const deviceLog = (event, details = {}) => {
  try {
    const safe = {};
    Object.entries(details || {}).forEach(([key, value]) => {
      if (!DEVICE_LOG_FIELDS.has(key) || value === undefined || value === null) return;
      safe[key] = key === "message" ? String(value).slice(0, 180) : value;
    });
    console.info(`[PilaTeacher/device] ${event}`, safe);
  } catch (e) {}
};
// Which device this is, for a sign-in failure that reproduces on one handset
// and not another. Model and OS come from the web view user agent; no
// identifier that could single out a person is read.
const authDeviceContext = () => {
  const agent = String(globalThis.navigator?.userAgent || "");
  const ios = /(?:iPhone|iPad|CPU) OS (\d+(?:[._]\d+)*)/.exec(agent);
  const android = /Android (\d+(?:\.\d+)*)/.exec(agent);
  return {
    appBuild: APP_BUILD_LABEL,
    platform: Capacitor.getPlatform(),
    osVersion: (ios?.[1] || android?.[1] || "").replace(/_/g, "."),
    deviceModel: /\b(iPad|iPhone|iPod)\b/.exec(agent)?.[1] || (Capacitor.getPlatform() === "android" ? "android" : "web"),
  };
};
const recordAuthStage = (stage, details = {}) => {
  const identity = details.error ? readAuthErrorIdentity(details.error) : {};
  const entry = appendAuthDiagnostic(stage, { ...authDeviceContext(), ...details, ...identity });
  deviceLog(`auth_stage_${entry.stage}`, {
    stage: entry.stage, provider: entry.provider, state: entry.outcome,
    domain: entry.errorDomain, code: entry.errorCode, message: entry.message,
    appBuild: entry.appBuild, model: entry.deviceModel,
    requestStartedAt: entry.requestStartedAt, requestEndedAt: entry.requestEndedAt,
    errorName: entry.errorName, userState: entry.userState, profileState: entry.profileState,
  });
  return entry;
};
/* The Auth initialization probe and the fetch wrapper both run before this
   module body; they buffer until this line hands them the recorder. */
connectAuthInitLog(recordAuthStage);
let authPreflightStarted = false;
const runAuthConnectivityPreflight = async ({ force = false } = {}) => {
  if (authPreflightStarted && !force) return readAuthDiagnostics().filter((entry) => entry.feature === AUTH_FEATURES.CONNECTIVITY);
  authPreflightStarted = true;
  const shared = { feature: AUTH_FEATURES.CONNECTIVITY, provider: "firebase" };
  recordAuthStage(AUTH_STAGES.PREFLIGHT_STARTED, shared);
  try {
    const records = await runAuthPreflight({ apiKey: fbAuthApiKey });
    return records.map((record) => recordAuthStage(record.stage, { ...shared, ...record }));
  } catch (error) {
    return [recordAuthStage(AUTH_STAGES.PREFLIGHT_STARTED, { ...shared, outcome: "failed", error })];
  }
};
