/* One record, rendered the same way on the login diagnostics panel and in the
   hidden lesson diagnostics. A field that is only legible on one of the two
   screens makes comparing two devices' logs pointless, so both screens render
   this component and the clipboard export uses the same summary line. */
function AuthDiagnosticRow({ entry }) {
  return (
    <div className="rounded-md px-2 py-1" style={{ backgroundColor: PAGE }}>
      <p className="break-all tabular-nums" style={{ fontSize: 9, lineHeight: 1.5, color: entry.outcome === "failed" ? BAD : SUB }}>{authDiagnosticSummary(entry)}</p>
      {(entry.errorDomain || entry.errorCode) && <p className="mt-0.5 break-all" style={{ fontSize: 9, lineHeight: 1.4, color: BAD }}>{entry.errorDomain || "domain 없음"} · {entry.errorCode || "code 없음"}</p>}
      {entry.message && <p className="mt-0.5 break-all" style={{ fontSize: 8, lineHeight: 1.4, color: SUB }}>{entry.message}</p>}
      <p className="mt-0.5 break-all" style={{ fontSize: 8, lineHeight: 1.4, color: SUB }}>{authDiagnosticDetail(entry)}</p>
    </div>
  );
}

function AuthDiagnosticsPanel({ onClose, onToast }) {
  const [entries, setEntries] = useState(() => readAuthDiagnostics());
  const [rechecking, setRechecking] = useState(false);
  const refresh = () => setEntries(readAuthDiagnostics());
  const connectivity = entries.filter((entry) => entry.feature === AUTH_FEATURES.CONNECTIVITY);
  const attempts = entries.filter((entry) => entry.feature !== AUTH_FEATURES.CONNECTIVITY);
  const failure = firstFailedAuthStage(attempts);
  const context = authDeviceContext();
  const asText = () => [
    `PilaTeacher 로그인 진단`,
    `${context.platform} ${context.osVersion} · ${context.deviceModel} · ${context.appBuild}`,
    ...entries.map((entry) => [
      authDiagnosticSummary(entry),
      entry.errorDomain,
      entry.errorCode,
      entry.message,
      authDiagnosticDetail(entry),
    ].filter(Boolean).join(" · ")),
  ].join("\n");
  const recheck = async () => {
    setRechecking(true);
    try { await runAuthConnectivityPreflight({ force: true }); refresh(); }
    finally { setRechecking(false); }
  };
  const copy = async () => {
    try { await navigator.clipboard.writeText(asText()); onToast?.({ ok: true, msg: "진단 내용을 복사했습니다." }); }
    catch (_error) { onToast?.({ ok: false, msg: "복사하지 못했습니다. 화면을 캡처해 주세요." }); }
  };
  return (
    <div role="dialog" aria-label="로그인 진단" className="fixed inset-0 z-50 overflow-y-auto safe-all" style={{ backgroundColor: PAGE }}>
      <div className="mx-auto w-full max-w-md px-5 py-6">
        <div className="flex items-center gap-3">
          <h2 className="min-w-0 flex-1 text-lg font-extrabold" style={{ color: INK }}>로그인 진단</h2>
          <button type="button" onClick={onClose} className="min-h-11 rounded-lg px-3 text-xs font-extrabold" style={{ backgroundColor: CARD, color: INK2, border: `1px solid ${LINE}` }}>닫기</button>
        </div>
        <p className="mt-1" style={{ fontSize: 11, lineHeight: 1.5, color: SUB }}>{context.platform} {context.osVersion} · {context.deviceModel} · {context.appBuild}</p>

        <section className="mt-4 rounded-xl p-3" style={{ backgroundColor: CARD, border: `1px solid ${LINE}` }}>
          <div className="flex items-center gap-2">
            <p className="min-w-0 flex-1 text-xs font-extrabold" style={{ color: INK }}>연결 점검</p>
            <button type="button" onClick={recheck} disabled={rechecking} className="min-h-11 shrink-0 rounded-lg px-3 text-[10px] font-extrabold disabled:opacity-40" style={{ backgroundColor: TINT, color: BRAND_D }}>{rechecking ? "점검 중" : "다시 점검"}</button>
          </div>
          {connectivity.length
            ? <div className="mt-2 space-y-1">{connectivity.map((entry, index) => <AuthDiagnosticRow key={`${entry.at}-${index}`} entry={entry} />)}</div>
            : <p className="mt-2" style={{ fontSize: 10, color: SUB }}>점검 기록 없음 · [다시 점검]을 눌러 주세요</p>}
        </section>

        <section className="mt-3 rounded-xl p-3" style={{ backgroundColor: CARD, border: `1px solid ${LINE}` }}>
          <p className="text-xs font-extrabold" style={{ color: INK }}>최근 로그인 시도</p>
          {failure
            ? <p className="mt-1 break-all" style={{ fontSize: 10, lineHeight: 1.5, color: BAD }}>최초 실패 단계: {failure.stage} · {failure.errorDomain || "domain 없음"} · {failure.errorCode || "code 없음"}</p>
            : <p className="mt-1" style={{ fontSize: 10, color: SUB }}>실패한 단계 없음</p>}
          <div className="mt-2 space-y-1">{attempts.map((entry, index) => <AuthDiagnosticRow key={`${entry.at}-${index}`} entry={entry} />)}</div>
          {!attempts.length && <p className="mt-1" style={{ fontSize: 10, color: SUB }}>로그인 시도 기록 없음</p>}
        </section>

        <div className="mt-3 grid grid-cols-2 gap-2">
          <button type="button" onClick={copy} className="h-11 rounded-lg text-xs font-extrabold text-white" style={{ backgroundColor: BRAND }}>내용 복사</button>
          <button type="button" onClick={() => { clearAuthDiagnostics(); refresh(); }} className="h-11 rounded-lg text-xs font-extrabold" style={{ backgroundColor: CARD, color: BAD, border: `1px solid ${LINE}` }}>기록 비우기</button>
        </div>
        <p className="mt-2" style={{ fontSize: 9, lineHeight: 1.5, color: SUB }}>단계·오류 코드·소요 시간만 기록합니다. 이메일·비밀번호·토큰은 저장하지 않습니다.</p>
      </div>
    </div>
  );
}

function AuthScreen({ accounts, onLogin, onSignup, onToast }) {
  const [mode, setMode] = useState("main");
  const [emailTab, setEmailTab] = useState("login");
  const [auto, setAuto] = useState(true);
  const [signup, setSignup] = useState(null);
  const [f, setF] = useState({ name: "", email: "", pw: "", center: "", phone: "" });

  const [busy, setBusy] = useState("");
  const [diagnosticTaps, setDiagnosticTaps] = useState(0);
  const [diagnosticsOpen, setDiagnosticsOpen] = useState(false);
  const socialGateRef = useRef(null);
  if (!socialGateRef.current) socialGateRef.current = createSingleFlightGate();
  const handleSocial = async (provider) => {
    if (fbReady) {
      if (provider !== "google" && provider !== "apple") {
        onToast({ ok: false, msg: "지금은 Google \u00b7 Apple \u00b7 \uc774\uba54\uc77c\ub85c\ub9cc \ub85c\uadf8\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4." });
        return;
      }
      if (socialGateRef.current.busy) return;
      setBusy(provider);
      const correlationId = `auth_${provider}_${Date.now().toString(36)}`;
      const stage = (name, details = {}) => recordAuthStage(name, { provider, correlationId, ...details });
      stage(AUTH_STAGES.LOGIN_START);
      try {
        await socialGateRef.current.run(async () => {
          const u = await fbSignInSocial(provider, { onStage: stage });
          stage(AUTH_STAGES.PROFILE_LOAD_STARTED);
          const profileResult = await fbLoadProfileState(u.id);
          if (profileResult.status === "error") {
            stage(AUTH_STAGES.PROFILE_LOAD_FAILED, { outcome: "failed", error: profileResult.error });
            throw profileResult.error;
          }
          const prof = profileResult.profile;
          stage(AUTH_STAGES.PROFILE_LOAD_SUCCEEDED, { outcome: "succeeded", profileState: profileResult.status });
          if (prof && prof.center) onLogin({ ...u, ...prof, id: u.id }, auto);
          else setSignup({ ...u, provider, center: "", phone: "", fb: true });
        });
      } catch (e) {
        const diagnostic = safeAuthDiagnostic(e, { provider, stage: e?.authStage || "sign_in" });
        deviceLog("auth_sign_in_failed", diagnostic);
        const kind = classifyAuthError(e);
        // A cancelled sheet is not a failure: record it as its own outcome and
        // leave the login screen exactly as it was.
        if (kind === "cancelled") {
          stage(AUTH_STAGES.LOGIN_CANCELLED, { outcome: "cancelled", error: e });
        } else {
          const failure = stage(AUTH_STAGES.LOGIN_FAILED, { outcome: "failed", error: e });
          const label = provider === "apple" ? "Apple" : "Google";
          const message = kind === "network"
            ? "네트워크 연결을 확인한 뒤 다시 시도해 주세요."
            : kind === "configuration"
              ? `${label} 로그인 설정을 확인할 수 없습니다. 잠시 뒤 다시 시도해 주세요.`
              : kind === "credential"
                ? "로그인 정보가 만료되었거나 유효하지 않습니다. 다시 로그인해 주세요."
                // An unclassified failure still has to be traceable from the
                // device, so it carries the code the failing layer produced.
                : `${label} 로그인을 완료하지 못했습니다 (코드 ${failure.errorCode || "unknown"}).`;
          onToast({ ok: false, msg: message });
        }
      } finally {
        setBusy("");
      }
      return;
    }
    const exist = accounts.find((a) => a.provider === provider);
    if (exist) { onLogin(exist, auto); return; }
    setSignup({ provider, name: "", email: "", center: "", phone: "" });
  };

  return (
    <div className="min-h-screen" style={{ background: SPLASH_BG }}>
      <div className="mx-auto flex min-h-screen max-w-md flex-col px-6 pb-8 pt-16">
        <div className="flex flex-col items-center">
          <Logo size={88} />
          <h1 className="mt-5 text-3xl font-extrabold" style={{ color: INK, letterSpacing: "-0.04em" }}>필라티쳐</h1>
          <p className="mt-2 text-sm font-extrabold" style={{ color: PRIMARY }}>강사를 위한 전문 회원 관리</p>
          <p className="mt-1 text-xs" style={{ color: SUB }}>수업 · 체형 변화 · 재등록을 한 화면에서</p>
        </div>

        <div className="mt-10 flex-1">
          {mode === "main" ? (
            <div className="space-y-2">
              {PROVIDERS.filter((p) => Capacitor.getPlatform() !== "ios" || p.key !== "google").map((p) => (
                <button key={p.key} onClick={() => handleSocial(p.key)} disabled={!!busy} aria-busy={busy === p.key}
                  className="flex w-full items-center justify-center gap-2 rounded-2xl py-3.5 text-sm font-extrabold disabled:cursor-not-allowed disabled:opacity-55"
                  style={{ backgroundColor: p.bg, color: p.fg, border: p.border ? `1px solid ${p.border}` : "none" }}>
                  {busy === p.key ? <Loader2 size={15} className="animate-spin" /> : null}{p.label}
                </button>
              ))}
              <div className="flex items-center gap-3 py-3">
                <div className="h-px flex-1" style={{ backgroundColor: LINE }} />
                <span className="text-xs font-bold" style={{ color: SUB }}>또는</span>
                <div className="h-px flex-1" style={{ backgroundColor: LINE }} />
              </div>
              <button onClick={() => setMode("email")} disabled={busy}
                className="flex w-full items-center justify-center gap-2 rounded-2xl py-3.5 text-sm font-extrabold"
                style={{ backgroundColor: CANVAS, color: INK }}>
                <Mail size={16} /> 이메일로 시작하기
              </button>
            </div>
          ) : (
            <div>
              <div className="flex gap-1 rounded-2xl p-1" style={{ backgroundColor: CANVAS }}>
                {[{ k: "login", l: "로그인" }, { k: "signup", l: "회원가입" }].map((t) => (
                  <button key={t.k} onClick={() => setEmailTab(t.k)} className="flex-1 rounded-xl py-2.5 text-sm font-bold"
                    style={emailTab === t.k ? { backgroundColor: CARD, color: PRIMARY, boxShadow: "0 1px 3px rgba(20,20,43,.12)" } : { color: SUB }}>{t.l}</button>
                ))}
              </div>
              <div className="mt-4 space-y-3">
                {emailTab === "signup" && (
                  <>
                    <Field label="강사 이름"><input value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} placeholder="예) 박서연" className={inputCls} /></Field>
                    <Field label="센터명"><input value={f.center} onChange={(e) => setF({ ...f, center: e.target.value })} placeholder="예) 필라티쳐 강남점" className={inputCls} /></Field>
                    <Field label="연락처" hint="선택"><input value={f.phone} onChange={(e) => setF({ ...f, phone: e.target.value })} placeholder="010-" className={inputCls} /></Field>
                  </>
                )}
                <Field label="이메일"><input value={f.email} onChange={(e) => setF({ ...f, email: e.target.value })} placeholder="teacher@studio.com" className={inputCls} /></Field>
                <Field label="비밀번호"><input type="password" value={f.pw} onChange={(e) => setF({ ...f, pw: e.target.value })} placeholder="6자 이상" className={inputCls} /></Field>
                <PrimaryBtn
                  disabled={busy || (emailTab === "signup" ? !(f.name && f.email && f.pw.length >= 6 && f.center) : !(f.email && f.pw))}
                  onClick={async () => {
                    if (fbReady) {
                      setBusy("email");
                      const emailCorrelationId = `auth_email_${Date.now().toString(36)}`;
                      try {
                        const emailStage = (name, details = {}) => recordAuthStage(name, { feature: AUTH_FEATURES.EMAIL_SIGN_IN, provider: "email", correlationId: emailCorrelationId, ...details });
                        if (emailTab === "signup") {
                          const u = await fbSignUpEmail(f.email, f.pw, f.name, { onStage: emailStage });
                          onSignup({ ...u, provider: "email", name: f.name, email: f.email, center: f.center, phone: f.phone, fb: true }, auto);
                        } else {
                          const u = await fbSignInEmail(f.email, f.pw, { onStage: emailStage });
                          emailStage(AUTH_STAGES.PROFILE_LOAD_STARTED);
                          const profileResult = await fbLoadProfileState(u.id);
                          if (profileResult.status === "error") {
                            emailStage(AUTH_STAGES.PROFILE_LOAD_FAILED, { outcome: "failed", error: profileResult.error });
                            throw profileResult.error;
                          }
                          const prof = profileResult.profile;
                          emailStage(AUTH_STAGES.PROFILE_LOAD_SUCCEEDED, { outcome: "succeeded", profileState: profileResult.status });
                          if (prof && prof.center) onLogin({ ...u, ...prof, id: u.id }, auto);
                          else setSignup({ ...u, provider: "email", center: "", phone: "", fb: true });
                        }
                      } catch (e) {
                        const c = (e && e.code) || "";
                        recordAuthStage(AUTH_STAGES.LOGIN_FAILED, { feature: AUTH_FEATURES.EMAIL_SIGN_IN, provider: "email", correlationId: emailCorrelationId, outcome: "failed", error: e });
                        onToast({ ok: false, msg:
                          c === "auth/operation-timeout" ? "로그인 서버 응답이 늦어 중단했습니다. 앱 버전을 7번 눌러 진단을 확인해 주세요."
                          : c === "auth/network-request-failed" ? "네트워크 연결을 확인한 뒤 다시 시도해 주세요."
                          : c === "auth/email-already-in-use" ? "\uc774\ubbf8 \uac00\uc785\ub41c \uc774\uba54\uc77c\uc785\ub2c8\ub2e4."
                          : c === "auth/weak-password" ? "\ube44\ubc00\ubc88\ud638\ub97c 6\uc790 \uc774\uc0c1\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \uc8fc\uc138\uc694."
                          : c === "auth/invalid-email" ? "\uc774\uba54\uc77c \ud615\uc2dd\uc774 \uc62c\ubc14\ub974\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."
                          : "\uc774\uba54\uc77c \ub610\ub294 \ube44\ubc00\ubc88\ud638\uac00 \ub9de\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4." });
                      } finally {
                        setBusy("");
                      }
                      return;
                    }
                    if (emailTab === "signup") {
                      if (accounts.some((a) => a.email === f.email)) { onToast({ ok: false, msg: "이미 가입된 이메일입니다." }); return; }
                      onSignup({ provider: "email", name: f.name, email: f.email, pw: f.pw, center: f.center, phone: f.phone }, auto);
                    } else {
                      const acc = accounts.find((a) => a.email === f.email && a.pw === f.pw);
                      if (!acc) { onToast({ ok: false, msg: "이메일 또는 비밀번호가 맞지 않습니다." }); return; }
                      onLogin(acc, auto);
                    }
                  }}>
                  {emailTab === "signup" ? "가입하고 시작하기" : "로그인"}
                </PrimaryBtn>
                <button onClick={() => setMode("main")} className="w-full py-2 text-xs font-bold" style={{ color: SUB }}>다른 방법으로 로그인</button>
              </div>
            </div>
          )}

          <button onClick={() => setAuto((v) => !v)} className="mt-5 flex w-full items-center gap-2">
            <span className="flex h-5 w-5 items-center justify-center rounded-md"
              style={auto ? { backgroundColor: BRAND } : { backgroundColor: CARD, border: `1px solid ${LINE}` }}>
              {auto && <Check size={13} color="#fff" />}
            </span>
            <span className="text-sm font-bold" style={{ color: INK }}>자동 로그인</span>
            <span className="ml-auto text-xs" style={{ color: SUB }}>다음부터 바로 시작합니다</span>
          </button>

          {!fbReady && accounts.length > 0 && (
            <div className="mt-6">
              <Sub>최근 로그인</Sub>
              <div className="mt-2 flex flex-wrap gap-1.5">
                {accounts.map((a) => (
                  <button key={a.id} onClick={() => onLogin(a, auto)} className="flex items-center gap-1.5 rounded-full py-2 pl-2 pr-3" style={{ backgroundColor: CARD, boxShadow: SHADOW }}>
                    <Avatar src={a.photo} name={a.name} size={24} radius={12} />
                    <span className="text-xs font-bold" style={{ color: INK }}>{a.name}</span>
                    <span className="text-xs" style={{ color: SUB }}>{PROVIDER_LABEL[a.provider]}</span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <p className="text-center text-xs leading-relaxed" style={{ color: FAINT }}>
          로그인 정보와 회원·수업 기록은 클라우드에 안전하게 백업됩니다. 음성은 기록 정리를 위해 서버로 전송된 뒤 즉시 삭제되며 보관하지 않습니다. 체형 사진은 이 기기에만 저장됩니다.<br />
          로그인하면 이용약관 및 개인정보 처리방침에 동의하게 됩니다.
        </p>
        <button type="button" aria-label="앱 버전"
          onClick={() => { const next = diagnosticTaps + 1; setDiagnosticTaps(next); if (next >= 7) { setDiagnosticTaps(0); setDiagnosticsOpen(true); } }}
          className="mt-3 w-full text-center tabular-nums" style={{ fontSize: 10, color: FAINT }}><RuntimeBuildLabel /></button>
      </div>

      {diagnosticsOpen && <AuthDiagnosticsPanel onClose={() => setDiagnosticsOpen(false)} onToast={onToast} />}

      {signup && (
        <Sheet title={`${PROVIDER_LABEL[signup.provider]} 계정으로 가입`} onClose={() => setSignup(null)}>
          <div className="space-y-3">
            <Sub>처음 로그인이라 강사 정보를 등록합니다. 여기 입력한 내용이 앱 안에 그대로 표시됩니다.</Sub>
            <Field label="강사 이름"><input value={signup.name} onChange={(e) => setSignup({ ...signup, name: e.target.value })} placeholder="예) 박서연" className={inputCls} /></Field>
            <Field label="센터명"><input value={signup.center} onChange={(e) => setSignup({ ...signup, center: e.target.value })} placeholder="예) 필라티쳐 강남점" className={inputCls} /></Field>
            <div className="grid grid-cols-2 gap-2">
              <Field label="이메일"><input value={signup.email} onChange={(e) => setSignup({ ...signup, email: e.target.value })} placeholder="teacher@studio.com" className={inputCls} disabled={!!signup.fb} /></Field>
              <Field label="연락처" hint="선택"><input value={signup.phone} onChange={(e) => setSignup({ ...signup, phone: e.target.value })} placeholder="010-" className={inputCls} /></Field>
            </div>
            <PrimaryBtn disabled={!(signup.name && signup.center)} onClick={() => onSignup(signup, auto)}>가입하고 시작하기</PrimaryBtn>
          </div>
        </Sheet>
      )}
    </div>
  );
}
function Header({ settings, account, alertCount, onProfile, onAlerts }) {
  return (
    <header className="bg-white" style={{ borderBottom: `1px solid ${LINE}` }}>
      <div className="pt-header-inner mx-auto flex items-center gap-2.5 px-3" style={{ height: 44 }}>
        <Logo size={26} radius={0.24} />
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm font-extrabold" style={{ color: INK, maxWidth: "100%" }}>{settings.center || "필라티쳐"}</p>
          <Sub className="truncate">{account?.name ? `${account.name} 강사` : "체형 변화 · 재등록 관리"}</Sub>
        </div>
        {alertCount > 0 && (
          <button onClick={onAlerts} aria-label={`재등록 상담이 필요한 회원 ${alertCount}명 보기`}
            className="flex shrink-0 items-center gap-1 rounded-full px-2.5 py-1.5 text-xs font-extrabold" style={{ backgroundColor: BAD_S, color: BAD }}>
            <Bell size={13} /> 재등록 {alertCount}
          </button>
        )}
        <button onClick={onProfile} className="shrink-0" aria-label="내 프로필">
          <Avatar src={account?.photo} name={account?.name} size={30} radius={10} ring />
        </button>
      </div>
    </header>
  );
}
function Tabs({ tab, setTab }) {
  const items = [
    { key: "schedule", label: "일정", icon: Calendar }, { key: "members", label: "회원", icon: Users },
    { key: "analysis", label: "체형분석", icon: Activity }, { key: "settings", label: "더보기", icon: SettingsIcon },
  ];
  return (
    <nav className="safe-tab z-40 flex shrink-0" aria-label="주요 메뉴"
      style={{ height: 49, boxSizing: "content-box", borderTop: `1px solid ${LINE}`, backgroundColor: CARD }}>
      <div className="flex h-[49px] w-full items-center">
        {items.map((it) => {
          const on = tab === it.key, Icon = it.icon;
          return (
            <button key={it.key} type="button" aria-current={on ? "page" : undefined} onClick={() => setTab(it.key)} className="relative flex h-[49px] flex-1 flex-col items-center justify-center gap-0.5 text-[10px] font-medium"
              style={{ color: on ? BRAND : SUB }}>
              <span className="relative flex items-center justify-center">
                <Icon size={20} strokeWidth={on ? 2.2 : 1.7} />
                {on && <span aria-hidden="true" className="absolute" style={{ bottom: -3, width: 18, height: 2, borderRadius: 1, backgroundColor: BRAND }} />}
              </span>
              <span style={{ fontWeight: on ? 700 : 500 }}>{it.label}</span>
            </button>
          );
        })}
      </div>
    </nav>
  );
}

/* 알림을 미뤄둔 회원 — 그 날짜까지 골든타임에서 숨긴다 */
const isSnoozed = (m) => !!(m?.snoozeUntil && dday(m.snoozeUntil) > 0);

/* 수강권 흔적이 하나라도 있으면 '등록한 적 있는 회원' */
const everRegistered = (m) => !!(
  (m?.passName && String(m.passName).trim()) ||
  left(m) > 0 ||
  (m?.payments || []).length > 0 ||
  num(m?.total) > 0 ||
  (m?.contractEnd && String(m.contractEnd).trim())
);

/* 잔여가 다 떨어진 회원 — 재등록 상담이 이미 지났거나 종료 처리가 필요한 사람 */
function spentMembers(members, schedule) {
  return members.filter((m) => {
    if (isEnded(m) || isHold(m)) return false;
    if (left(m) > 0) return false;
    if (!everRegistered(m) && !attendanceOf(schedule, m.id).done) return false;
    return true;
  });
}
function detectAlerts(members, schedule) {
  const out = [];
  members.forEach((m) => {
    if (isEnded(m)) return;
    if (isSnoozed(m)) return;
    const att = attendanceOf(schedule, m.id);
    /* 등록 이력도 출석 기록도 없는 빈 회원은 재등록 대상이 아니다 */
    if (!everRegistered(m) && !att.done) return;
    if (isHold(m)) {
      const d = ddaySafe(m.holdUntil);
      if (d !== null && d <= 3)
        out.push({ member: m, kind: "return", rest: left(m), d, att, reasons: [d < 0 ? `수업 재개 예정 ${Math.abs(d)}일 경과` : `수업 재개 D-${d}`], urgency: 25 + Math.max(0, 3 - d) });
      return;
    }
    const rest = left(m);
    /* 잔여가 0이면 이미 소진된 상태 — 골든타임(소진 전에 잡는 알림)에서는 뺀다.
       대신 아래 spent 로 따로 세어 '정리 필요'로 보여 준다. */
    if (rest <= 0) return;
    const d = ddaySafe(m.contractEnd);
    const pc = paceOf(schedule, m);
    const pace = pc.use;
    const wks = rest > 0 ? rest / pace : 0;
    const reasons = [];
    if (rest > 0 && wks <= 4) reasons.push(`${pc.short && pc.done ? `${pc.days}일 기준` : "주"} ${pace.toFixed(1)}회 · 약 ${Math.max(1, Math.round(wks))}주 뒤 소진`);
    if (rest < 10) reasons.push(`잔여 ${rest}회`);
    if (d !== null && d < 30) reasons.push(d < 0 ? `만료 ${Math.abs(d)}일 경과` : `만료 D-${d}`);
    if (!reasons.length) return;
    const urgency = (10 - Math.min(rest, 10)) * 3 + (d !== null ? Math.max(0, 30 - d) / 2 : 0) + (wks ? Math.max(0, 4 - wks) * 6 : 0);
    out.push({ member: m, kind: "renew", rest, d, wks, pace, pc, reasons, att, urgency });
  });
  return out.sort((a, b) => b.urgency - a.urgency);
}
function AlertCenter({ alerts, spent, onOpenMember, onBrief, onSnooze, snoozedCount, onUnsnoozeAll }) {
  const [open, setOpen] = useState(false);
  const spentN = (spent || []).length;
  if (!alerts.length && !snoozedCount && !spentN) return null;
  return (
    <section className="mb-3 overflow-hidden rounded-3xl" style={{ background: `linear-gradient(150deg, ${BAD_S} 0%, ${CARD} 55%)`, border: `1px solid ${LINE}`, boxShadow: SHADOW }}>
      <button onClick={() => setOpen((v) => !v)} className="flex w-full items-center gap-2 px-4 py-3.5 text-left">
        <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-xl" style={{ backgroundColor: BAD_S }}><Bell size={16} style={{ color: BAD }} /></span>
        <div className="min-w-0 flex-1">
          <h3 className="text-sm font-extrabold" style={{ color: INK }}>재등록 골든타임</h3>
          <Sub className="truncate">{alerts.length ? `지금 연락해야 할 회원 ${alerts.length}명` : spentN ? `잔여를 다 쓴 회원 ${spentN}명` : "지금 연락할 회원은 없습니다"}</Sub>
        </div>
        {alerts.length > 0 && !open && (
          <span className="shrink-0 rounded-full px-2.5 py-1 text-xs font-extrabold" style={{ backgroundColor: BAD_S, color: BAD }}>{alerts.length}</span>
        )}
        <span className="shrink-0 text-xs font-extrabold" style={{ color: PRIMARY }}>{open ? "접기" : "보기"}</span>
        <ChevronRight size={16} className="shrink-0" style={{ color: PRIMARY, transform: open ? "rotate(90deg)" : "none", transition: "transform .18s ease" }} />
      </button>
      {open && spentN > 0 && (
        <div className="px-4 pb-3">
          <div className="rounded-2xl p-3" style={{ backgroundColor: CANVAS }}>
            <p className="text-xs font-extrabold" style={{ color: INK }}>잔여를 다 쓴 회원 {spentN}명</p>
            <Sub className="mt-0.5 block">재등록을 했거나, 더 안 나오면 종료로 바꿔 주세요</Sub>
            <div className="mt-2 flex flex-wrap gap-1.5">
              {(spent || []).slice(0, 12).map((m) => (
                <button key={m.id} onClick={() => onOpenMember(m.id)} className="rounded-full bg-white px-2.5 py-1.5 text-xs font-bold" style={{ color: INK }}>
                  {m.name || "이름 미입력"}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
      {snoozedCount > 0 && (
        <div className="flex items-center gap-2 px-4 pb-3">
          <Sub className="min-w-0 flex-1">알림을 미뤄둔 회원 {snoozedCount}명</Sub>
          <button onClick={onUnsnoozeAll} className="shrink-0 rounded-full bg-white px-3 py-1.5 text-xs font-extrabold" style={{ color: PRIMARY }}>다시 보기</button>
        </div>
      )}
      {open && alerts.length > 0 && (
        <div className="flex gap-3 overflow-x-auto px-4 pb-4">
          {alerts.map((a) => {
            const urgent = a.rest <= 3;
            return (
              <div key={a.member.id} className="w-64 shrink-0 rounded-2xl p-4" style={{ backgroundColor: CANVAS }}>
                <div className="flex items-center gap-2">
                  <button onClick={() => onOpenMember(a.member.id)} className="text-sm font-extrabold" style={{ color: INK }}>{a.member.name || "이름 미입력"}</button>
                  <span className="rounded-full px-2 py-0.5 text-xs font-extrabold" style={{ backgroundColor: urgent ? BAD_S : WARN_S, color: urgent ? BAD : WARN }}>{a.reasons[0]}</span>
                </div>
                <div className="mt-2 flex items-end gap-3">
                  <div><Sub>잔여</Sub><p className="text-2xl font-extrabold tabular-nums" style={{ color: urgent ? BAD : INK }}>{a.rest}회</p></div>
                  {a.d !== null && <div><Sub>만료</Sub><p className="text-2xl font-extrabold tabular-nums" style={{ color: a.d <= 7 ? BAD : INK }}>{a.d < 0 ? `+${Math.abs(a.d)}` : `D-${a.d}`}</p></div>}
                  {a.kind === "renew" && a.wks > 0 && <div><Sub>소진예상</Sub><p className="text-2xl font-extrabold tabular-nums" style={{ color: a.wks <= 4 ? BAD : INK }}>{Math.max(1, Math.round(a.wks))}주</p></div>}
                </div>
                <Sub className="mt-1 truncate">{a.member.passName || "수강권 미입력"} · {a.member.instructor}</Sub>
                <button onClick={() => onBrief(a)} className="mt-3 flex w-full items-center justify-center gap-1.5 rounded-xl py-2.5 text-xs font-extrabold text-white" style={{ backgroundColor: BRAND }}>
                  <Sparkles size={13} /> AI 재등록 브리핑 생성
                </button>
                <div className="mt-1.5 flex gap-1.5">
                  {[7, 30].map((n) => (
                    <button key={n} onClick={() => onSnooze && onSnooze(a.member.id, n)}
                      className="flex-1 rounded-xl bg-white py-2 text-xs font-bold" style={{ color: SUB }}>{n}일 숨기기</button>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </section>
  );
}
function SalesBriefModal({ alert, onClose, onToast }) {
  const { member, rest, d, att } = alert;
  const r = useMemo(() => buildReview(member), [member]);
  const [text, setText] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let alive = true;
    (async () => {
      if (aiProvider.getStatus().status !== "connected") {
        if (alive) { setError("AI 상담 문장을 사용할 수 없습니다"); setLoading(false); }
        return;
      }
      try {
        const consent = await ensureMemberAIConsent(member.id, "generateReport");
        if (!alive) return;
        if (!consent.ok) { setError(consent.message); return; }
        const result = await aiProvider.generateReport(buildReportInput({ reportType: "renewal_consultation", memberId: member.id, memberName: member.name, source: { goal: member.goal, remainingLessons: rest, expiryDays: d, attendance: att, bodyComposition: r?.rows, performance: member.perf || [] } }));
        if (alive && result.status === AI_STATUSES.DRAFT) setText(formatAIReport(result.output));
        else if (alive) setError("AI 상담 문장을 사용할 수 없습니다");
      } catch (e) { if (alive) setError(aiFailureMessage(e, "AI 브리핑을 불러오지 못했습니다.")); }
      finally { if (alive) setLoading(false); }
    })();
    return () => { alive = false; };
  }, [member.id]);

  return (
    <Sheet title={`${member.name} 재등록 브리핑`} onClose={onClose}>
      <div className="grid grid-cols-3 gap-2">
        {[{ l: "잔여", v: `${rest}회`, c: rest <= 3 ? BAD : INK },
          { l: "만료", v: d === null ? "-" : d < 0 ? `+${Math.abs(d)}일` : `D-${d}`, c: d !== null && d <= 7 ? BAD : INK },
          { l: "출석률", v: att.rate === null ? "-" : `${att.rate}%`, c: INK }].map((x) => (
          <div key={x.l} className="rounded-2xl p-3 text-center" style={{ backgroundColor: CANVAS }}>
            <Sub>{x.l}</Sub><p className="text-lg font-extrabold tabular-nums" style={{ color: x.c }}>{x.v}</p>
          </div>
        ))}
      </div>
      {r && (
        <div className="mt-3 grid grid-cols-3 gap-2 rounded-2xl p-3" style={{ backgroundColor: CANVAS }}>
          {r.rows.map((x) => (
            <div key={x.key} className="text-center">
              <Sub>{x.label}</Sub>
              <p className="text-sm font-extrabold tabular-nums" style={{ color: INK }}>{x.from} → {x.to}</p>
              <p className="text-xs font-bold" style={{ color: toneColor(x.tone) }}>{x.diff > 0 ? "+" : ""}{x.diff}{uLabel(x.key)}</p>
            </div>
          ))}
        </div>
      )}
      <div className="mt-3 rounded-2xl p-4" style={{ backgroundColor: TINT }}>
        <p className="text-xs font-extrabold" style={{ color: PRIMARY }}>상담 멘트</p>
        {loading ? <p className="mt-2 flex items-center gap-2 text-sm" style={{ color: SUB }}><Loader2 size={14} className="animate-spin" /> 회원 데이터를 분석하는 중…</p>
          : error ? <p className="mt-2 text-sm font-bold" style={{ color: WARN }}>{error}. 저장된 기록은 그대로 확인할 수 있습니다.</p>
            : <p className="mt-2 whitespace-pre-line text-sm leading-relaxed" style={{ color: INK }}>{text}</p>}
      </div>
      <div className="mt-3 flex gap-2">
        <button disabled={loading || !text} onClick={async () => {
          try { await navigator.clipboard.writeText(text); onToast({ ok: true, msg: "멘트를 복사했습니다." }); }
          catch (e) { onToast({ ok: false, msg: "복사하지 못했습니다." }); }
        }} className="flex flex-1 items-center justify-center gap-1.5 rounded-2xl py-3 text-sm font-extrabold text-white disabled:opacity-40" style={{ backgroundColor: BRAND }}>
          <Copy size={14} /> 멘트 복사
        </button>
        <button onClick={onClose} className="rounded-2xl px-5 py-3 text-sm font-bold" style={{ backgroundColor: CANVAS, color: SUB }}>닫기</button>
      </div>
    </Sheet>
  );
}
function SchedAttendeeRow({ s, a, members, onStatus, onNoshowFee }) {
  const m = members.find((x) => x.id === a.memberId);
  const nm = m?.name || "삭제된 회원";
  const st = stOf(a.status);
  return (
    <div className="rounded-xl bg-white p-2.5">
      <div className="flex items-center gap-2">
        <span className="min-w-0 flex-1 truncate text-sm font-extrabold" style={{ color: INK }}>{nm}</span>
        {m && (left(m) > 0
          ? <Sub>잔여 {left(m)}회</Sub>
          : <span className="rounded-full px-2 py-0.5 text-xs font-extrabold" style={{ backgroundColor: BAD_S, color: BAD }}>잔여 0</span>)}
        <span className="rounded-full px-2 py-0.5 text-xs font-extrabold" style={{ backgroundColor: st.bg, color: st.color }}>{st.label}</span>
      </div>
      <div className="mt-1.5 flex flex-wrap gap-1.5">
        {a.status !== "done"
          ? <button onClick={() => onStatus(s.id, "done", a.memberId)} className="rounded-full px-2.5 py-1 text-xs font-extrabold text-white" style={{ backgroundColor: GOOD }}>출석</button>
          : <button onClick={() => onStatus(s.id, "booked", a.memberId)} className="rounded-full px-2.5 py-1 text-xs font-bold" style={{ backgroundColor: CANVAS, color: SUB }}>출석 취소</button>}
        {a.status !== "noshow" && <button onClick={() => onStatus(s.id, "noshow", a.memberId)} className="rounded-full px-2.5 py-1 text-xs font-bold" style={{ backgroundColor: CANVAS, color: BAD }}>노쇼</button>}
        {a.status !== "cancel" && <button onClick={() => onStatus(s.id, "cancel", a.memberId)} className="rounded-full px-2.5 py-1 text-xs font-bold" style={{ backgroundColor: CANVAS, color: SUB }}>수업 취소</button>}
        {a.deductFrom && <span className="self-center text-xs font-bold" style={{ color: SUB }}>{a.deductFrom} −1회</span>}
      </div>
      {a.status === "noshow" && (
        <div className="mt-1.5 flex flex-wrap items-center gap-1.5 rounded-lg p-2" style={{ backgroundColor: BAD_S }}>
          {a.noshowFee == null ? (
            <>
              <span className="text-xs font-bold" style={{ color: INK }}>노쇼 차감할까요?</span>
              <button onClick={() => onNoshowFee(s.id, true, a.memberId)} className="rounded-full px-2.5 py-1 text-xs font-extrabold text-white" style={{ backgroundColor: BAD }}>1회 차감</button>
              <button onClick={() => onNoshowFee(s.id, false, a.memberId)} className="rounded-full bg-white px-2.5 py-1 text-xs font-bold" style={{ color: SUB }}>다음으로</button>
            </>
          ) : a.noshowFee ? (
            <>
              <span className="rounded-full px-2 py-0.5 text-xs font-extrabold" style={{ backgroundColor: CARD, color: BAD }}>{a.deductFrom || "정규"} 1회 차감됨</span>
              <button onClick={() => onNoshowFee(s.id, false, a.memberId)} className="text-xs font-bold" style={{ color: SUB }}>차감 취소</button>
            </>
          ) : (
            <>
              <span className="text-xs font-bold" style={{ color: SUB }}>차감 없이 기록</span>
              <button onClick={() => onNoshowFee(s.id, true, a.memberId)} className="text-xs font-extrabold" style={{ color: BAD }}>1회 차감하기</button>
            </>
          )}
        </div>
      )}
    </div>
  );
}

/* 일간·주간·월간 목록용 한 줄 요약 — 출석 처리는 '오늘 수업' 에서만 한다 */
function SchedLine({ s, members, onEdit }) {
  const nameOf = (id) => members.find((m) => m.id === id)?.name || "삭제된 회원";
  const pv = isPersonalEvt(s);
  const list = attendeesOf(s);
  const eq = isEquipGroup(s);
  const settled = pv ? true : eq ? !!s.groupDone || !!s.groupCancelled : list.length > 0 && list.every((a) => a.status !== "booked");
  const st = pv ? { label: "내 일정", color: MINT, bg: CANVAS }
    : eq ? (s.groupCancelled ? { label: "취소", color: BAD, bg: BAD_S } : s.groupDone ? { label: "완료", color: GOOD, bg: GOOD_S } : { label: "예정", color: PRIMARY, bg: TINT })
    : list.length > 1 ? { label: `${list.filter((a) => a.status === "done").length}/${list.length} 출석`, color: settled ? GOOD : PRIMARY, bg: settled ? GOOD_S : TINT }
    : stOf(list[0]?.status);
  const edge = pv ? MINT : s.groupCancelled ? BAD : settled ? GOOD : PRIMARY;
  const title = pv ? (s.title || "내 일정") : eq
    ? `${s.equip || "기구"} 그룹 · ${num(s.groupCount) > 0 ? `예정 ${num(s.groupCount)}명` : "인원 미입력"}`
    : list.map((a) => nameOf(a.memberId)).join(", ") || "회원 없음";
  return (
    <button onClick={() => onEdit(s)} className="flex w-full items-center gap-2 rounded-xl px-2.5 py-2 text-left"
      style={{ backgroundColor: settled ? CANVAS : CARD, borderLeft: `4px solid ${edge}`, border: `1px solid ${settled ? "transparent" : LINE}`, borderLeftWidth: 4, borderLeftColor: edge, opacity: settled ? 0.72 : 1 }}>
      <span className="w-11 shrink-0 text-xs font-extrabold tabular-nums" style={{ color: settled ? SUB : edge }}>{s.start}</span>
      <span className="min-w-0 flex-1 truncate text-sm font-extrabold" style={{ color: INK, textDecoration: st.label === "취소" ? "line-through" : "none" }}>{title}</span>
      <span className="hidden shrink-0 text-xs sm:inline" style={{ color: SUB }}>{pv ? "" : eq ? "그룹" : s.type}</span>
      <span className="shrink-0 rounded-full px-2 py-0.5 text-xs font-extrabold" style={{ backgroundColor: st.bg, color: st.color }}>{st.label}</span>
      <Pencil size={12} className="shrink-0" style={{ color: FAINT }} />
    </button>
  );
}

function SchedItem({ s, members, del, setDel, setEditing, onStatus, onNoshowFee, onGroupDone, onDelete }) {
  const nameOf = (id) => members.find((m) => m.id === id)?.name || "삭제된 회원";
  if (isPersonalEvt(s)) return (
    <div className="rounded-2xl p-3" style={{ backgroundColor: CANVAS, borderLeft: `4px solid ${MINT}` }}>
      <div className="flex items-center gap-2">
        <div className="w-14 shrink-0">
          <p className="text-sm font-extrabold tabular-nums" style={{ color: MINT }}>{s.start}</p>
          <Sub>{s.end}</Sub>
        </div>
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm font-extrabold" style={{ color: INK }}>{s.title || "내 일정"}</p>
          <Sub className="truncate">{s.memo || "개인 일정"}</Sub>
        </div>
        <button onClick={() => setEditing(s)} className="rounded-full bg-white px-2.5 py-1.5" style={{ color: SUB }}><Pencil size={12} /></button>
        <button onClick={() => onDelete(s.id)} className="rounded-full bg-white px-2.5 py-1.5" style={{ color: FAINT }}><Trash2 size={12} /></button>
      </div>
    </div>
  );
  const list = attendeesOf(s);
  const eq = isEquipGroup(s);
  const group = list.length > 1 || s.type === "그룹";
  const doneN = list.filter((a) => a.status === "done").length;
  return (
    <div className="rounded-2xl p-3" style={{ backgroundColor: CANVAS }}>
      <div className="flex items-center gap-2">
        <div className="w-14 shrink-0">
          <p className="text-sm font-extrabold tabular-nums" style={{ color: INK }}>{s.start}</p>
          <Sub>{s.end}</Sub>
        </div>
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm font-extrabold" style={{ color: INK }}>
            {eq ? `그룹 · ${s.equip || "기구 미선택"}` : group ? `${s.type} · ${list.length}명` : nameOf(list[0]?.memberId)}
          </p>
          <Sub className="truncate">
            {eq ? [s.instructor, s.room].filter(Boolean).join(" · ") : group ? list.map((a) => nameOf(a.memberId)).join(", ") : [s.type, s.instructor, s.room].filter(Boolean).join(" · ")}
          </Sub>
        </div>
        {eq
          ? <span className="rounded-full px-2.5 py-1 text-xs font-extrabold" style={{ backgroundColor: s.groupDone ? GOOD_S : TINT, color: s.groupDone ? GOOD : PRIMARY }}>{s.groupDone ? "완료" : "예정"}</span>
          : group
          ? <span className="rounded-full px-2.5 py-1 text-xs font-extrabold" style={{ backgroundColor: doneN ? GOOD_S : TINT, color: doneN ? GOOD : PRIMARY }}>출석 {doneN}/{list.length}</span>
          : <span className="rounded-full px-2.5 py-1 text-xs font-extrabold" style={{ backgroundColor: stOf(list[0]?.status).bg, color: stOf(list[0]?.status).color }}>{stOf(list[0]?.status).label}</span>}
      </div>
      {s.memo && <p className="mt-1.5 text-xs" style={{ color: INK2 }}>{s.memo}</p>}
      {eq ? (
        <div className="mt-2 flex flex-wrap items-center gap-2 rounded-xl bg-white p-2.5">
          <span className="text-sm font-extrabold" style={{ color: INK }}>{s.equip || "기구 미선택"} 그룹 수업</span>
          {s.groupDone ? (
            <>
              <span className="rounded-full px-2 py-0.5 text-xs font-extrabold" style={{ backgroundColor: GOOD_S, color: GOOD }}>진행 완료 · 이달 누적 +1</span>
              <button onClick={() => onGroupDone && onGroupDone(s.id, false)} className="ml-auto text-xs font-bold" style={{ color: SUB }}>완료 취소</button>
            </>
          ) : (
            <button onClick={() => onGroupDone && onGroupDone(s.id, true)} className="ml-auto rounded-full px-3 py-1.5 text-xs font-extrabold text-white" style={{ backgroundColor: GOOD }}>진행 완료</button>
          )}
        </div>
      ) : (
        <div className="mt-2 space-y-1.5">
          {list.map((a) => <SchedAttendeeRow key={a.memberId} s={s} a={a} members={members} onStatus={onStatus} onNoshowFee={onNoshowFee} />)}
        </div>
      )}
      <div className="mt-2 flex gap-1.5">
        <button onClick={() => setEditing(s)} className="ml-auto rounded-full bg-white px-2.5 py-1.5" style={{ color: SUB }}><Pencil size={12} /></button>
        <button onClick={() => setDel(s.id)} className="rounded-full bg-white px-2.5 py-1.5" style={{ color: FAINT }}><Trash2 size={12} /></button>
      </div>
      {del === s.id && (
        <div className="mt-2 flex flex-wrap items-center gap-2 rounded-xl p-2.5" style={{ backgroundColor: BAD_S }}>
          <AlertTriangle size={13} style={{ color: BAD }} />
          <span className="text-xs font-bold" style={{ color: INK }}>{s.start} 수업을 삭제할까요?</span>
          <button onClick={() => { onDelete(s.id); setDel(null); }} className="rounded-full px-3 py-1.5 text-xs font-extrabold text-white" style={{ backgroundColor: BAD }}>삭제</button>
          <button onClick={() => setDel(null)} className="rounded-full bg-white px-3 py-1.5 text-xs font-bold" style={{ color: SUB }}>취소</button>
        </div>
      )}
    </div>
  );
}

function ScheduleManager({ db, photos, onSave, onDelete, onStatus, onStatusAll, onNoshowFee, onGroupDone, onNoComment, onSaveNote, onToast, onSettings, memberPresetId, onConsumeMemberPreset, quickAddRequest, onConsumeQuickAdd, onOpenMember }) {
  const initialDisplay = useMemo(() => {
    try { return JSON.parse(localStorage.getItem(SCHEDULE_VIEW_KEY) || "null") || {}; }
    catch (e) { return {}; }
  }, []);
  const [foldEmpty, setFoldEmpty] = useState(initialDisplay.foldEmpty !== false);
  /* v1의 showSunday 값은 APK에서 의도치 않게 계속 남을 수 있어 새 명시 설정만 읽는다. */
  const [showSundaySetting, setShowSundaySetting] = useState(initialDisplay.showSundaySetting === true);
  const [displaySettings, setDisplaySettings] = useState(false);
  const [listOpen, setListOpen] = useState(false);
  const [briefingList, setBriefingList] = useState(null);
  const [queueOpen, setQueueOpen] = useState(false);
  const [recordQueueRevision, setRecordQueueRevision] = useState(0);
  const scheduleTriggerRef = useRef(null);
  const queueTriggerRef = useRef(null);
  const [cursor, setCursor] = useState(todayISO());
  const [editing, setEditing] = useState(null);
  const [del, setDel] = useState(null);
  const [focusedMemberId, setFocusedMemberId] = useState(null);
  /* 유형 색은 계정에 함께 저장되는 설정값 — 없으면 기본 프리셋 */
  const scheduleColors = useMemo(() => normalizeScheduleColors(db.settings?.scheduleColors), [db.settings?.scheduleColors]);
  const typeTones = useMemo(() => scheduleTypeTones(scheduleColors, THEME), [scheduleColors, THEME]);
  useEffect(() => {
    const refresh = () => setRecordQueueRevision((value) => value + 1);
    window.addEventListener("pilateacher:lesson-record-updated", refresh);
    return () => window.removeEventListener("pilateacher:lesson-record-updated", refresh);
  }, []);
  useBackClose(!!focusedMemberId, () => setFocusedMemberId(null));
  useEffect(() => {
    if (!memberPresetId) return;
    const target = db.members.find((m) => m.id === memberPresetId);
    if (!target) { onConsumeMemberPreset?.(); return; }
    setCursor(todayISO());
    setEditing({ id: null, memberIds: [target.id], date: todayISO(), start: "10:00", dur: lessonDurationOf(target), type: "개인레슨", instructor: db.settings.staff, room: "", memo: "" });
    onConsumeMemberPreset?.();
  }, [memberPresetId]);
  useEffect(() => {
    if (!quickAddRequest) return;
    setCursor(todayISO());
    setEditing({ id: null, memberIds: [], date: todayISO(), start: "10:00", dur: DEFAULT_CLASS_DURATION, type: "개인레슨", instructor: db.settings.staff, room: "", memo: "" });
    onConsumeQuickAdd?.();
  }, [quickAddRequest]);
  useEffect(() => {
    try { localStorage.setItem(SCHEDULE_VIEW_KEY, JSON.stringify({ foldEmpty, showSundaySetting })); } catch (e) {}
  }, [foldEmpty, showSundaySetting]);

  const nameOf = (id) => db.members.find((m) => m.id === id)?.name || "삭제된 회원";
  const memberOf = (id) => db.members.find((m) => m.id === id);
  const briefingOf = useCallback((memberId, sessionId = null) => {
    const target = db.members.find((item) => item.id === memberId);
    return target ? createMemberBriefing({ member: target, currentSessionId: sessionId }) : null;
  }, [db.members]);
  const scheduleBriefingsOf = useCallback((lesson) => attendeesOf(lesson).map((attendee) => {
    const member = db.members.find((item) => item.id === attendee.memberId);
    const briefing = selectScheduleBriefing(briefingOf(attendee.memberId, lesson.id));
    return member && briefing ? { member, briefing } : null;
  }).filter(Boolean), [briefingOf, db.members]);
  const week = useMemo(() => Array.from({ length: 7 }, (_, i) => shift(monStart(cursor), i)), [cursor]);
  const byDate = (d) => db.schedule.filter((s) => s.date === d).sort((a, b) => a.start.localeCompare(b.start));
  const seatsOn = (d) => byDate(d).reduce((n, s) => n + attendeesOf(s).length, 0);
  const ym = monthKey(cursor);
  const stat = useMemo(() => monthStats(db.schedule, ym), [db.schedule, ym]);
  /* 이번 달 예상 급여 — 완료된 수업의 회원별 수업료를 더한다 */
  const monthPay = useMemo(() => {
    const cm = monthKey(todayISO());
    let sum = 0;
    db.schedule.forEach((s) => {
      if (!s?.date || !s.date.startsWith(cm) || isPersonalEvt(s)) return;
      if (isEquipGroup(s)) { if (s.groupDone) sum += rateBase(db.settings).group; return; }
      attendeesOf(s).forEach((a) => {
        if (!a.deductFrom) return;
        sum += rateFor(db.members.find((x) => x.id === a.memberId), s.type, db.settings);
      });
    });
    return sum;
  }, [db.schedule, db.members, db.settings]);
  const monthDone = useMemo(() => {
    const cm = monthKey(todayISO());
    return db.schedule.filter((s) => s?.date && s.date.startsWith(cm) && (isEquipGroup(s) ? !!s.groupDone : attendeesOf(s).some((a) => a.deductFrom))).length;
  }, [db.schedule]);

  const sundayHasLessons = db.schedule.some((s) => s?.date === week[6]);
  const visibleDays = showSundaySetting || sundayHasLessons ? week : week.slice(0, 6);
  const briefingRenderKey = `${visibleDays[0]}|${visibleDays.at(-1)}|${db.members.map((item) => `${item.id}:${item.notes?.length || 0}`).join(",")}`;
  const briefingRenderRef = useRef("");
  useEffect(() => {
    if (briefingRenderRef.current === briefingRenderKey) return;
    briefingRenderRef.current = briefingRenderKey;
    const memberIds = new Set(visibleDays.flatMap((date) => byDate(date)).flatMap((lesson) => attendeesOf(lesson).map((attendee) => attendee.memberId)));
    const count = [...memberIds].filter((memberId) => {
      const briefing = briefingOf(memberId);
      return briefing && briefing.kind !== "first_lesson" && briefing.kind !== "no_memory";
    }).length;
    if (count) trackMemberMemoryUsage("briefing_rendered", { count });
  }, [briefingRenderKey, briefingOf]);
  const liveEditing = editing?.id ? (db.schedule.find((s) => s.id === editing.id) || editing) : editing;
  const step = (dir) => setCursor(shift(cursor, 7 * dir));

  const itemProps = { members: db.members, del, setDel, setEditing, onStatus, onNoshowFee, onGroupDone, onDelete };

  const T0 = todayISO();
  const [parked, setParked] = useState({});
  const todayRows = useMemo(() => {
    const out = [];
    db.schedule.filter((s) => s.date === T0).sort((a, b) => a.start.localeCompare(b.start)).forEach((s) => {
      if (isPersonalEvt(s)) { out.push({ key: s.id, kind: "personal", sid: s.id, start: s.start, end: s.end, title: s.title, memo: s.memo, s }); return; }
      if (isEquipGroup(s)) { out.push({ key: s.id, kind: "equip", sid: s.id, start: s.start, end: s.end, type: s.type, equip: s.equip, done: !!s.groupDone, s }); return; }
      const list = attendeesOf(s);
      /* 듀엣처럼 두 명 이상이면 한 카드로 묶어 한 회원처럼 다룬다 */
      if (list.length > 1) { out.push({ key: s.id, kind: "multi", sid: s.id, start: s.start, end: s.end, type: s.type, list, s }); return; }
      list.forEach((a) => out.push({ key: `${s.id}:${a.memberId}`, kind: "member", id: a.memberId, sid: s.id, start: s.start, end: s.end, type: s.type, status: a.status, fee: a.noshowFee, deductFrom: a.deductFrom, s }));
    });
    return out;
  }, [db.schedule]);

  const [peek, setPeek] = useState(1);
  const T1 = shift(T0, peek);
  const tomorrowRows = useMemo(() => {
    const out = [];
    db.schedule.filter((s) => s.date === T1).sort((a, b) => a.start.localeCompare(b.start)).forEach((s) => {
      if (isPersonalEvt(s)) { out.push({ key: s.id, kind: "personal", start: s.start, title: s.title }); return; }
      if (isEquipGroup(s)) { out.push({ key: s.id, kind: "equip", start: s.start, equip: s.equip }); return; }
      attendeesOf(s).forEach((a) => out.push({ key: `${s.id}:${a.memberId}`, kind: "member", id: a.memberId, start: s.start, type: s.type }));
    });
    return out;
  }, [db.schedule, T1]);

  const [solo, setSolo] = useState({});
  /* 수업을 처리하면 목록 순서가 바뀐다 — 올라오는 카드에 튕기는 느낌을 준다 */
  const [bump, setBump] = useState(0);
  const bumped = () => setBump((v) => v + 1);
  const doStatus = (...a) => { bumped(); onStatus(...a); };
  const doStatusAll = (...a) => { bumped(); onStatusAll && onStatusAll(...a); };
  const doGroupDone = (...a) => { bumped(); onGroupDone(...a); };
  const isSettled = (r) => {
    if (r.kind === "personal") return true;
    if (r.kind === "equip") return r.done || !!r.s?.groupCancelled;
    if (r.kind === "multi") return r.list.every((a) => a.status !== "booked" && (a.status !== "noshow" || a.noshowFee != null));
    if (r.status === "cancel") return true;
    if (r.status === "noshow") return r.fee != null;
    if (r.status === "done") return (memberOf(r.id)?.notes || []).some((x) => x?.sid === r.sid);
    return false;
  };
  const canPark = (r) => isSettled(r) || !!parked[r.key];
  const sortedRows = useMemo(() => {
    const down = todayRows.filter((r) => parked[r.key]);
    const up = todayRows.filter((r) => !parked[r.key]);
    return [...up, ...down];
  }, [todayRows, parked]);
  const parkedCount = todayRows.filter((r) => parked[r.key]).length;
  const todayCls = db.schedule.filter((s) => s.date === T0 && !isPersonalEvt(s)).length;
  const todayStat = useMemo(() => {
    const st = { done: 0, booked: 0, noshow: 0, cancel: 0 };
    db.schedule.filter((s) => s?.date === T0 && !isPersonalEvt(s)).forEach((s) => {
      if (isEquipGroup(s)) { st[s.groupCancelled ? "cancel" : s.groupDone ? "done" : "booked"] += 1; return; }
      attendeesOf(s).forEach((a) => {
        if (a.status === "done") st.done += 1;
        else if (a.status === "noshow") st.noshow += 1;
        else if (a.status === "cancel") st.cancel += 1;
        else st.booked += 1;
      });
    });
    return st;
  }, [db.schedule, T0]);
  /* 지난달 같은 날까지 완료 수업 — 비교용 */
  const lastMonthSame = useMemo(() => {
    const d = new Date(T0 + "T00:00:00");
    const day = d.getDate();
    const p = new Date(d.getFullYear(), d.getMonth() - 1, 1);
    const pm = `${p.getFullYear()}-${String(p.getMonth() + 1).padStart(2, "0")}`;
    let n = 0;
    db.schedule.forEach((s) => {
      if (!s?.date || !s.date.startsWith(pm) || isPersonalEvt(s)) return;
      if (Number(s.date.slice(8, 10)) > day) return;
      if (isEquipGroup(s)) { if (s.groupDone) n += 1; return; }
      n += attendeesOf(s).filter((a) => a.deductFrom).length;
    });
    return n;
  }, [db.schedule, T0]);
  const doneRows = db.schedule
    .filter((s) => s?.date === T0 && !isPersonalEvt(s) && !isEquipGroup(s))
    .flatMap((s) => attendeesOf(s).filter((a) => a.status === "done").map((a) => ({ id: a.memberId, sid: s.id })));
  const unwrittenRows = doneRows.filter((r) => !(memberOf(r.id)?.notes || []).some((x) => x?.sid === r.sid));
  const unwritten = unwrittenRows.length;
  const firstUnwritten = unwrittenRows[0] || null;
  const nextTarget0 = nextTarget(db.schedule, db.members);
  const taskQueue = useMemo(() => {
    const endDate = todayISO();
    const startDate = shift(endDate, -27);
    const out = [];
    db.schedule
      .filter((s) => s?.date >= startDate && s.date <= endDate && !isPersonalEvt(s))
      .sort((a, b) => `${a.date} ${a.start}`.localeCompare(`${b.date} ${b.start}`))
      .forEach((s) => {
        const end = s.end || addMin(s.start || "00:00", Number(s.dur) || 50);
        if (new Date(`${s.date}T${end}:00`).getTime() > Date.now()) return;
        if (isEquipGroup(s)) {
          if (!s.groupCancelled && (s.actualCount === undefined || s.actualCount === null || s.actualCount === "")) {
            out.push({ key: `group:${s.id}`, kind: "group", s });
          }
          return;
        }
        attendeesOf(s).forEach((a) => {
          const m = memberOf(a.memberId);
          if (a.status === "done" && !(m?.notes || []).some((n) => n?.sid === s.id)) {
            const pendingDraft = loadPendingLessonRecord(a.memberId, s.id);
            out.push({ key: `note:${s.id}:${a.memberId}`, kind: "note", s, a, m, pendingDraft, recordQueueLabel: pendingLessonRecordLabel(pendingDraft) });
          }
          if (a.status === "noshow" && a.noshowFee == null) {
            out.push({ key: `noshow:${s.id}:${a.memberId}`, kind: "noshow", s, a, m });
          }
        });
      });
    return out;
  }, [db.schedule, db.members, recordQueueRevision]);

  return (
    <div className="flex h-full min-h-0 flex-col">
      {/* ─── 상단 헤더: 주 범위 + 이동 + 오늘 + 등록 ─── */}
      <div className="shrink-0 flex items-center gap-1 px-2" style={{ height: 44, backgroundColor: CARD, borderBottom: `1px solid ${LINE}` }}>
        <button onClick={() => step(-1)} className="flex items-center justify-center" style={{ width: 36, height: 36, color: SUB }}>
          <ChevronLeft size={18} />
        </button>
        <p className="min-w-0 flex-1 text-center text-sm font-semibold tabular-nums" style={{ color: INK }}>
          {md(visibleDays[0])}~{md(visibleDays[visibleDays.length - 1])}
        </p>
        <button onClick={() => step(1)} className="flex items-center justify-center" style={{ width: 36, height: 36, color: SUB }}>
          <ChevronRight size={18} />
        </button>
        <button onClick={() => setCursor(todayISO())} className="shrink-0 rounded-lg px-2.5 py-1.5 text-xs font-bold"
          style={{ color: cursor === T0 ? SUB : PRIMARY, opacity: cursor === T0 ? 0.5 : 1 }}>오늘</button>
        <button type="button" aria-label="일정 목록" onClick={() => setListOpen(true)}
          className="flex h-10 w-10 shrink-0 items-center justify-center" style={{ color: SUB }}>
          <ClipboardList size={18} />
        </button>
        <button onClick={() => setDisplaySettings(true)} aria-label="일정 표시 설정"
          className="flex h-10 w-10 shrink-0 items-center justify-center" style={{ color: SUB }}>
          <SlidersHorizontal size={18} />
        </button>
      </div>

      {/* ─── 메인 시간표 영역 (flex-1, 내부 스크롤) ─── */}
      <div className="min-h-0 flex-1 overflow-hidden" style={{ backgroundColor: CARD }}>
        {focusedMemberId && (
          <div className="sticky top-0 z-20 flex items-center gap-2 px-3 py-2" style={{ backgroundColor: TINT, borderBottom: `1px solid ${LINE}` }}>
            <span className="min-w-0 flex-1 text-xs font-bold" style={{ color: BRAND_D }}>{nameOf(focusedMemberId)} · 이번 주 이 회원 일정만 보기</span>
            <button type="button" onClick={() => setFocusedMemberId(null)} className="flex h-7 shrink-0 items-center gap-1 px-2 text-xs font-semibold" style={{ borderRadius: 7, backgroundColor: CARD, color: SUB, border: `1px solid ${LINE}` }}><X size={12} />필터 해제</button>
          </div>
        )}
        <WeekGrid days={visibleDays} byDate={byDate} nameOf={nameOf} memberOf={(id) => db.members.find((m) => m.id === id)} briefingOf={briefingOf} cursor={cursor} foldEmpty={foldEmpty} focusedMemberId={focusedMemberId} scheduleColors={scheduleColors}
          onOpen={(s, trigger) => { scheduleTriggerRef.current = trigger; setEditing(s); }}
          onNew={(date, start, dur, trigger) => { scheduleTriggerRef.current = trigger; setEditing({ id: null, memberIds: [], date, start, dur: dur || DEFAULT_CLASS_DURATION, type: "개인레슨", instructor: db.settings.staff, room: "", memo: "" }); }} />
      </div>

      {/* ─── 하단 고정 업무 요약 ─── */}
      <div className="shrink-0" style={{ padding: "6px 12px 8px", backgroundColor: PAGE }}>
        <button onClick={(e) => { if (taskQueue.length) { queueTriggerRef.current = e.currentTarget; setQueueOpen(true); } }} disabled={!taskQueue.length}
          className="flex h-14 w-full items-center gap-3 rounded-xl px-3 text-left disabled:opacity-80"
          style={{ backgroundColor: taskQueue.length ? TINT : CARD, border: `1px solid ${taskQueue.length ? RING : LINE}`, boxShadow: "0 1px 4px rgba(28,36,51,.06)" }}>
          <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg" style={{ backgroundColor: taskQueue.length ? TINT : GOOD_S }}>
            {taskQueue.length ? <Pencil size={14} style={{ color: PRIMARY }} /> : <Check size={14} style={{ color: GOOD }} />}
          </span>
          <span className="min-w-0 flex-1">
            <span className="block text-sm font-extrabold" style={{ color: INK }}>{taskQueue.length ? `처리할 업무 ${taskQueue.length}건` : "남은 수업 없음"}</span>
            <span className="block text-xs" style={{ color: SUB }}>{taskQueue.length ? "기록 · 인원체크 · 차감 결정" : "처리할 업무가 없습니다"}</span>
          </span>
          {taskQueue.length > 0 && <span className="shrink-0 text-xs font-extrabold" style={{ color: PRIMARY }}>지금 처리</span>}
        </button>
      </div>

      {editing && <ScheduleForm draft={liveEditing} members={db.members} schedule={db.schedule} briefingOf={briefingOf} scheduleColors={scheduleColors} returnFocusRef={scheduleTriggerRef} onClose={() => setEditing(null)}
        onSubmit={(v) => { onSave(v); setEditing(null); }} onDelete={(id) => { onDelete(id); setEditing(null); }}
        onStatus={onStatus} onStatusAll={onStatusAll} onNoshowFee={onNoshowFee} onGroupDone={onGroupDone}
        onNoComment={onNoComment} onSaveNote={onSaveNote} onFocusMemberWeek={(memberId) => { setFocusedMemberId(memberId); setEditing(null); }} />}
      {queueOpen && (
        <ScheduleQueueSheet tasks={taskQueue} members={db.members} returnFocusRef={queueTriggerRef} onClose={() => setQueueOpen(false)}
          onNoComment={onNoComment} onSaveNote={onSaveNote}
          onNoshowFee={onNoshowFee} onSaveSchedule={onSave} />
      )}
      {displaySettings && (
        <Sheet title="일정 표시 설정" onClose={() => setDisplaySettings(false)}>
          <div className="space-y-2">
            {[
              { label: "빈 시간 접기", value: foldEmpty, set: setFoldEmpty },
              { label: "일요일 표시", value: showSundaySetting, set: setShowSundaySetting },
            ].map((item) => (
              <button key={item.label} onClick={() => item.set(!item.value)}
                className="flex h-12 w-full items-center rounded-xl px-3 text-left" style={{ border: `1px solid ${LINE}`, backgroundColor: CARD }}>
                <span className="text-sm font-bold" style={{ color: INK }}>{item.label}</span>
                <span className="ml-auto flex h-6 w-10 items-center rounded-full p-0.5" style={{ backgroundColor: item.value ? BRAND : LINE }}>
                  <span className="h-5 w-5 rounded-full bg-white transition-transform" style={{ transform: item.value ? "translateX(16px)" : "none" }} />
                </span>
              </button>
            ))}
          </div>
        </Sheet>
      )}
      {listOpen && (
        <Sheet title="이번 주 일정" sub={`${md(visibleDays[0])}~${md(visibleDays[visibleDays.length - 1])}`} onClose={() => setListOpen(false)} wide>
          <div className="space-y-3">
            {visibleDays.map((date) => {
              const rows = byDate(date);
              return (
                <section key={date}>
                  <p className="mb-1.5 text-xs font-semibold tabular-nums" style={{ color: date === todayISO() ? PRIMARY : SUB }}>{dow(date)} {md(date)}</p>
                  {rows.length ? rows.map((s) => {
                    const cardAttendees = attendeesOf(s);
                    const memberBriefings = !isPersonalEvt(s) && !isEquipGroup(s) ? scheduleBriefingsOf(s) : [];
                    const singleBriefing = cardAttendees.length === 1 ? memberBriefings[0] || null : null;
                    const groupBriefingCount = cardAttendees.length > 1 ? memberBriefings.length : 0;
                    return (
                      <div key={s.id} className="mb-1 rounded-lg" style={{ backgroundColor: CANVAS, border: `1px solid ${LINE}`, borderLeft: `3px solid ${(typeTones[lessonTypeKeyOf(s)] || typeTones.private).edge}` }}>
                        <button type="button" onClick={(e) => { scheduleTriggerRef.current = e.currentTarget; setListOpen(false); setEditing(s); }}
                          className="flex min-h-11 w-full items-center gap-2 px-3 py-2 text-left">
                          <span className="shrink-0 text-xs font-semibold tabular-nums" style={{ color: PRIMARY }}>{s.start}</span>
                          <span className="min-w-0 flex-1">
                            <span className="block truncate text-sm font-semibold" style={{ color: INK }}>{isPersonalEvt(s) ? s.title : isEquipGroup(s) ? groupHeadcountText(s) : cardAttendees.map((a) => nameOf(a.memberId)).join(" · ")}</span>
                            <span className="mt-0.5 block truncate" style={{ fontSize: 10, color: SUB }}>{[lessonTypeInfo(s).label, lessonEquipFullText(s)].filter(Boolean).join(" · ")}</span>
                          </span>
                          <ChevronRight size={14} style={{ color: SUB }} />
                        </button>
                        {singleBriefing && (
                          <button type="button" onClick={() => { setListOpen(false); onOpenMember?.(singleBriefing.member.id); }}
                            className="flex min-h-11 w-full items-center gap-2 border-t px-3 py-2 text-left" style={{ borderColor: LINE }}>
                            <Sparkles size={13} className="shrink-0" style={{ color: PRIMARY }} />
                            <span className="min-w-0 flex-1 truncate text-xs font-semibold" style={{ color: INK2 }}>{singleBriefing.briefing.displayText}</span>
                          </button>
                        )}
                        {groupBriefingCount > 0 && (
                          <button type="button" onClick={(event) => { scheduleTriggerRef.current = event.currentTarget; setListOpen(false); setBriefingList({ lesson: s, items: memberBriefings }); }}
                            className="mx-3 mb-2 flex min-h-11 items-center rounded-full px-3 text-xs font-extrabold" style={{ backgroundColor: TINT, color: PRIMARY }}>
                            확인할 회원 {groupBriefingCount}명
                            <ChevronRight size={13} className="ml-auto" />
                          </button>
                        )}
                      </div>
                    );
                  }) : <p className="rounded-lg px-3 py-2 text-xs" style={{ backgroundColor: CANVAS, color: SUB }}>일정 없음</p>}
                </section>
              );
            })}
          </div>
        </Sheet>
      )}
      {briefingList && (
        <Sheet title="회원별 브리핑" sub={`${ymd(briefingList.lesson.date)} · ${briefingList.lesson.start}`} onClose={() => setBriefingList(null)}>
          <div className="space-y-2">
            {briefingList.items.map(({ member, briefing }) => (
              <button key={member.id} type="button" onClick={() => { setBriefingList(null); onOpenMember?.(member.id); }}
                className="flex min-h-14 w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left" style={{ backgroundColor: CANVAS, border: `1px solid ${LINE}` }}>
                <Avatar name={member.name} size={34} />
                <span className="min-w-0 flex-1">
                  <span className="block text-sm font-extrabold" style={{ color: INK }}>{member.name}</span>
                  <span className="mt-0.5 block text-xs leading-relaxed" style={{ color: INK2 }}>{briefing.displayText}</span>
                </span>
                <ChevronRight size={14} className="shrink-0" style={{ color: SUB }} />
              </button>
            ))}
          </div>
        </Sheet>
      )}
    </div>
  );
}
const SWIPE_GO = 58, SWIPE_MAX = 88;
function SwipeRow({ children, down, enabled, onPark, onUnpark }) {
  const box = useRef(null), tag = useRef(null), g = useRef(null);
  const paint = (dx, spring) => {
    const n = box.current; if (!n) return;
    n.style.transition = spring ? "transform .38s cubic-bezier(.22,1,.36,1)" : "";
    n.style.transform = dx ? `translate3d(${dx}px,0,0)` : "translate3d(0,0,0)";
    if (tag.current) {
      const t = Math.min(1, Math.abs(dx) / SWIPE_GO);
      tag.current.style.opacity = String(t);
      tag.current.style.transform = `scale(${0.9 + t * 0.1})`;
    }
  };
  const start = (e) => {
    if (!enabled || e.pointerType === "mouse" && e.button !== 0) return;
    g.current = { x: e.clientX, y: e.clientY, axis: null, dx: 0 };
    const n = box.current; if (n) n.style.transition = "";
  };
  const move = (e) => {
    const s = g.current; if (!s) return;
    const dx = e.clientX - s.x, dy = e.clientY - s.y;
    if (!s.axis) {
      if (Math.abs(dx) < 5 && Math.abs(dy) < 5) return;
      s.axis = Math.abs(dx) > Math.abs(dy) ? "x" : "y";
      if (s.axis === "x") e.currentTarget.setPointerCapture?.(e.pointerId);
    }
    if (s.axis !== "x") return;
    const dir = down ? 1 : -1;
    const v = dx * dir;
    s.dx = v <= 0 ? 0 : (v > SWIPE_MAX ? SWIPE_MAX + (v - SWIPE_MAX) * 0.22 : v) * dir;
    paint(s.dx, false);
  };
  const end = () => {
    const s = g.current; if (!s) return;
    g.current = null;
    const hit = Math.abs(s.dx) >= SWIPE_GO;
    paint(0, true);
    if (hit) (down ? onUnpark : onPark)();
  };
  return (
    <div className="relative select-none" style={{ opacity: down ? 0.6 : 1, transition: "opacity .2s ease" }}>
      {enabled && (
        <div ref={tag} className="pointer-events-none absolute inset-0 flex items-center rounded-2xl px-4"
          style={{ backgroundColor: down ? GOOD_S : TINT, justifyContent: down ? "flex-start" : "flex-end", opacity: 0 }}>
          <span className="text-xs font-extrabold" style={{ color: down ? GOOD : PRIMARY }}>{down ? "되돌리기" : "정리하기"}</span>
        </div>
      )}
      <div ref={box} onPointerDown={start} onPointerMove={move} onPointerUp={end} onPointerCancel={end}
        style={{ touchAction: "pan-y", willChange: "transform" }}>
        {children}
      </div>
    </div>
  );
}

const AXIS = 28, GRID_PAD_X = 12, GRID_H0 = 8, GRID_H1 = 23, GRID_ROW = 64, GRID_FOLD = 20;
const hourLabel = (h) => `${String(h).padStart(2, "0")}시`;

function WeekGrid({ days, byDate, nameOf, memberOf, briefingOf, cursor, onOpen, onNew, foldEmpty = true, focusedMemberId = null, scheduleColors = null }) {
  const rows = GRID_H1 - GRID_H0 + 1;
  /* 유형 색은 설정/테마 레이어에서 계산한 값만 쓴다 — 카드 안에 색을 적지 않는다 */
  const typeTones = useMemo(() => scheduleTypeTones(scheduleColors, THEME), [scheduleColors, THEME]);
  const top0 = GRID_H0 * 60;
  const gridRef = useRef(null);
  const gridHeaderRef = useRef(null);
  const [gridBodyHeight, setGridBodyHeight] = useState(0);
  /* 빈 칸을 위아래로 훑으면 그 시간만큼 일정이 잡힌다 (30분 단위) */
  /* 지금 시각 표시선 — 1분마다 갱신 */
  const [nowMin, setNowMin] = useState(() => { const d = new Date(); return d.getHours() * 60 + d.getMinutes(); });
  useEffect(() => {
    const t = setInterval(() => { const d = new Date(); setNowMin(d.getHours() * 60 + d.getMinutes()); }, 60000);
    return () => clearInterval(t);
  }, []);
  const showNow = nowMin >= top0 && nowMin <= GRID_H1 * 60 + 59;
  const activeHours = useMemo(() => {
    const out = new Set();
    days.forEach((d) => byDate(d).forEach((s) => {
      const start = Math.max(GRID_H0, Math.floor(minOf(s.start) / 60));
      const end = Math.min(GRID_H1, Math.floor(Math.max(minOf(s.start), minOf(s.end) - 1) / 60));
      for (let h = start; h <= end; h += 1) out.add(h);
    }));
    if (days.includes(todayISO())) out.add(Math.floor(nowMin / 60));
    return out;
  }, [days, byDate, nowMin]);
  useEffect(() => {
    const grid = gridRef.current;
    if (!grid) return undefined;
    const measure = () => {
      const headerHeight = gridHeaderRef.current?.getBoundingClientRect().height || 0;
      setGridBodyHeight(Math.max(0, grid.clientHeight - headerHeight));
    };
    measure();
    if (typeof ResizeObserver === "undefined") {
      window.addEventListener("resize", measure);
      return () => window.removeEventListener("resize", measure);
    }
    const observer = new ResizeObserver(measure);
    observer.observe(grid);
    return () => observer.disconnect();
  }, []);
  const baseHeightOf = (hour) => (!foldEmpty || activeHours.has(hour) ? GRID_ROW : GRID_FOLD);
  const baseTotalHeight = Array.from({ length: rows }, (_, i) => baseHeightOf(GRID_H0 + i)).reduce((a, b) => a + b, 0);
  const fillPerRow = gridBodyHeight > baseTotalHeight ? (gridBodyHeight - baseTotalHeight) / rows : 0;
  const heightOf = (hour) => baseHeightOf(hour) + fillPerRow;
  const topOf = (minutes) => {
    const clamped = Math.max(top0, Math.min((GRID_H1 + 1) * 60, minutes));
    const hour = Math.floor(clamped / 60);
    let y = 0;
    for (let h = GRID_H0; h < Math.min(hour, GRID_H1 + 1); h += 1) y += heightOf(h);
    if (hour <= GRID_H1) y += ((clamped % 60) / 60) * heightOf(hour);
    return y;
  };
  const totalHeight = Array.from({ length: rows }, (_, i) => heightOf(GRID_H0 + i)).reduce((a, b) => a + b, 0);
  const nowTop = topOf(nowMin);
  const nowKey = `${todayISO()} ${String(Math.floor(nowMin / 60)).padStart(2, "0")}:${String(nowMin % 60).padStart(2, "0")}`;
  const nextId = days.flatMap((d) => byDate(d)).filter((s) => !isPersonalEvt(s) && `${s.date} ${s.start}` >= nowKey)
    .sort((a, b) => `${a.date} ${a.start}`.localeCompare(`${b.date} ${b.start}`))[0]?.id || null;
  const slotAt = (e, el) => {
    const r = el.getBoundingClientRect();
    const y = Math.max(0, Math.min(r.height - 1, e.clientY - r.top));
    let acc = 0;
    for (let h = GRID_H0; h <= GRID_H1; h += 1) {
      const hh = heightOf(h);
      if (y < acc + hh) return { hour: h, half: y - acc >= hh / 2 ? 1 : 0 };
      acc += hh;
    }
    return { hour: GRID_H1, half: 1 };
  };
  /* 빈 칸을 누르면 그 시간대(30분)로 등록 창이 열린다 */
  const tapNew = (d, e) => {
    e.currentTarget.focus();
    const k = slotAt(e, e.currentTarget);
    const startMin = k.hour * 60 + k.half * 30;
    const start = `${String(Math.floor(startMin / 60)).padStart(2, "0")}:${String(startMin % 60).padStart(2, "0")}`;
    onNew(d, start, DEFAULT_CLASS_DURATION, e.currentTarget);
  };
  const blocksOf = (d) => byDate(d).filter((s) => {
    const a = minOf(s.start), b = minOf(s.end) || a + 50;
    return b > top0 && a < (GRID_H1 + 1) * 60;
  }).map((s) => {
    const st = Math.max(minOf(s.start), top0);
    const en = Math.min(minOf(s.end) || st + 50, (GRID_H1 + 1) * 60);
    const pv = isPersonalEvt(s);
    const eq = isEquipGroup(s);
    const list = attendeesOf(s);
    const label = pv ? (s.title || "내 일정") : eq
      ? ((s.groupDone || num(s.actualCount) > 0) && num(s.groupCount) > 0 ? `참석 ${num(s.actualCount) || 0}/${num(s.groupCount)}` : groupHeadcountText(s))
      : list.length > 1 ? `${nameOf(list[0]?.memberId)}+${list.length - 1}` : nameOf(list[0]?.memberId);
    /* 두 번째 줄은 준비할 기구 — 시간은 좌측 시간축에 이미 있으므로 카드에서 반복하지 않는다 */
    const equipText = lessonEquipText(s);
    const typeKey = lessonTypeKeyOf(s);
    const typeDef = lessonTypeDef(typeKey);
    const groupPeople = num(s.groupCount);
    const done = pv ? false : eq ? !!s.groupDone : list.length > 0 && list.every((a) => a.status !== "booked");
    const status = list[0]?.status || "booked";
    const needsRecord = !pv && !eq && list.some((a) => a.status === "done" && !(memberOf?.(a.memberId)?.notes || []).some((n) => n?.sid === s.id));
    const briefingLine = !pv && !eq && list.some((attendee) => !!selectScheduleBriefing(briefingOf?.(attendee.memberId, s.id)));
    const typeLabel = typeDef.label;
    return { s, top: topOf(st), h: Math.max(20, topOf(en) - topOf(st) - 2), label, equipText, typeKey, typeShort: typeDef.short, typeLabel, briefingLine, done, cancelled: (eq && !!s.groupCancelled) || status === "cancel", noshow: status === "noshow", eq, pv, next: s.id === nextId, needsRecord, groupPeople };
  }).filter((b) => b.top >= -GRID_ROW && b.top < totalHeight);

  return (
    <div ref={gridRef} className="pt-week-grid flex h-full min-h-0 flex-col" style={{ padding: `0 ${GRID_PAD_X}px`, backgroundColor: CARD }}>
          <div className="min-h-0 flex-1 overflow-y-auto">
          <div ref={gridHeaderRef} className="sticky top-0 z-20 grid shrink-0" style={{ gridTemplateColumns: `var(--pt-week-axis, ${AXIS}px) repeat(${days.length}, minmax(0, 1fr))`, backgroundColor: "var(--card)", borderBottom: "1px solid var(--line)" }}>
            <div />
            {days.map((d) => {
              const today = d === todayISO(), on = d === cursor;
              return (
                <div key={d} className="min-w-0 py-1.5 text-center" style={{ borderLeft: "1px solid var(--line)", backgroundColor: today ? "var(--tint)" : "var(--card)" }}>
                  <p className="pt-week-day font-extrabold" style={{ color: today ? "var(--primary)" : redInk(d, SUB) }}>{dow(d)}</p>
                  <p className="pt-week-date font-extrabold tabular-nums" style={{ color: today ? "var(--primary)" : redInk(d, on ? INK : SUB) }}>{Number(d.slice(8, 10))}</p>
                </div>
              );
            })}
          </div>
          <div className="relative grid" style={{ gridTemplateColumns: `var(--pt-week-axis, ${AXIS}px) repeat(${days.length}, minmax(0, 1fr))` }}>
            <div style={{ height: totalHeight }}>
              {Array.from({ length: rows }, (_, i) => (
                <div key={i} className="flex items-start justify-end pr-1 pt-0.5" style={{ height: heightOf(GRID_H0 + i), borderTop: i ? `1px solid ${LINE}` : "none" }}>
                  <span className="pt-week-time font-bold tabular-nums" style={{ color: FAINT }}>{hourLabel(GRID_H0 + i)}</span>
                </div>
              ))}
            </div>
            {days.map((d) => (
              <div key={d} tabIndex={-1} className="relative min-w-0 overflow-hidden"
                style={{ height: totalHeight, borderLeft: `1px solid ${LINE}`, backgroundColor: d === todayISO() ? TINT : "transparent" }}
                onClick={(e) => tapNew(d, e)}>
                {Array.from({ length: rows }, (_, i) => (
                  <div key={i} style={{ height: heightOf(GRID_H0 + i), borderTop: i ? `1px solid ${LINE}` : "none" }}>
                    <div style={{ height: heightOf(GRID_H0 + i) / 2, borderBottom: `1px dashed ${LINE}` }} />
                  </div>
                ))}
                {d === todayISO() && showNow && (
                  <div className="pointer-events-none absolute left-0 right-0 z-10" style={{ top: nowTop }}>
                    <div style={{ height: 2, backgroundColor: "#FF3B30", boxShadow: "0 0 5px rgba(255,59,48,.35)" }} />
                    <div style={{ position: "absolute", left: -4, top: -3, width: 8, height: 8, borderRadius: 8, backgroundColor: "#FF3B30" }} />
                  </div>
                )}
                {blocksOf(d).map((b) => {
                  const memberMatch = !focusedMemberId || attendeesOf(b.s).some((a) => a.memberId === focusedMemberId);
                  const tone = typeTones[b.typeKey] || typeTones.private;
                  const memberDot = !b.pv && !b.eq ? idColor(attendeesOf(b.s)[0]?.memberId) : "";
                  /* 카드는 최대 두 줄. 폭이 40px 남짓이라 첫 줄은 회원명에 모두 내주고,
                     유형 약자는 기구와 같은 두 번째 줄에 둔다. 두 줄이 안 들어가는
                     짧은 카드에서만 약자를 이름 앞에 붙인다 — 색만으로 구분하지 않기 위해서다. */
                  const twoLine = b.h >= 26;
                  /* 회원 점과 다음 수업 표시가 이름 폭을 먹는 만큼 글자를 한 단계 줄인다 */
                  const labelLen = b.label.length + (twoLine && memberDot ? 1 : 0) + (b.next ? 1 : 0);
                  return (
                  <button key={b.s.id} title={[b.typeLabel, b.label, lessonEquipFullText(b.s)].filter(Boolean).join(" · ")} onPointerDown={(e) => e.stopPropagation()} onClick={(e) => { e.stopPropagation(); onOpen(b.s, e.currentTarget); }}
                    className="absolute left-0.5 right-0.5 flex min-w-0 flex-col justify-center overflow-hidden text-left"
                    style={{ top: b.top + 1, height: Math.max(18, b.h - 1), borderRadius: 4,
                      background: b.cancelled ? "transparent" : b.noshow ? "var(--bad-s)" : tone.surface,
                      border: b.next ? "1.5px solid var(--brand)" : b.cancelled ? "1px dashed var(--line)" : `1px solid ${b.noshow ? "var(--bad-s)" : tone.border}`,
                      borderLeft: `3px solid ${b.cancelled ? "var(--line)" : tone.edge}`,
                      color: b.noshow ? "var(--bad)" : b.done || b.cancelled ? "var(--ink2)" : "var(--ink)",
                      padding: "1px 2px 1px 3px", fontSize: labelLen >= 6 ? 8 : labelLen === 5 ? 9 : labelLen === 4 ? 9.5 : 10.5,
                      letterSpacing: labelLen >= 4 ? "-0.35px" : "-0.15px", lineHeight: 1.08, fontWeight: b.next || (focusedMemberId && memberMatch) ? 700 : 600,
                      opacity: memberMatch ? (b.done ? 0.74 : 1) : 0.22, boxShadow: focusedMemberId && memberMatch ? `0 0 0 2px ${RING}` : "none", transition: "opacity .18s ease, box-shadow .18s ease" }}>
                    {b.next && <Play size={7} fill={BRAND} className="absolute left-0.5 top-0.5" />}
                    {memberDot && !twoLine && <span className="absolute" aria-hidden="true" style={{ left: 2, bottom: 2, width: 5, height: 5, borderRadius: 3, backgroundColor: memberDot, opacity: b.done ? .45 : 1 }} />}
                    <span className="flex w-full min-w-0 items-center" style={{ paddingLeft: b.next ? 8 : 0 }}>
                      {!twoLine && <span className="pt-week-type mr-0.5 shrink-0" aria-label={`${b.typeLabel} 수업`} style={{ color: tone.edge }}>{b.typeShort}</span>}
                      {memberDot && twoLine && <span className="shrink-0" aria-hidden="true" style={{ width: 3.5, height: 3.5, borderRadius: 2, marginRight: 1.5, backgroundColor: memberDot, opacity: b.done ? .45 : 1 }} />}
                      <span className="min-w-0 flex-1 truncate" style={{ textDecoration: b.cancelled ? "line-through" : "none" }}>{b.label}</span>
                    </span>
                    {twoLine && (
                      <span className="pt-week-equip flex w-full min-w-0 items-center">
                        <span className="pt-week-type mr-0.5 shrink-0" aria-label={`${b.typeLabel} 수업`} style={{ color: tone.edge }}>{b.typeShort}</span>
                        <span className="min-w-0 flex-1 truncate" style={{ color: tone.ink }}>{b.equipText}</span>
                      </span>
                    )}
                    {b.briefingLine && <span className="absolute" aria-label="브리핑 있음" style={{ top: 2, right: 2, width: b.h >= 24 ? 5 : 4, height: b.h >= 24 ? 5 : 4, borderRadius: 3, backgroundColor: PRIMARY }} />}
                    {b.needsRecord && <span className="absolute" aria-label="기록 필요" style={{ bottom: 2, right: 2, width: 5, height: 5, borderRadius: 3, backgroundColor: BRAND }} />}
                  </button>
                  );
                })}
              </div>
            ))}
          </div>
          </div>
    </div>
  );
}

function ScheduleForm({ draft, members, schedule, briefingOf, returnFocusRef, onClose, onSubmit, onDelete, onStatus, onStatusAll, onNoshowFee, onGroupDone, onNoComment, onSaveNote, onFocusMemberWeek, scheduleColors = null }) {
  const aiRecording = useContext(AIRecordingStatusContext);
  const currentIds = draft.memberIds || attendeesOf(draft).map((a) => a.memberId).filter(Boolean);
  const initialKind = draft.personal
    ? (draft.title === "상담" ? "consult" : "off")
    : draft.type === "그룹" ? "group" : draft.type === "듀엣" || currentIds.length > 1 ? "duet" : "solo";
  const duration = draft.dur || (draft.start && draft.end ? Math.max(10, minOf(draft.end) - minOf(draft.start)) : DEFAULT_CLASS_DURATION);
  const [kind, setKind] = useState(initialKind);
  const [f, setF] = useState({ ...draft, start: draft.start || "10:00", dur: duration, groupCount: draft.groupCount ?? (initialKind === "group" ? DEFAULT_GROUP_COUNT : "") });
  /* 강사가 고른 기구 — AI 요약이 추론한 값과 섞지 않는다 */
  const [equipmentIds, setEquipmentIds] = useState(() => equipmentIdsOf(draft));
  const typeTones = useMemo(() => scheduleTypeTones(scheduleColors, THEME), [scheduleColors, THEME]);
  const [memberIds, setMemberIds] = useState(currentIds);
  const [memberNames, setMemberNames] = useState(currentIds.map((id) => members.find((m) => m.id === id)?.name || ""));
  const [del, setDel] = useState(false);
  const [editingInfo, setEditingInfo] = useState(!draft.id);
  const [activeMemberId, setActiveMemberId] = useState(currentIds[0] || "");
  const [recordMode, setRecordMode] = useState(null);
  const [recordFallback, setRecordFallback] = useState("");
  const [recordBody, setRecordBody] = useState("");
  const [picker, setPicker] = useState(null);
  const isGroup = kind === "group";
  const isDuet = kind === "duet";
  const isMemberLesson = kind === "solo" || isDuet;
  const activeMember = members.find((m) => m.id === activeMemberId) || null;
  const activeAttendee = attendeesOf(draft).find((a) => a.memberId === activeMemberId) || null;
  const latestNote = (activeMember?.notes || []).slice().sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")))[0] || null;
  const currentLessonNote = (activeMember?.notes || []).find((note) => String(note?.sid || "") === String(draft.id || "")) || null;
  const activeBriefing = useMemo(() => activeMember ? (briefingOf?.(activeMember.id, draft.id) || createMemberBriefing({ member: activeMember, currentSessionId: draft.id })) : null, [activeMember, briefingOf, draft.id]);
  const openedBriefingRef = useRef("");
  useEffect(() => {
    if (!activeMember?.id || !draft.id || !activeBriefing) return;
    const key = `${activeMember.id}:${draft.id}`;
    if (openedBriefingRef.current === key) return;
    openedBriefingRef.current = key;
    trackMemberMemoryUsage("briefing_opened", { count: 1 });
  }, [activeMember?.id, activeBriefing, draft.id]);
  const hour = Number((f.start || "10:00").slice(0, 2));
  const minute = Number((f.start || "10:00").slice(3, 5));
  const durationOptions = [...new Set([30, DEFAULT_CLASS_DURATION, 60, 80, Number(f.dur)].filter((n) => Number.isFinite(n) && n > 0))].sort((a, b) => a - b);
  const setTime = (h, m) => setF((x) => ({ ...x, start: `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}` }));
  const neededSlots = isDuet ? 2 : isMemberLesson ? 1 : 0;
  const chosenIds = memberIds.slice(0, neededSlots).filter(Boolean);
  const unresolved = isMemberLesson && memberNames.slice(0, neededSlots).some((name, i) => {
    if (!name?.trim()) return true;
    return !memberIds[i];
  });
  const duplicateChoice = isDuet && chosenIds.length === 2 && chosenIds[0] === chosenIds[1];
  const ambiguousName = memberNames.slice(0, neededSlots).find((name, i) => name?.trim() && !memberIds[i] && members.filter((m) => isActive(m) && (m.name || "").trim() === name.trim()).length > 1);
  const prevIds = new Set(attendeesOf(draft).map((a) => a.memberId));
  const noRest = chosenIds.filter((id) => !prevIds.has(id)).map((id) => members.find((m) => m.id === id)).filter((m) => m && left(m) <= 0);
  const myStart = minOf(f.start), myEnd = myStart + (Number(f.dur) || 50);
  const clashes = (schedule || []).filter((s) => s?.date === f.date && s.id !== draft.id).filter((s) => {
    const a = minOf(s.start), b = minOf(s.end) || a + 50;
    return myStart < b && a < myEnd;
  });
  /* 그룹 인원은 비워도 기본 8명으로 저장한다 — 빈 칸 때문에 등록 버튼이 막히면 안 된다 */
  const ready = !!f.date && !!f.start && (!isMemberLesson || (chosenIds.length === neededSlots && !unresolved && !duplicateChoice))
    && noRest.length === 0;
  const submit = () => {
    const previous = attendeesOf(draft);
    const personal = kind === "consult" || kind === "off";
    onSubmit({
      id: draft.id || uid(), date: f.date, start: f.start, end: addMin(f.start, Number(f.dur) || 50),
      type: personal ? "개인일정" : isGroup ? "그룹" : isDuet ? "듀엣" : "개인레슨",
      instructor: personal ? "" : (f.instructor || ""), room: personal ? "" : (f.room || ""), memo: f.memo || "",
      /* 기구는 stable id 배열로 저장하고, 옛 코드가 읽는 equip 문자열은 거울로만 남긴다 */
      equipmentIds: personal ? [] : normalizeEquipmentIds(equipmentIds),
      equip: isGroup ? legacyEquipLabel(equipmentIds) : null,
      groupCount: isGroup ? clampGroupCount(f.groupCount) : undefined,
      actualCount: isGroup ? draft.actualCount : undefined,
      noshowCount: isGroup ? draft.noshowCount : undefined,
      groupDone: isGroup ? !!draft.groupDone : undefined,
      groupCancelled: isGroup ? !!draft.groupCancelled : undefined,
      attendees: isMemberLesson ? chosenIds.map((id) => previous.find((a) => a.memberId === id) || { memberId: id, status: "booked", deductFrom: null, noshowFee: null }) : [],
      personal: personal || undefined,
      title: personal ? (kind === "consult" ? "상담" : (draft.personal && draft.title && draft.title !== "상담" ? draft.title : "휴무")) : undefined,
      ...(draft.aiRecommendation ? { aiRecommendation: draft.aiRecommendation } : {}),
    });
  };
  return (
    <>
    <ScheduleBottomSheet title={draft.id ? (isMemberLesson ? "수업 관리" : "일정 수정") : "일정 등록"} subtitle={`${dow(f.date)} ${f.date?.slice(5).replace("-", ".") || ""}${draft.id ? ` · ${draft.start}~${draft.end || addMin(draft.start, Number(draft.dur) || 50)}` : ""}`} returnFocusRef={returnFocusRef} onClose={onClose}>
      <div className="space-y-4">
        {draft.id && !editingInfo && (
          <div className="flex items-center gap-3 rounded-xl px-3 py-2.5" style={{ backgroundColor: CANVAS, border: `1px solid ${LINE}` }}>
            <div className="min-w-0 flex-1">
              <p className="text-sm font-extrabold" style={{ color: INK }}>{draft.personal ? draft.title : isGroup ? `그룹 ${num(draft.groupCount) || DEFAULT_GROUP_COUNT}명` : `${draft.type} · ${attendeesOf(draft).length}명`}</p>
              <p className="mt-0.5 text-xs tabular-nums" style={{ color: SUB }}>{draft.start}~{draft.end || addMin(draft.start, Number(draft.dur) || 50)}{lessonEquipFullText(draft) ? ` · ${lessonEquipFullText(draft)}` : ""}</p>
            </div>
            <button onClick={() => setEditingInfo(true)} className="shrink-0 rounded-lg px-3 py-2 text-xs font-extrabold" style={{ backgroundColor: CARD, color: PRIMARY, border: `1px solid ${LINE}` }}>일정 정보 수정</button>
          </div>
        )}
        {editingInfo && <>
        <div>
          <p className="mb-1.5 text-xs font-bold" style={{ color: SUB }}>날짜</p>
          <button type="button" onClick={() => setPicker({ type: "date" })} className="flex h-11 w-full items-center gap-2 px-3 text-left text-sm font-bold"
            style={{ borderRadius: 9, backgroundColor: CANVAS, border: `1px solid ${LINE}`, color: INK }}>
            <CalendarDays size={15} style={{ color: BRAND }} />{ymd(f.date)} · {dow(f.date)}요일<ChevronDown size={14} className="ml-auto" style={{ color: SUB }} />
          </button>
        </div>
        <div>
          <p className="mb-1.5 text-xs font-bold" style={{ color: SUB }}>시작 시간</p>
          <div className="grid grid-cols-3 gap-2">
            <button type="button" aria-label="시 선택" onClick={() => setPicker({ type: "hour" })} className="flex h-11 items-center justify-center gap-1 text-sm font-bold" style={{ borderRadius: 9, backgroundColor: CANVAS, border: `1px solid ${LINE}`, color: INK }}>{hour}시<ChevronDown size={13} style={{ color: SUB }} /></button>
            <button type="button" aria-label="분 선택" onClick={() => setPicker({ type: "minute" })} className="flex h-11 items-center justify-center gap-1 text-sm font-bold" style={{ borderRadius: 9, backgroundColor: CANVAS, border: `1px solid ${LINE}`, color: INK }}>{String(minute).padStart(2, "0")}분<ChevronDown size={13} style={{ color: SUB }} /></button>
            <button type="button" aria-label="수업 길이 선택" onClick={() => setPicker({ type: "duration" })} className="flex h-11 items-center justify-center gap-1 text-sm font-bold" style={{ borderRadius: 9, backgroundColor: CANVAS, border: `1px solid ${LINE}`, color: INK }}>{f.dur}분<ChevronDown size={13} style={{ color: SUB }} /></button>
          </div>
        </div>
        <div>
          <p className="mb-1.5 text-xs font-bold" style={{ color: SUB }}>유형</p>
          <div className="grid grid-cols-6 gap-2">
            {LESSON_TYPES.map((type, index) => {
              const tone = typeTones[type.key];
              const active = kind === type.formKind;
              return (
                <button key={type.key} onClick={() => { setKind(type.formKind); if (type.formKind === "group") setF((current) => ({ ...current, groupCount: num(current.groupCount) > 0 ? current.groupCount : DEFAULT_GROUP_COUNT })); }}
                  className="flex h-11 items-center justify-center gap-1.5 rounded-lg text-sm font-bold"
                  style={{ gridColumn: `span ${index < 3 ? 2 : 3}`, backgroundColor: active ? tone.surface : CARD, color: active ? tone.ink : SUB, border: `1px solid ${active ? tone.edge : LINE}` }}>
                  <span aria-hidden="true" style={{ width: 8, height: 8, borderRadius: 2, backgroundColor: tone.edge, opacity: active ? 1 : 0.55 }} />
                  {type.label}
                </button>
              );
            })}
          </div>
        </div>
        {isMemberLesson && (
          <div>
            <p className="mb-1.5 text-xs font-bold" style={{ color: SUB }}>회원 {isDuet ? "(두 명 모두 입력)" : "(같은 이름은 기존 회원으로 연결)"}</p>
            <div className={`grid gap-2 ${isDuet ? "grid-cols-2" : "grid-cols-1"}`}>
              {Array.from({ length: neededSlots }, (_, slot) => (
                <button type="button" key={slot} onClick={() => setPicker({ type: "member", slot })} className="flex h-11 min-w-0 items-center gap-2 px-3 text-left text-sm font-bold"
                  style={{ borderRadius: 9, backgroundColor: CANVAS, border: `1px solid ${LINE}`, color: memberIds[slot] ? INK : FAINT }}>
                  <Users size={14} className="shrink-0" style={{ color: BRAND }} /><span className="min-w-0 flex-1 truncate">{memberNames[slot] || (isDuet ? `회원 ${slot + 1} 선택` : "회원 선택")}</span><ChevronDown size={13} className="shrink-0" style={{ color: SUB }} />
                </button>
              ))}
            </div>
          </div>
        )}
        {isGroup && (
          <div>
            <p className="mb-1.5 text-xs font-bold" style={{ color: SUB }}>인원 <span style={{ fontWeight: 600, color: FAINT }}>({GROUP_COUNT_MIN}~{GROUP_COUNT_MAX}명)</span></p>
            <div className="flex items-center gap-2">
              <button type="button" aria-label="인원 줄이기" onClick={() => setF((current) => ({ ...current, groupCount: clampGroupCount(num(current.groupCount) - 1, GROUP_COUNT_MIN) }))}
                className="flex h-11 w-11 shrink-0 items-center justify-center" style={{ borderRadius: 9, backgroundColor: CANVAS, border: `1px solid ${LINE}`, color: INK }}><Minus size={15} /></button>
              <input inputMode="numeric" aria-label="그룹 인원" value={f.groupCount}
                onChange={(e) => setF({ ...f, groupCount: e.target.value.replace(/[^0-9]/g, "").slice(0, 2) })}
                onBlur={() => setF((current) => ({ ...current, groupCount: clampGroupCount(current.groupCount) }))}
                placeholder={String(DEFAULT_GROUP_COUNT)} className={`${inputCls} text-center tabular-nums`} />
              <button type="button" aria-label="인원 늘리기" onClick={() => setF((current) => ({ ...current, groupCount: clampGroupCount(num(current.groupCount) + 1) }))}
                className="flex h-11 w-11 shrink-0 items-center justify-center" style={{ borderRadius: 9, backgroundColor: CANVAS, border: `1px solid ${LINE}`, color: INK }}><Plus size={15} /></button>
            </div>
          </div>
        )}
        {(isGroup || isMemberLesson) && (
          <div>
            <p className="mb-1.5 text-xs font-bold" style={{ color: SUB }}>사용 기구 <span style={{ fontWeight: 600, color: FAINT }}>(복수 선택 · 선택 안 해도 됩니다)</span></p>
            <div className="grid grid-cols-3 gap-2">
              {EQUIPMENT_REGISTRY.map((item) => {
                const on = equipmentIds.includes(item.id);
                return (
                  <button type="button" key={item.id} aria-pressed={on} onClick={() => setEquipmentIds((current) => toggleEquipmentId(current, item.id))}
                    className="flex h-10 items-center justify-center gap-1 text-xs font-bold"
                    style={{ borderRadius: 9, backgroundColor: on ? TINT : CARD, color: on ? BRAND_D : SUB, border: `1px solid ${on ? BRAND : LINE}`, fontWeight: on ? 700 : 600 }}>
                    {on && <Check size={12} />}{item.label}
                  </button>
                );
              })}
            </div>
          </div>
        )}
        <div className="min-h-[18px] text-xs font-bold" style={{ color: noRest.length || unresolved || duplicateChoice ? BAD : clashes.length ? WARN : SUB }}>
          {noRest.length > 0 ? `${noRest.map((m) => m.name).join(", ")} 회원은 잔여 횟수가 없어 등록할 수 없습니다.`
            : ambiguousName ? `‘${ambiguousName}’ 동명이인이 있습니다. 회원 상세에서 대상을 확인해 주세요.`
              : duplicateChoice ? "듀엣 회원은 서로 달라야 합니다."
                : unresolved && memberNames.some((n) => n?.trim()) ? "등록된 회원 이름과 정확히 일치해야 합니다."
                  : clashes.length ? "같은 시간에 다른 일정이 있습니다. 겹쳐서 등록됩니다."
                    : ""}
        </div>
        <button onClick={submit} disabled={!ready} className="flex h-12 w-full items-center justify-center rounded-lg text-sm font-extrabold text-white disabled:opacity-35" style={{ backgroundColor: PRIMARY }}>
          {draft.id ? "수정 저장" : "등록"}
        </button>
        </>}
        {draft.id && !isGroup && isMemberLesson && attendeesOf(draft).length > 0 && (
          <div className="space-y-3 border-t pt-3" style={{ borderColor: LINE }}>
            <div className="flex gap-2 overflow-x-auto pb-0.5">
              {attendeesOf(draft).map((a) => {
                const m = members.find((x) => x.id === a.memberId);
                const active = a.memberId === activeMemberId;
                return (
                  <button key={a.memberId} onClick={() => { setActiveMemberId(a.memberId); setRecordMode(null); setRecordBody(""); }}
                    className="min-w-[132px] flex-1 rounded-xl p-3 text-left"
                    style={{ backgroundColor: active ? TINT : CANVAS, border: `1px solid ${active ? "#D9D7EE" : LINE}` }}>
                    <p className="truncate text-sm font-extrabold" style={{ color: active ? PRIMARY : INK }}>{m?.name || "삭제된 회원"}</p>
                    <p className="mt-0.5 text-xs" style={{ color: SUB }}>잔여 {left(m)}회{m?.contractEnd ? ` · ${m.contractEnd.slice(5).replace("-", ".")}까지` : ""}</p>
                  </button>
                );
              })}
            </div>

            {activeMember && activeBriefing && (
              <section className="rounded-xl p-3" aria-label="지난 수업 이어서 보기" style={{ backgroundColor: LAVENDER_S, border: `1px solid ${RING}` }}>
                <div className="mb-2 flex items-center gap-2"><Sparkles size={14} style={{ color: BRAND_D }} /><p className="min-w-0 flex-1 text-xs font-extrabold" style={{ color: BRAND_D }}>지난 수업 이어서 보기</p><span style={{ fontSize: 9, color: SUB }}>저장한 기록 기준</span></div>
                <div className="space-y-1.5">{activeBriefing.lines.slice(0, 5).map((briefingLine, index) => <p key={`${briefingLine.kind}-${index}`} className="text-xs leading-relaxed" style={{ color: briefingLine.kind === "conflict" ? WARN : INK2 }}>• {briefingLine.text}</p>)}</div>
              </section>
            )}

            {activeMember && (
              <button type="button" onClick={() => onFocusMemberWeek?.(activeMember.id)} className="flex h-11 w-full items-center justify-center gap-2 rounded-lg text-xs font-bold"
                style={{ backgroundColor: TINT, color: BRAND_D, border: `1px solid #D5D1EB` }}>
                <CalendarDays size={14} /> 이번 주 이 회원 일정만 보기
              </button>
            )}

            {activeMember && activeAttendee && (
              <>
                <div className="rounded-xl p-3" style={{ backgroundColor: CARD, border: `1px solid ${LINE}` }}>
                  <div className="flex items-center gap-2">
                    <div className="min-w-0 flex-1">
                      <p className="text-sm font-extrabold" style={{ color: INK }}>{activeMember.name}</p>
                      <p className="mt-0.5 text-xs" style={{ color: SUB }}>{activeMember.goal || "목표 미입력"}</p>
                    </div>
                    <span className="shrink-0 rounded-full px-2.5 py-1 text-xs font-extrabold" style={{ backgroundColor: stOf(activeAttendee.status).bg, color: stOf(activeAttendee.status).color }}>{stOf(activeAttendee.status).label}</span>
                  </div>
                  {(activeMember.focus || []).length > 0 && <p className="mt-2 text-xs leading-relaxed" style={{ color: WARN }}>주의 · {(activeMember.focus || []).join(" · ")}</p>}
                  {currentLessonNote && <p className="mt-2 line-clamp-2 text-xs font-bold leading-relaxed" style={{ color: GOOD }}>이 수업 기록 · {currentLessonNote.body}</p>}
                  {latestNote && !latestNote.lessonRecord && <p className="mt-2 line-clamp-2 text-xs leading-relaxed" style={{ color: INK2 }}>최근 기록 · {latestNote.body}</p>}
                </div>

                <div>
                  <p className="mb-1.5 text-xs font-extrabold" style={{ color: INK }}>출석 · 차감</p>
                  <div className="grid grid-cols-3 gap-2">
                    {[{ k: "done", l: "출석" }, { k: "noshow", l: "노쇼" }, { k: "cancel", l: "취소" }].map((o) => (
                      <button key={o.k} onClick={() => onStatus?.(draft.id, o.k, activeMemberId)} className="h-9 rounded-lg text-xs font-bold"
                        style={activeAttendee.status === o.k ? { backgroundColor: stOf(o.k).color, color: "#fff" } : { backgroundColor: CANVAS, color: SUB }}>{o.l}</button>
                    ))}
                  </div>
                  {activeAttendee.status !== "booked" && <button type="button" onClick={() => onStatus?.(draft.id, "booked", activeMemberId)} className="mt-2 h-9 w-full rounded-lg text-xs font-bold" style={{ backgroundColor: CARD, color: BRAND_D, border: `1px solid ${LINE}` }}>처리 되돌리기</button>}
                  {activeAttendee.status === "done" && <p className="mt-1.5 text-xs font-bold" style={{ color: activeAttendee.deductFrom ? GOOD : SUB }}>{activeAttendee.deductFrom ? `${activeAttendee.deductFrom} 1회 차감 완료` : "차감 없이 출석 기록"}</p>}
                  {activeAttendee.status === "noshow" && (
                    <div className="mt-2 grid grid-cols-2 gap-2">
                      <button onClick={() => onNoshowFee?.(draft.id, true, activeMemberId)} className="h-9 rounded-lg text-xs font-extrabold" style={activeAttendee.noshowFee === true ? { backgroundColor: BAD, color: "#fff" } : { backgroundColor: BAD_S, color: BAD }}>차감</button>
                      <button onClick={() => onNoshowFee?.(draft.id, false, activeMemberId)} className="h-9 rounded-lg text-xs font-extrabold" style={activeAttendee.noshowFee === false ? { backgroundColor: BRAND, color: "#fff" } : { backgroundColor: CANVAS, color: SUB }}>비차감</button>
                    </div>
                  )}
                </div>

                {activeAttendee.status !== "booked" && <>
                {!aiRecordingAvailable(aiRecording) && <p className="rounded-lg px-3 py-2 text-xs font-bold" style={{ backgroundColor: WARN_S, color: WARN }}>AI 정리 잠시 점검 중 · 직접 입력으로 기록할 수 있어요.</p>}
                <div className="grid grid-cols-2 gap-2">
                  {aiRecordingAvailable(aiRecording) && <button onClick={() => { setRecordFallback(""); setRecordMode(recordMode === "voice" ? null : "voice"); }} className="flex h-12 items-center justify-center gap-1.5 rounded-lg text-xs font-extrabold" style={{ backgroundColor: recordMode === "voice" ? PRIMARY : TINT, color: recordMode === "voice" ? "#fff" : PRIMARY, border: `1px solid ${recordMode === "voice" ? PRIMARY : "#D9D7EE"}` }}><Smartphone size={15} /> 기록하기</button>}
                  <button onClick={() => { setRecordFallback(""); setRecordMode(recordMode === "write" ? null : "write"); }} className="flex h-12 items-center justify-center gap-1 rounded-lg text-xs font-extrabold" style={{ backgroundColor: recordMode === "write" ? TINT : CARD, color: recordMode === "write" ? PRIMARY : INK, border: `1px solid ${LINE}` }}><Pencil size={13} /> 직접입력</button>
                  <button onClick={async () => { const stored = await onNoComment?.(activeMemberId, draft.type, draft.id); if (stored !== false) onClose(); }} className="h-12 rounded-lg text-xs font-extrabold" style={{ backgroundColor: CARD, color: SUB, border: `1px solid ${LINE}` }}>노코멘트</button>
                  <button onClick={onClose} className="h-12 rounded-lg text-xs font-extrabold" style={{ backgroundColor: CANVAS, color: SUB, border: `1px solid ${LINE}` }}>나중에</button>
                </div>

                {recordMode && (
                  <div className="space-y-2 rounded-xl p-3" style={{ backgroundColor: CANVAS }}>
                    {recordFallback && <p role="status" className="rounded-lg px-3 py-2 text-xs font-bold" style={{ backgroundColor: WARN_S, color: WARN }}>{recordFallback}</p>}
                    {recordMode === "voice" && <VoiceNote key={lessonRecordSessionKey(activeMemberId, draft.id)} memberId={activeMemberId} memberName={activeMember?.name || "회원"} lessonId={draft.id} onLater={() => setRecordMode(null)} onClose={onClose} onDeferred={onClose} onDirectEntry={(message) => { setRecordFallback(message || "음성 인식을 사용할 수 없어 직접 입력으로 전환했습니다."); setRecordMode("write"); }} onDraftChange={(text, meta, options) => onSaveNote?.(activeMemberId, draft.type, draft.id, text, meta, options)} onApply={(text, meta) => onSaveNote?.(activeMemberId, draft.type, draft.id, text, meta, { confirmed: true, upsert: true })} />}
                    {recordMode === "write" && <><textarea rows={4} value={recordBody} onChange={(e) => setRecordBody(e.target.value)} placeholder="수업 내용과 회원 반응을 기록하세요" className={`${inputCls} h-auto resize-none py-3 leading-relaxed`} /><button disabled={!recordBody.trim()} onClick={async () => { const stored = await onSaveNote?.(activeMemberId, draft.type, draft.id, recordBody.trim(), null); if (stored !== false) onClose(); }} className="h-11 w-full rounded-lg text-xs font-extrabold text-white disabled:opacity-35" style={{ backgroundColor: PRIMARY }}>저장</button></>}
                  </div>
                )}
                </>}
              </>
            )}

            {attendeesOf(draft).length > 1 && (
              <div className="grid grid-cols-3 gap-1">
                {[{ k: "done", l: "전체 출석" }, { k: "noshow", l: "전체 노쇼" }, { k: "cancel", l: "전체 취소" }].map((o) => (
                  <button key={o.k} onClick={() => onStatusAll?.(draft.id, o.k)} className="h-9 rounded-lg text-xs font-bold" style={{ backgroundColor: TINT, color: PRIMARY }}>{o.l}</button>
                ))}
              </div>
            )}
          </div>
        )}
        {draft.id && isGroup && (
          <div className="grid grid-cols-2 gap-2 border-t pt-3" style={{ borderColor: LINE }}>
            <button onClick={() => { onGroupDone?.(draft.id, true); onClose(); }} className="h-9 rounded-lg text-xs font-bold text-white" style={{ backgroundColor: GOOD }}>완료</button>
            <button onClick={() => { onGroupDone?.(draft.id, "cancelled"); onClose(); }} className="h-9 rounded-lg text-xs font-bold" style={{ backgroundColor: BAD_S, color: BAD }}>취소</button>
          </div>
        )}
        {draft.id && !editingInfo && <button type="button" onClick={onClose} className="h-11 w-full rounded-lg text-xs font-extrabold" style={{ backgroundColor: CARD, color: INK, border: `1px solid ${LINE}` }}>닫기</button>}
        {draft.id && onDelete && (del ? (
          <div className="flex items-center gap-2 rounded-lg p-2.5" style={{ backgroundColor: BAD_S }}>
            <span className="min-w-0 flex-1 text-xs font-bold" style={{ color: BAD }}>이 일정을 삭제할까요?</span>
            <button onClick={() => { onDelete(draft.id); onClose(); }} className="rounded-lg px-3 py-2 text-xs font-bold text-white" style={{ backgroundColor: BAD }}>삭제</button>
            <button onClick={() => setDel(false)} className="rounded-lg px-3 py-2 text-xs font-bold" style={{ color: SUB }}>취소</button>
          </div>
        ) : draft.id ? (
          <button onClick={() => setDel(true)} className="flex h-10 w-full items-center justify-center gap-1.5 rounded-lg text-xs font-bold" style={{ backgroundColor: CANVAS, color: SUB }}><Trash2 size={13} /> 일정 삭제</button>
        ) : null)}
      </div>
    </ScheduleBottomSheet>
    {picker?.type === "date" && <ChoiceBottomSheet title="날짜 선택" subtitle="선택한 날짜로 일정이 등록됩니다" value={f.date} onClose={() => setPicker(null)}
      options={Array.from({ length: 15 }, (_, index) => shift(f.date, index - 7)).map((date) => ({ value: date, label: `${ymd(date)} · ${dow(date)}요일`, description: date === todayISO() ? "오늘" : "" }))}
      onSelect={(date) => setF((current) => ({ ...current, date }))} />}
    {picker?.type === "hour" && <ChoiceBottomSheet title="시 선택" value={hour} columns={2} onClose={() => setPicker(null)} options={Array.from({ length: 24 }, (_, value) => ({ value, label: `${value}시` }))} onSelect={(value) => setTime(value, minute)} />}
    {picker?.type === "minute" && <ChoiceBottomSheet title="분 선택" value={minute} columns={2} onClose={() => setPicker(null)} options={[0, 10, 20, 30, 40, 50].map((value) => ({ value, label: `${String(value).padStart(2, "0")}분` }))} onSelect={(value) => setTime(hour, value)} />}
    {picker?.type === "duration" && <ChoiceBottomSheet title="수업 길이" value={Number(f.dur)} columns={2} onClose={() => setPicker(null)} options={durationOptions.map((value) => ({ value, label: `${value}분` }))} onSelect={(value) => setF((current) => ({ ...current, dur: value }))} />}
    {picker?.type === "member" && <ChoiceBottomSheet title="회원 선택" subtitle="기존 회원과 정확히 연결합니다" value={memberIds[picker.slot] || ""} onClose={() => setPicker(null)}
      options={members.filter(isActive).map((item) => ({ value: item.id, label: item.name || "이름 미입력", description: `잔여 ${left(item)}회${item.contractEnd ? ` · ${ymd(item.contractEnd)}까지` : ""}` }))}
      onSelect={(id) => { const item = members.find((memberItem) => memberItem.id === id); const ids = [...memberIds]; const names = [...memberNames]; ids[picker.slot] = id; names[picker.slot] = item?.name || ""; setMemberIds(ids); setMemberNames(names); if (!draft.id && picker.slot === 0 && item) setF((current) => ({ ...current, dur: lessonDurationOf(item) })); }} />}
    </>
  );
}

function ScheduleQueueSheet({ tasks, members, returnFocusRef, onClose, onNoComment, onSaveNote, onNoshowFee, onSaveSchedule }) {
  const aiRecording = useContext(AIRecordingStatusContext);
  const task = tasks[0] || null;
  const [groupCount, setGroupCount] = useState(0);
  const [lastGroup, setLastGroup] = useState(null);
  const [recordMode, setRecordMode] = useState(null);
  const [recordBody, setRecordBody] = useState("");
  useEffect(() => {
    if (task?.kind === "group") setGroupCount(num(task.s.actualCount ?? task.s.groupCount ?? 0));
    setRecordMode(null);
    setRecordBody("");
  }, [task?.key]);
  const memberName = task?.m?.name || members.find((m) => m.id === task?.a?.memberId)?.name || "회원";
  const targetName = task?.kind === "group" ? "그룹수업" : memberName;
  return (
    <ScheduleBottomSheet title="처리할 업무" subtitle={`남은 ${tasks.length}건 · 최근 4주`} returnFocusRef={returnFocusRef} onClose={onClose}>
      {!task ? (
        <div className="py-8 text-center">
          <span className="mx-auto flex h-10 w-10 items-center justify-center rounded-xl" style={{ backgroundColor: GOOD_S }}><Check size={18} style={{ color: GOOD }} /></span>
          <p className="mt-3 text-sm font-extrabold" style={{ color: INK }}>남은 수업 없음</p>
          {lastGroup && <button onClick={() => { onSaveSchedule?.({ ...lastGroup, actualCount: undefined, groupDone: false }); setLastGroup(null); }} className="mt-2 text-xs font-extrabold" style={{ color: GOOD }}>방금 저장한 그룹 인원을 미체크로 되돌리기</button>}
          <button onClick={onClose} className="mt-4 h-10 rounded-lg px-5 text-xs font-extrabold" style={{ backgroundColor: CANVAS, color: SUB }}>닫기</button>
        </div>
      ) : (
        <div className="space-y-3">
          {lastGroup && (
            <div className="flex items-center gap-2 rounded-lg px-3 py-2" style={{ backgroundColor: GOOD_S }}>
              <span className="min-w-0 flex-1 text-xs font-bold" style={{ color: GOOD }}>그룹 인원을 저장했습니다.</span>
              <button onClick={() => { onSaveSchedule?.({ ...lastGroup, actualCount: undefined, groupDone: false }); setLastGroup(null); }} className="shrink-0 text-xs font-extrabold" style={{ color: GOOD }}>미체크로 되돌리기</button>
            </div>
          )}
          <div className="rounded-xl px-3 py-3" style={{ backgroundColor: CANVAS, border: `1px solid ${LINE}` }}>
            <p className="text-xs font-bold tabular-nums" style={{ color: PRIMARY }}>{dow(task.s.date)} {task.s.date?.slice(5).replace("-", ".")} · {task.s.start}</p>
            <p className="mt-1 truncate text-base font-extrabold" style={{ color: INK }}>{targetName}</p>
            {task.kind === "note" && <p className="mt-1 text-xs font-bold" style={{ color: task.pendingDraft?.structuredDraft ? GOOD : task.pendingDraft?.rawTranscript ? WARN : SUB }}>{task.recordQueueLabel}</p>}
          </div>

          {task.kind === "note" && (
            <div>
              <p className="mb-2 text-xs" style={{ color: SUB }}>저장하면 다음 업무로 자동 이동합니다</p>
              {!aiRecordingAvailable(aiRecording) && <p className="mb-2 rounded-lg px-3 py-2 text-xs font-bold" style={{ backgroundColor: WARN_S, color: WARN }}>AI 정리 잠시 점검 중 · 직접 입력으로 기록할 수 있어요.</p>}
              <div className="grid grid-cols-2 gap-2">
                {aiRecordingAvailable(aiRecording) && <button onClick={() => setRecordMode(recordMode === "voice" ? null : "voice")} className="flex h-12 items-center justify-center gap-1 rounded-lg text-xs font-extrabold" style={{ backgroundColor: recordMode === "voice" ? PRIMARY : TINT, border: `1px solid ${recordMode === "voice" ? PRIMARY : "#D9D7EE"}`, color: recordMode === "voice" ? "#fff" : PRIMARY }}><Smartphone size={15} /> 말하기</button>}
                <button onClick={() => setRecordMode(recordMode === "write" ? null : "write")} className="flex h-12 items-center justify-center gap-1 rounded-lg text-xs font-extrabold" style={{ backgroundColor: recordMode === "write" ? TINT : CARD, border: `1px solid ${LINE}`, color: recordMode === "write" ? PRIMARY : INK }}><Pencil size={14} /> 직접 입력</button>
                <button onClick={() => onNoComment?.(task.a.memberId, task.s.type, task.s.id)} className="h-12 rounded-lg text-xs font-extrabold" style={{ backgroundColor: CARD, color: SUB, border: `1px solid ${LINE}` }}>노코멘트</button>
                <button onClick={onClose} className="h-12 rounded-lg text-xs font-extrabold" style={{ backgroundColor: CANVAS, color: SUB, border: `1px solid ${LINE}` }}>나중에</button>
              </div>
              {recordMode && (
                <div className="mt-3 space-y-2 rounded-xl p-3" style={{ backgroundColor: CANVAS }}>
                  {recordMode === "voice" && <VoiceNote key={lessonRecordSessionKey(task.a.memberId, task.s.id)} memberId={task.a.memberId} memberName={memberName} lessonId={task.s.id} onLater={() => setRecordMode(null)} onClose={onClose} onDeferred={onClose} onDirectEntry={() => setRecordMode("write")} onDraftChange={(text, meta, options) => onSaveNote?.(task.a.memberId, task.s.type, task.s.id, text, meta, options)} onApply={(text, meta) => onSaveNote?.(task.a.memberId, task.s.type, task.s.id, text, meta, { confirmed: true, upsert: true })} />}
                  {recordMode === "write" && <><textarea rows={4} value={recordBody} onChange={(e) => setRecordBody(e.target.value)} placeholder="수업 내용과 회원 반응을 기록하세요" className={`${inputCls} h-auto resize-none py-3 leading-relaxed`} /><button disabled={!recordBody.trim()} onClick={() => onSaveNote?.(task.a.memberId, task.s.type, task.s.id, recordBody.trim(), null)} className="h-11 w-full rounded-lg text-xs font-extrabold text-white disabled:opacity-35" style={{ backgroundColor: PRIMARY }}>저장 · 다음</button></>}
                </div>
              )}
            </div>
          )}

          {task.kind === "group" && (
            <div>
              <p className="mb-2 text-xs font-bold" style={{ color: SUB }}>참석 인원</p>
              <div className="flex items-center gap-2">
                <button aria-label="참석 인원 줄이기" onClick={() => setGroupCount((n) => Math.max(0, n - 1))} className="flex h-11 w-11 items-center justify-center rounded-lg" style={{ backgroundColor: CANVAS, border: `1px solid ${LINE}` }}><Minus size={16} /></button>
                <span className="flex h-11 min-w-0 flex-1 items-center justify-center rounded-lg text-lg font-extrabold tabular-nums" style={{ backgroundColor: CANVAS, color: INK }}>{groupCount}명</span>
                <button aria-label="참석 인원 늘리기" onClick={() => setGroupCount((n) => Math.min(num(task.s.groupCount) || 99, n + 1))} className="flex h-11 w-11 items-center justify-center rounded-lg" style={{ backgroundColor: CANVAS, border: `1px solid ${LINE}` }}><Plus size={16} /></button>
              </div>
              <button onClick={() => { setLastGroup(task.s); onSaveSchedule?.({ ...task.s, actualCount: groupCount, groupDone: true, groupCancelled: false }); }} className="mt-3 h-12 w-full rounded-lg text-sm font-extrabold text-white" style={{ backgroundColor: PRIMARY }}>저장</button>
            </div>
          )}

          {task.kind === "noshow" && (
            <div>
              <p className="mb-2 text-xs font-bold" style={{ color: SUB }}>노쇼 수강권 차감 여부</p>
              <div className="grid grid-cols-2 gap-2">
                <button onClick={() => onNoshowFee?.(task.s.id, true, task.a.memberId)} className="h-12 rounded-lg text-sm font-extrabold text-white" style={{ backgroundColor: BAD }}>차감</button>
                <button onClick={() => onNoshowFee?.(task.s.id, false, task.a.memberId)} className="h-12 rounded-lg text-sm font-extrabold" style={{ backgroundColor: CANVAS, color: SUB, border: `1px solid ${LINE}` }}>비차감</button>
              </div>
            </div>
          )}
        </div>
      )}
    </ScheduleBottomSheet>
  );
}

function coverDraw(ctx, img, w, h, tf) {
  const base = Math.max(w / img.width, h / img.height);
  const s = base * (tf?.scale || 1);
  const dw = img.width * s, dh = img.height * s;
  const rot = ((tf?.rot || 0) * Math.PI) / 180;
  ctx.save();
  ctx.translate(w / 2 + ((tf?.x || 0) / 100) * w, h / 2 + ((tf?.y || 0) / 100) * h);
  if (rot) ctx.rotate(rot);
  ctx.drawImage(img, -dw / 2, -dh / 2, dw, dh);
  ctx.restore();
}
function angleOf(p1, p2) {
  const [a, b] = p1.x <= p2.x ? [p1, p2] : [p2, p1];
  return +((Math.atan2(b.y - a.y, b.x - a.x) * 180) / Math.PI).toFixed(1);
}
function angleLabel(part, deg, mirror) {
  if (Math.abs(deg) < 0.3) return `${part} 수평 (0°)`;
  let higher = deg > 0 ? "좌" : "우";
  if (mirror) higher = higher === "좌" ? "우" : "좌";
  return `${part} ${Math.abs(deg).toFixed(1)}° · ${higher}측 높음`;
}

function drawAnnotationMark(ctx, mark, width, height, options = {}) {
  if (!ctx || !mark || !Array.isArray(mark.pts) || !mark.pts.length) return;
  const offsetX = Number(options.offsetX) || 0, offsetY = Number(options.offsetY) || 0;
  const lineScale = Math.max(0.01, Number(options.lineScale) || 1);
  const fontScale = Math.max(0.01, Number(options.fontScale) || lineScale);
  const strokeWidth = Math.max(0.8, (Number(mark.width) || 3) * (mark.tool === "arrow" ? 0.78 : 1) * lineScale);
  const point = (value) => ({ x: offsetX + Number(value?.x || 0) * width, y: offsetY + Number(value?.y || 0) * height });
  const start = point(mark.pts[0]), end = point(mark.pts[mark.pts.length - 1]);
  ctx.save();
  ctx.globalAlpha = mark.opacity ?? 1;
  ctx.strokeStyle = mark.color || "#6C5FD4";
  ctx.fillStyle = mark.color || "#6C5FD4";
  ctx.lineWidth = strokeWidth;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  if (mark.tool === "point") {
    ctx.beginPath(); ctx.arc(start.x, start.y, ((Number(mark.width) || 3) + 3) * lineScale, 0, Math.PI * 2); ctx.fill();
    ctx.lineWidth = Math.max(1, 1.5 * lineScale);
    ctx.beginPath(); ctx.arc(start.x, start.y, ((Number(mark.width) || 3) + 9) * lineScale, 0, Math.PI * 2); ctx.stroke();
    ctx.restore(); return;
  }
  if (mark.tool === "circle") {
    ctx.beginPath();
    ctx.ellipse((start.x + end.x) / 2, (start.y + end.y) / 2, Math.abs(end.x - start.x) / 2, Math.abs(end.y - start.y) / 2, 0, 0, Math.PI * 2);
    ctx.stroke();
  } else if (mark.tool === "rect") {
    ctx.strokeRect(Math.min(start.x, end.x), Math.min(start.y, end.y), Math.abs(end.x - start.x), Math.abs(end.y - start.y));
  } else if (mark.tool === "text") {
    const lines = annotationTextLines(mark), font = annotationFont(mark, fontScale), lineHeight = annotationFontSize(mark, fontScale) * 1.16;
    ctx.font = font; ctx.textAlign = "left"; ctx.textBaseline = "top";
    ctx.shadowColor = "rgba(0,0,0,.58)"; ctx.shadowBlur = Math.max(1.5, 2.4 * fontScale); ctx.shadowOffsetY = Math.max(1, fontScale);
    lines.forEach((line, index) => ctx.fillText(line || " ", start.x, start.y + index * lineHeight));
  } else {
    ctx.beginPath();
    if (mark.tool === "hline") { ctx.moveTo(offsetX, start.y); ctx.lineTo(offsetX + width, start.y); }
    else if (mark.tool === "vline") { ctx.moveTo(start.x, offsetY); ctx.lineTo(start.x, offsetY + height); }
    else mark.pts.forEach((value, index) => { const next = point(value); index ? ctx.lineTo(next.x, next.y) : ctx.moveTo(next.x, next.y); });
    ctx.stroke();
    if (mark.tool === "arrow" && mark.pts.length >= 2) {
      const [left, right] = arrowHeadPoints(start, end, (7 + (Number(mark.width) || 3) * 1.4) * lineScale);
      ctx.beginPath(); ctx.moveTo(end.x, end.y); ctx.lineTo(left.x, left.y); ctx.moveTo(end.x, end.y); ctx.lineTo(right.x, right.y); ctx.stroke();
    }
  }

  if (mark.tool === "angle" && mark.pts.length === 2) {
    const baseY = start.x <= end.x ? start.y : end.y;
    ctx.save(); ctx.setLineDash([5 * lineScale, 5 * lineScale]); ctx.globalAlpha *= 0.6;
    ctx.beginPath(); ctx.moveTo(Math.min(start.x, end.x) - 20 * lineScale, baseY); ctx.lineTo(Math.max(start.x, end.x) + 20 * lineScale, baseY); ctx.stroke(); ctx.restore();
    [start, end].forEach((value) => { ctx.beginPath(); ctx.arc(value.x, value.y, ((Number(mark.width) || 3) + 2) * lineScale, 0, Math.PI * 2); ctx.fill(); });
    if (mark.label && !options.hideLabel) {
      const centerX = (start.x + end.x) / 2, centerY = (start.y + end.y) / 2 - 14 * fontScale;
      ctx.font = `700 ${13 * fontScale}px Pretendard, sans-serif`;
      const textWidth = ctx.measureText(String(mark.label)).width;
      ctx.fillStyle = "rgba(10,10,16,0.82)"; ctx.fillRect(centerX - textWidth / 2 - 7 * fontScale, centerY - 15 * fontScale, textWidth + 14 * fontScale, 22 * fontScale);
      ctx.strokeStyle = "rgba(255,255,255,0.55)"; ctx.lineWidth = Math.max(0.8, fontScale); ctx.strokeRect(centerX - textWidth / 2 - 7 * fontScale, centerY - 15 * fontScale, textWidth + 14 * fontScale, 22 * fontScale);
      ctx.fillStyle = "#fff"; ctx.textAlign = "center"; ctx.textBaseline = "alphabetic"; ctx.fillText(String(mark.label), centerX, centerY + fontScale);
    }
  }
  ctx.restore();
}

function PostureCanvas({ photo, label, onClose, onCancel = onClose, onSave, onDraft, onToast, fresh, initialTool = "pen" }) {
  const wrapRef = useRef(null), canvasRef = useRef(null), imgRef = useRef(null);
  const [size, setSize] = useState({ w: 0, h: 0 });
  const [marks, setMarks] = useState(() => (Array.isArray(photo.marks) ? photo.marks : []).map((mark) => ({ ...mark, id: mark?.id || uid() })));
  const marksRef = useRef(marks);
  const [undoStack, setUndoStack] = useState([]);
  const [redoStack, setRedoStack] = useState([]);
  const [selectedMarkId, setSelectedMarkId] = useState(null);
  const [draft, setDraft] = useState(null);
  const [pending, setPending] = useState(null);
  const [tool, setTool] = useState(initialTool === "guide" ? "pen" : initialTool);
  const [guideSheet, setGuideSheet] = useState(false);
  const [recentColors, setRecentColors] = useState(() => readRecentAnnotationColors(window.localStorage));
  const [color, setColor] = useState(() => readRecentAnnotationColors(window.localStorage)[0] || "#6C5FD4");
  const [width, setWidth] = useState(4);
  const [opacity] = useState(1);
  const [grid] = useState(false);
  const [ruler, setRuler] = useState(null);
  const [memoDraft, setMemoDraft] = useState(null);
  const [colorPickerOpen, setColorPickerOpen] = useState(false);
  const [customColor, setCustomColor] = useState(() => hexToHsl("#6C5FD4"));
  const editRef = useRef(null);
  const memoTapRef = useRef(null);
  const rulerDrag = useRef(null);
  /* 두 손가락으로 자를 옮기고 돌린다 */
  const ptrs = useRef(new Map());
  const gest = useRef(null);
  /* 자가 꺼져 있으면 두 손가락은 사진 확대·이동 */
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const pinch = useRef(null);
  const resetZoom = () => { setZoom(1); setPan({ x: 0, y: 0 }); };
  const exportingRef = useRef(false);
  const [exportPreview, setExportPreview] = useState(null);
  const [exportBusy, setExportBusy] = useState(false);
  const initialMarks = useRef(JSON.stringify(marks));
  const onDraftRef = useRef(onDraft);
  useEffect(() => { onDraftRef.current = onDraft; }, [onDraft]);
  const hasUnsaved = () => JSON.stringify(marks) !== initialMarks.current;
  const requestClose = () => {
    if (hasUnsaved() && !window.confirm("저장하지 않은 표시가 있습니다. 편집을 종료할까요?")) return;
    onCancel?.();
  };
  useBackClose(true, requestClose);
  useBackClose(Boolean(exportPreview), () => setExportPreview(null));
  useScrollLock();

  const replaceMarks = (next) => {
    marksRef.current = next;
    setMarks(next);
  };
  const commitMarks = (updater) => {
    const current = marksRef.current;
    const next = typeof updater === "function" ? updater(current) : updater;
    if (!Array.isArray(next) || JSON.stringify(next) === JSON.stringify(current)) return;
    setUndoStack((history) => [...history, current].slice(-40));
    setRedoStack([]);
    replaceMarks(next);
  };
  const undoMarks = () => {
    if (pending) { setPending(null); return; }
    if (!undoStack.length) return;
    const previous = undoStack[undoStack.length - 1];
    setUndoStack((history) => history.slice(0, -1));
    setRedoStack((history) => [...history, marksRef.current].slice(-40));
    replaceMarks(previous);
    setSelectedMarkId((id) => previous.some((mark) => mark.id === id) ? id : null);
  };
  const redoMarks = () => {
    if (!redoStack.length) return;
    const next = redoStack[redoStack.length - 1];
    setRedoStack((history) => history.slice(0, -1));
    setUndoStack((history) => [...history, marksRef.current].slice(-40));
    replaceMarks(next);
    setSelectedMarkId((id) => next.some((mark) => mark.id === id) ? id : null);
  };
  const chooseColor = (value) => {
    const next = normalizeAnnotationColor(value, color);
    setColor(next);
    setRecentColors(rememberAnnotationColor(window.localStorage, next));
    if (selectedMarkId) commitMarks((items) => items.map((mark) => mark.id === selectedMarkId ? { ...mark, color: next } : mark));
  };
  const openColorPicker = () => { setCustomColor(hexToHsl(color)); setColorPickerOpen(true); };
  const customColorPreview = hslToHex(customColor.h, customColor.s, customColor.l);
  const setHandwritingSize = (value) => {
    const next = closestHandwritingWidth(value);
    setWidth(next);
    if (selectedMarkId) commitMarks((items) => items.map((mark) => mark.id === selectedMarkId && mark.tool === "text" ? { ...mark, width: next } : mark));
  };
  const deleteSelectedMark = () => {
    if (!selectedMarkId) return;
    commitMarks((items) => items.filter((mark) => mark.id !== selectedMarkId));
    setSelectedMarkId(null);
  };
  useEffect(() => {
    if (selectedMarkId && !marks.some((mark) => mark.id === selectedMarkId)) setSelectedMarkId(null);
  }, [marks, selectedMarkId]);

  useEffect(() => {
    if (!onDraftRef.current || !hasUnsaved()) return undefined;
    const timer = setTimeout(() => {
      Promise.resolve(onDraftRef.current?.(marks.map((mark) => ({ ...mark, source: mark.source || "manual" }))))
        .then((stored) => { if (stored === false) onToast?.({ ok: false, msg: "표시 초안을 저장하지 못했습니다. 편집 내용은 화면에 유지됩니다." }); })
        .catch(() => onToast?.({ ok: false, msg: "표시 초안을 저장하지 못했습니다. 편집 내용은 화면에 유지됩니다." }));
    }, 240);
    return () => clearTimeout(timer);
  }, [marks, onToast]);

  useEffect(() => {
    const img = new window.Image();
    if (!String(photo.src || "").startsWith("blob:")) img.crossOrigin = "anonymous";
    img.onload = () => { imgRef.current = img; setSize((s) => ({ ...s })); };
    img.src = photo.src;
  }, [photo.src]);

  useEffect(() => {
    const fit = () => {
      const el = wrapRef.current, c = canvasRef.current;
      if (!el || !c) return;
      const w = el.clientWidth, h = el.clientHeight, dpr = window.devicePixelRatio || 1;
      c.width = w * dpr; c.height = h * dpr;
      c.style.width = `${w}px`; c.style.height = `${h}px`;
      setSize({ w, h });
    };
    fit();
    window.addEventListener("resize", fit);
    return () => window.removeEventListener("resize", fit);
  }, []);

  const degText = (deg) => `${Math.abs(deg).toFixed(1)}°`;
  const imageFrame = () => wrapRef.current?.getBoundingClientRect() || canvasRef.current?.getBoundingClientRect();

  /* ---- 자(눈금자) 기하 ---- */
  const rulerGeom = (w, h) => {
    if (!ruler) return null;
    const C = { x: ruler.cx * w, y: ruler.cy * h };
    const rad = (ruler.deg * Math.PI) / 180;
    return { C, rad, u: { x: Math.cos(rad), y: Math.sin(rad) }, n: { x: -Math.sin(rad), y: Math.cos(rad) }, L: Math.hypot(w, h) * 1.3 };
  };
  const toLocal = (g, P) => { const dx = P.x - g.C.x, dy = P.y - g.C.y; return { x: dx * g.u.x + dy * g.u.y, y: dx * g.n.x + dy * g.n.y }; };
  /* 자를 켜면 '윗변'에서만 그릴 수 있다.
     실제 자처럼 — 자 몸통과 그 아래에는 아무것도 그어지지 않고,
     윗변 근처에 찍은 점은 자 선 위로 딱 붙는다. */
  const rulerZone = (p) => {
    const c = canvasRef.current;
    if (!c || !ruler) return { ok: true, pt: p };
    const r = imageFrame(), w = r.width, h = r.height;
    const g = rulerGeom(w, h);
    const lp = toLocal(g, { x: p.x * w, y: p.y * h });
    if (lp.y >= -1) return { ok: false, pt: p, lp };      /* 자 몸통과 그 아래 — 금지 */
    if (lp.y < -140) return { ok: true, pt: p, lp };       /* 자에서 멀면 자유롭게 */
    return { ok: true, snap: true, lp, pt: { x: (g.C.x + lp.x * g.u.x) / w, y: (g.C.y + lp.x * g.u.y) / h } };
  };
  const snapPt = (p) => rulerZone(p).pt;

  const measureCanvasText = (text, font) => {
    const context = canvasRef.current?.getContext("2d");
    if (!context) return String(text || " ").length * 14;
    context.save(); context.font = font; const measured = context.measureText(String(text || " ")).width; context.restore();
    return measured;
  };
  const drawSelection = (ctx, mark, w, h, renderScale) => {
    if (!mark || exportingRef.current) return;
    ctx.save();
    if (mark.tool === "arrow" && mark.pts?.length >= 2) {
      const values = [mark.pts[0], mark.pts[mark.pts.length - 1]].map((point) => ({ x: point.x * w, y: point.y * h }));
      ctx.setLineDash([4, 4]); ctx.strokeStyle = "rgba(255,255,255,.88)"; ctx.lineWidth = Math.max(3, (mark.width || 3) * 0.78 * renderScale + 2);
      ctx.beginPath(); ctx.moveTo(values[0].x, values[0].y); ctx.lineTo(values[1].x, values[1].y); ctx.stroke(); ctx.setLineDash([]);
      drawAnnotationMark(ctx, mark, w, h, { lineScale: renderScale, fontScale: renderScale });
      values.forEach((value, index) => {
        ctx.beginPath(); ctx.arc(value.x, value.y, 6, 0, Math.PI * 2); ctx.fillStyle = "rgba(18,22,32,.9)"; ctx.fill();
        ctx.strokeStyle = "#FFFFFF"; ctx.lineWidth = 1.5; ctx.stroke();
        ctx.beginPath(); ctx.arc(value.x, value.y, index ? 2.8 : 2.3, 0, Math.PI * 2); ctx.fillStyle = mark.color || color; ctx.fill();
      });
    } else if (mark.tool === "text") {
      const bounds = annotationTextBounds(mark, { width: w, height: h }, measureCanvasText, renderScale);
      ctx.setLineDash([5, 4]); ctx.strokeStyle = "rgba(255,255,255,.92)"; ctx.lineWidth = 1.5;
      ctx.strokeRect(bounds.left - 7, bounds.top - 6, bounds.width + 14, bounds.height + 12); ctx.setLineDash([]);
      ctx.beginPath(); ctx.arc(bounds.left - 7, bounds.top - 6, 8, 0, Math.PI * 2); ctx.fillStyle = "rgba(18,22,32,.92)"; ctx.fill(); ctx.strokeStyle = "#fff"; ctx.lineWidth = 2; ctx.stroke();
    }
    ctx.restore();
  };

  const drawRuler = (ctx, w, h) => {
    const g = rulerGeom(w, h); if (!g) return;
    const rx = Math.min(150, g.L / 2 - 30);
    ctx.save();
    ctx.translate(g.C.x, g.C.y); ctx.rotate(g.rad);
    ctx.fillStyle = "rgba(16,16,24,0.94)";
    ctx.fillRect(-g.L / 2, 0, g.L, 56);
    ctx.strokeStyle = "rgba(255,255,255,0.95)"; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-g.L / 2, 0); ctx.lineTo(g.L / 2, 0); ctx.stroke();
    ctx.strokeStyle = "rgba(255,255,255,0.45)"; ctx.lineWidth = 1;
    for (let x = Math.ceil(-g.L / 2 / 24) * 24; x <= g.L / 2; x += 24) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, x % 120 === 0 ? 16 : 9); ctx.stroke();
    }
    ctx.beginPath(); ctx.arc(0, 26, 15, 0, Math.PI * 2); ctx.fillStyle = "rgba(255,255,255,0.92)"; ctx.fill();
    ctx.strokeStyle = "rgba(0,0,0,0.35)"; ctx.lineWidth = 1.5; ctx.stroke();
    [-5, 0, 5].forEach((dx) => { ctx.beginPath(); ctx.arc(dx, 26, 1.6, 0, Math.PI * 2); ctx.fillStyle = "#17171F"; ctx.fill(); });
    ctx.beginPath(); ctx.arc(rx, 26, 13, 0, Math.PI * 2); ctx.fillStyle = PRIMARY; ctx.fill();
    ctx.strokeStyle = "rgba(255,255,255,0.9)"; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.beginPath(); ctx.arc(rx, 26, 5.5, 0, Math.PI * 2); ctx.strokeStyle = "#fff"; ctx.lineWidth = 2; ctx.stroke();
    let a = ((g.rad * 180 / Math.PI) % 180 + 180) % 180; if (a > 90) a -= 180;
    const t = `${Math.abs(a).toFixed(1)}°`;
    ctx.font = "bold 12px Pretendard, sans-serif";
    const tw = ctx.measureText(t).width;
    ctx.fillStyle = "rgba(10,10,16,0.85)"; ctx.fillRect(-60 - tw / 2 - 6, 17, tw + 12, 18);
    ctx.fillStyle = "#fff"; ctx.textAlign = "center"; ctx.fillText(t, -60, 30);
    ctx.restore();
  };

  const draw = useCallback(() => {
    const c = canvasRef.current; if (!c) return;
    const ctx = c.getContext("2d"), dpr = window.devicePixelRatio || 1;
    const w = c.width / dpr, h = c.height / dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = "#000"; ctx.fillRect(0, 0, w, h);
    if (imgRef.current) coverDraw(ctx, imgRef.current, w, h, photo);
    if (grid) {
      ctx.save(); ctx.strokeStyle = "rgba(255,255,255,0.28)"; ctx.lineWidth = 1;
      for (let i = 1; i < 10; i++) {
        ctx.beginPath(); ctx.moveTo((w / 10) * i, 0); ctx.lineTo((w / 10) * i, h); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, (h / 10) * i); ctx.lineTo(w, (h / 10) * i); ctx.stroke();
      }
      ctx.strokeStyle = PRIMARY; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(w / 2, 0); ctx.lineTo(w / 2, h); ctx.stroke(); ctx.restore();
    }
    const renderScale = w / 300;
    marks.forEach((mark) => drawAnnotationMark(ctx, mark, w, h, { lineScale: renderScale, fontScale: renderScale }));
    if (draft) drawAnnotationMark(ctx, draft, w, h, { lineScale: renderScale, fontScale: renderScale });
    if (pending && !draft) drawAnnotationMark(ctx, { tool: "point", color, width, opacity, pts: [pending] }, w, h, { lineScale: renderScale, fontScale: renderScale });
    drawSelection(ctx, marks.find((mark) => mark.id === selectedMarkId), w, h, renderScale);
    if (ruler && !exportingRef.current) drawRuler(ctx, w, h);
  }, [marks, draft, pending, grid, ruler, color, width, opacity, photo, size, selectedMarkId]);
  useEffect(() => { draw(); }, [draw]);

  const pos = (e) => screenPointToImagePoint(e, imageFrame(), { zoom, panX: pan.x, panY: pan.y });
  const baseViewport = () => {
    const rect = imageFrame();
    return { width: Math.max(1, rect?.width || size.w || 1), height: Math.max(1, rect?.height || size.h || 1) };
  };
  const interactionViewport = () => {
    const viewport = baseViewport();
    return { width: viewport.width * zoom, height: viewport.height * zoom };
  };
  const down = (e) => {
    e.currentTarget.setPointerCapture?.(e.pointerId);
    ptrs.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    /* 손가락이 둘 — 자가 켜져 있으면 자 조절, 꺼져 있으면 사진 확대 */
    if (ptrs.current.size === 2 && !ruler) {
      const [a, b] = [...ptrs.current.values()];
      memoTapRef.current = null;
      if (editRef.current) { replaceMarks(editRef.current.before); editRef.current = null; }
      setDraft(null);
      pinch.current = {
        d0: Math.max(1, Math.hypot(b.x - a.x, b.y - a.y)),
        mx: (a.x + b.x) / 2, my: (a.y + b.y) / 2,
        z0: zoom, px: pan.x, py: pan.y,
      };
      return;
    }
    if (ptrs.current.size === 2 && ruler) {
      const [p1, p2] = [...ptrs.current.values()];
      memoTapRef.current = null;
      if (editRef.current) { replaceMarks(editRef.current.before); editRef.current = null; }
      setDraft(null);
      rulerDrag.current = null;
      gest.current = {
        mx: (p1.x + p2.x) / 2, my: (p1.y + p2.y) / 2,
        ang: (Math.atan2(p2.y - p1.y, p2.x - p1.x) * 180) / Math.PI,
        cx: ruler.cx, cy: ruler.cy, deg: ruler.deg,
      };
      return;
    }
    if (ptrs.current.size > 1) return;
    const raw = pos(e);
    const rect = imageFrame();
    const viewport = interactionViewport();
    const hitFontScale = (rect.width / 300) * zoom;
    if (tool === "eraser") {
      const hit = hitTestAnnotations(marks, raw, viewport, { includeHandles: false, measureText: measureCanvasText, fontScale: hitFontScale, bodyTolerance: 18 });
      if (hit) {
        if (!window.confirm("선택한 표시를 삭제할까요?")) return;
        commitMarks((items) => items.filter((_, index) => index !== hit.index));
        if (selectedMarkId === hit.markId) setSelectedMarkId(null);
      }
      return;
    }
    if (ruler) {
      const rct = imageFrame();
      const g = rulerGeom(rct.width, rct.height);
      const P = { x: raw.x * rct.width, y: raw.y * rct.height };
      const lp = toLocal(g, P);
      const rx = Math.min(150, g.L / 2 - 30);
      if (Math.hypot(lp.x - rx, lp.y - 26) < 26) { rulerDrag.current = { mode: "rot", a0: Math.atan2(P.y - g.C.y, P.x - g.C.x) - g.rad }; return; }
      /* 자 몸통과 그 아래에서는 절대 그어지지 않는다 — 누르면 자를 옮긴다 */
      if (lp.y >= -1) { rulerDrag.current = { mode: "move", dx: P.x - g.C.x, dy: P.y - g.C.y }; return; }
    }
    const editable = hitTestAnnotations(marks, raw, viewport, { tools: ["arrow", "text"], measureText: measureCanvasText, fontScale: hitFontScale, handleRadius: 22, bodyTolerance: 14 });
    if (editable) {
      const kind = editable.mark.tool === "text" ? "move-text" : editable.part === "start" ? "arrow-start" : editable.part === "end" ? "arrow-end" : "move-arrow";
      const anchor = editable.mark.pts?.[0] || raw;
      setSelectedMarkId(editable.markId);
      setColor(normalizeAnnotationColor(editable.mark.color, color));
      setWidth(closestHandwritingWidth(editable.mark.width));
      editRef.current = {
        pointerId: e.pointerId,
        markId: editable.markId,
        kind,
        origin: raw,
        originalPoints: (editable.mark.pts || []).map((point) => ({ ...point })),
        originalMark: { ...editable.mark, pts: (editable.mark.pts || []).map((point) => ({ ...point })) },
        grabOffset: kind === "move-text" ? { x: raw.x - anchor.x, y: raw.y - anchor.y } : null,
        before: marksRef.current,
      };
      return;
    }
    setSelectedMarkId(null);
    const p = ruler ? snapPt(raw) : raw;
    if (tool === "text") {
      const label = window.prompt("사진에 표시할 내용을 입력하세요", "");
      if (label?.trim()) commitMarks((items) => [...items, { id: uid(), tool, color, width, opacity, pts: [p], label: label.trim() }]);
      return;
    }
    if (tool === "memo") {
      memoTapRef.current = { pointerId: e.pointerId, point: p, startX: e.clientX, startY: e.clientY, moved: false };
      return;
    }
    if (tool === "hline" || tool === "vline") { setDraft({ id: uid(), tool, color, width, opacity, pts: [p] }); return; }
    if (tool === "angle") {
      if (!pending) { setDraft({ id: uid(), tool: "point", color, width, opacity, pts: [p] }); return; }
      setDraft({ id: uid(), tool: "angle", color, width, opacity, pts: [pending, p], label: degText(angleOf(pending, p)) });
      return;
    }
    setDraft({ id: uid(), tool, color, width, opacity, pts: [p, p], label: "" });
  };
  const move = (e) => {
    if (ptrs.current.has(e.pointerId)) ptrs.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (memoTapRef.current?.pointerId === e.pointerId
      && Math.hypot(e.clientX - memoTapRef.current.startX, e.clientY - memoTapRef.current.startY) > 10) {
      memoTapRef.current.moved = true;
    }
    if (pinch.current && ptrs.current.size >= 2 && !ruler) {
      const el = canvasRef.current; if (!el) return;
      const [a, b] = [...ptrs.current.values()];
      const d = Math.max(1, Math.hypot(b.x - a.x, b.y - a.y));
      const g = pinch.current;
      setZoom(Math.min(5, Math.max(1, g.z0 * (d / g.d0))));
      const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
      setPan({ x: g.px + (mx - g.mx), y: g.py + (my - g.my) });
      return;
    }
    if (gest.current && ptrs.current.size >= 2 && ruler) {
      const el = canvasRef.current; if (!el) return;
      const r = imageFrame();
      const [p1, p2] = [...ptrs.current.values()];
      const mx = (p1.x + p2.x) / 2, my = (p1.y + p2.y) / 2;
      const ang = (Math.atan2(p2.y - p1.y, p2.x - p1.x) * 180) / Math.PI;
      const g = gest.current;
      setRuler({
        cx: Math.min(0.98, Math.max(0.02, g.cx + (mx - g.mx) / r.width)),
        cy: Math.min(0.98, Math.max(0.02, g.cy + (my - g.my) / r.height)),
        deg: g.deg + (ang - g.ang),
      });
      return;
    }
    if (ptrs.current.size > 1) return;
    const raw = pos(e);
    if (rulerDrag.current && ruler) {
      const rct = imageFrame();
      const P = { x: raw.x * rct.width, y: raw.y * rct.height };
      const d = rulerDrag.current;
      if (d.mode === "move") setRuler((r) => ({ ...r, cx: Math.min(0.98, Math.max(0.02, (P.x - d.dx) / rct.width)), cy: Math.min(0.98, Math.max(0.02, (P.y - d.dy) / rct.height)) }));
      else setRuler((r) => ({ ...r, deg: ((Math.atan2(P.y - r.cy * rct.height, P.x - r.cx * rct.width) - d.a0) * 180) / Math.PI }));
      return;
    }
    if (editRef.current && editRef.current.pointerId === e.pointerId) {
      const edit = editRef.current, rect = imageFrame();
      const next = applyAnnotationDrag(edit.originalMark, edit, raw, { width: rect.width, height: rect.height }, { measureText: measureCanvasText, fontScale: rect.width / 300 });
      replaceMarks(marksRef.current.map((mark) => mark.id === edit.markId ? next : mark));
      return;
    }
    if (!draft) return;
    /* 자 몸통·아래를 지나가는 동안에는 선이 이어지지 않는다 */
    if (ruler) { const z = rulerZone(raw); if (!z.ok) return; }
    const p = ruler ? snapPt(raw) : raw;
    setDraft((d) => {
      if (!d) return d;
      if (d.tool === "hline" || d.tool === "vline" || d.tool === "point") return { ...d, pts: [p] };
      if (d.tool === "pen") return { ...d, pts: [...d.pts, p] };
      return { ...d, pts: [d.pts[0], p], label: d.tool === "angle" ? degText(angleOf(d.pts[0], p)) : "" };
    });
  };
  const up = (e) => {
    if (e && e.pointerId != null) ptrs.current.delete(e.pointerId);
    if (memoTapRef.current?.pointerId === e?.pointerId) {
      const memoTap = memoTapRef.current;
      memoTapRef.current = null;
      if (e?.type !== "pointercancel" && !memoTap.moved) setMemoDraft({ point: memoTap.point, text: "" });
      return;
    }
    if (ptrs.current.size < 2) { gest.current = null; pinch.current = null; }
    if (zoom <= 1.02 && (pan.x !== 0 || pan.y !== 0)) setPan({ x: 0, y: 0 });
    if (editRef.current && editRef.current.pointerId === e?.pointerId) {
      const edit = editRef.current; editRef.current = null;
      if (e?.type === "pointercancel") { replaceMarks(edit.before); return; }
      if (JSON.stringify(marksRef.current) !== JSON.stringify(edit.before)) {
        setUndoStack((history) => [...history, edit.before].slice(-40));
        setRedoStack([]);
      }
      return;
    }
    if (ptrs.current.size >= 1 && gest.current === null && !draft) return;
    if (rulerDrag.current) { rulerDrag.current = null; return; }
    if (!draft) return;
    const d = draft; setDraft(null);
    if (d.tool === "point") { setPending(d.pts[0]); return; }
    if (d.tool === "hline" || d.tool === "vline") { commitMarks((items) => [...items, d]); return; }
    if (d.tool === "angle") {
      if (Math.hypot(d.pts[1].x - d.pts[0].x, d.pts[1].y - d.pts[0].y) < 0.02) return;
      const deg = angleOf(d.pts[0], d.pts[1]);
      commitMarks((items) => [...items, { ...d, angle: deg, label: degText(deg) }]);
      setPending(null);
      return;
    }
    if (d.tool !== "pen" && Math.hypot(d.pts[1].x - d.pts[0].x, d.pts[1].y - d.pts[0].y) < 0.02) return;
    commitMarks((items) => [...items, d]);
    if (d.tool === "arrow") setSelectedMarkId(d.id);
  };
  const pickTool = (k) => { setTool(k); setPending(null); setDraft(null); };
  const prepareGuide = (kind) => {
    const preset = {
      shoulder: { tool: "hline", pts: [{ x: 0.5, y: 0.28 }] },
      pelvis: { tool: "hline", pts: [{ x: 0.5, y: 0.54 }] },
      spine: { tool: "vline", pts: [{ x: 0.5, y: 0.5 }] },
      knee: { tool: "hline", pts: [{ x: 0.5, y: 0.73 }] },
      ankle: { tool: "hline", pts: [{ x: 0.5, y: 0.88 }] },
    }[kind];
    if (!preset) return;
    setTool(preset.tool);
    setGuideSheet(false);
  };
  const saveMemo = () => {
    const text = String(memoDraft?.text || "").trim();
    if (!text || !memoDraft?.point) return;
    const id = uid();
    commitMarks((items) => [...items, { id, tool: "text", fontStyle: "handwriting", color, width, opacity, pts: [memoDraft.point], label: text, source: "manual" }]);
    setSelectedMarkId(id);
    setMemoDraft(null);
  };
  const openExportPreview = () => {
    exportingRef.current = true;
    draw();
    try {
      const url = canvasRef.current?.toDataURL("image/jpeg", 0.92);
      if (!url) throw new Error("preview_empty");
      setExportPreview({ url, filename: `사진기록_${label}_${todayISO()}.jpg`, manual: false });
    } catch (error) {
      onToast?.({ ok: false, msg: "최종 이미지를 만들지 못했습니다. 편집 내용은 그대로 유지됩니다." });
    } finally {
      exportingRef.current = false;
      draw();
    }
  };
  const runPreviewExport = async (saveOnly) => {
    if (!exportPreview?.url || exportBusy) return;
    setExportBusy(true);
    try {
      const [canvas, exactBlob] = await Promise.all([
        canvasFromPreviewUrl(exportPreview.url),
        fetch(exportPreview.url).then((response) => response.blob()),
      ]);
      const result = await exportCanvas(canvas, exportPreview.filename, "PilaTeacher 사진 기록", saveOnly, exactBlob);
      if (result.how === "fail") throw new Error("image_export_failed");
      if (result.how === "manual") {
        setExportPreview((current) => current ? { ...current, manual: true } : current);
        onToast?.({ ok: false, msg: "자동 저장이 막혀 있습니다. 미리보기 이미지를 길게 눌러 저장해 주세요." });
        return;
      }
      if (result.how === "saved") onToast?.({ ok: true, msg: "이미지를 저장했습니다." });
      if (result.how === "gallery") onToast?.({ ok: true, msg: "사진 앱에 저장했습니다." });
      if (result.how === "documents") onToast?.({ ok: true, msg: "내 파일 > 문서 > PilaTeacher에 저장했습니다." });
      if (result.how === "copied") onToast?.({ ok: true, msg: "이미지를 복사했습니다. 원하는 앱에 붙여넣어 주세요." });
      if (result.how === "shared") onToast?.({ ok: true, msg: "이미지 공유를 완료했습니다." });
    } catch (error) {
      onToast?.({ ok: false, msg: saveOnly ? "이미지를 저장하지 못했습니다. 미리보기에서 다시 시도해 주세요." : "이미지를 공유하지 못했습니다. 미리보기에서 다시 시도해 주세요." });
    } finally {
      setExportBusy(false);
    }
  };
  const toolItems = [
    { k: "guide", l: "기준선", I: Crosshair }, { k: "ruler", l: "자", I: Move },
    { k: "pen", l: "펜", I: Pencil }, { k: "arrow", l: "화살표", I: ArrowUpRight },
    { k: "memo", l: "손메모", I: MessageSquare }, { k: "eraser", l: "삭제", I: Trash2 },
  ];
  const presetColorSet = new Set(ANNOTATION_PRESET_COLORS.map((item) => item.color));
  const customRecentColors = recentColors.filter((item) => !presetColorSet.has(item)).slice(0, 4).map((item) => ({ color: item, label: `최근 색상 ${item}` }));
  const selectedMark = marks.find((mark) => mark.id === selectedMarkId);
  const instruction = selectedMark?.tool === "arrow"
    ? "양 끝의 원을 끌어 방향을 고치고, 선 가운데를 끌어 통째로 옮기세요"
    : selectedMark?.tool === "text"
      ? "선택된 손메모를 끌어 정확한 위치에 놓으세요"
      : ruler
        ? "자 윗변을 따라 그립니다 · 자는 두 손가락으로 옮기고 돌릴 수 있어요"
        : tool === "memo"
          ? "문구를 놓을 곳을 누른 뒤 입력하세요 · 입력 후 다시 끌어 옮길 수 있어요"
          : tool === "eraser"
            ? "지울 표시를 눌러 주세요"
            : "표시를 눌러 다시 선택할 수 있습니다 · 두 손가락으로 사진 확대";

  return (
    <div className="safe-all fixed inset-0 z-50 flex flex-col bg-photo" style={{ background: "linear-gradient(180deg, #171A1D 0%, #111620 100%)" }}>
      <div className="flex items-center gap-1.5 px-3 py-2.5" style={{ backgroundColor: "rgba(24,29,40,.94)", borderBottom: "1px solid rgba(255,255,255,.08)", boxShadow: "0 8px 24px rgba(0,0,0,.18)" }}>
        <button onClick={requestClose} aria-label="편집 닫기" className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl" style={{ backgroundColor: "rgba(255,255,255,.08)", border: "1px solid rgba(255,255,255,.08)" }}><X size={18} color="#fff" /></button>
        <div className="min-w-0 flex-1 px-1">
          <p className="truncate text-sm font-extrabold text-white">직접 그리기 · {label}</p>
          <p className="mt-0.5 truncate text-[10px] font-semibold" style={{ color: "rgba(255,255,255,.52)" }}>표시는 저장 후에도 다시 수정할 수 있습니다</p>
        </div>
        <button aria-label="실행 취소" disabled={!pending && !undoStack.length} onClick={undoMarks} className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl disabled:opacity-30" style={{ backgroundColor: "rgba(255,255,255,.08)" }}><RotateCcw size={15} color="#fff" /></button>
        <button aria-label="다시 실행" disabled={!redoStack.length} onClick={redoMarks} className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl disabled:opacity-30" style={{ backgroundColor: "rgba(255,255,255,.08)" }}><Redo2 size={15} color="#fff" /></button>
        <button onClick={async () => { const next = marks.map((mark) => ({ ...mark, source: mark.source || "manual" })); try { const stored = await onSave(next); if (stored === false) throw Object.assign(new Error("annotation save rejected"), { code: "annotation_save_rejected" }); initialMarks.current = JSON.stringify(next); onClose(); } catch (error) { deviceLog("assessment_annotation_save_failed", { memberId: photo.memberId, assessmentId: photo.assessmentId, view: photo.view, ...deviceError(error) }); onToast?.({ ok: false, msg: "표시를 저장하지 못했습니다. 현재 편집 내용은 유지됩니다. 다시 시도해 주세요." }); } }} className="flex h-11 shrink-0 items-center rounded-xl px-4 text-xs font-extrabold text-white" style={{ backgroundColor: BRAND, boxShadow: "0 5px 14px rgba(76,67,153,.35)" }}>완료</button>
      </div>
      {fresh && (
        <p className="mx-4 mb-1 mt-2 rounded-xl px-3 py-2 text-center text-xs font-bold text-white" style={{ backgroundColor: "rgba(76,67,153,.88)", border: "1px solid rgba(185,178,244,.28)" }}>
          사진이 등록됐습니다 · 필요한 표시나 손메모를 남겨 주세요 (건너뛰려면 왼쪽 위 X)
        </p>
      )}
      <div className="flex min-h-0 flex-1 items-center justify-center px-2 py-1">
        <div ref={wrapRef} className="relative overflow-hidden rounded-xl" style={{ aspectRatio: "3 / 4", maxHeight: "100%", maxWidth: "min(100%, 540px)", width: "100%", border: "1px solid rgba(255,255,255,.12)", boxShadow: "0 16px 36px rgba(0,0,0,.34)" }}>
          <canvas ref={canvasRef} className="absolute inset-0 touch-none" onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={up}
            style={{ transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`, transformOrigin: "center center" }} />
          {zoom > 1.02 && (
            <button onClick={resetZoom} className="absolute right-2 top-2 rounded-full px-3 py-1.5 text-xs font-extrabold"
              style={{ backgroundColor: "rgba(255,255,255,.92)", color: "#17171F" }}>{zoom.toFixed(1)}× · 원래대로</button>
          )}
        </div>
      </div>
      <div className="px-1.5 pb-1.5 pt-1.5" style={{ background: "linear-gradient(180deg, rgba(19,24,34,.9), rgba(15,19,28,.98))", borderTop: "1px solid rgba(255,255,255,.07)", boxShadow: "0 -12px 28px rgba(0,0,0,.22)" }}>
        <div className="rounded-xl p-1.5" style={{ backgroundColor: "rgba(31,38,52,.94)", border: "1px solid rgba(255,255,255,.08)", boxShadow: "0 8px 24px rgba(0,0,0,.2)" }}>
          <div className="pt-hscroll flex gap-1 overflow-x-auto">
            {toolItems.map(({ k, l, I }) => {
              const active = k === "guide" ? ["hline", "vline"].includes(tool) : k === "ruler" ? Boolean(ruler) : tool === k;
              return <button key={k} onClick={() => { if (k === "guide") setGuideSheet(true); else if (k === "ruler") { setRuler((value) => value ? null : { cx: 0.5, cy: 0.58, deg: 0 }); pickTool("pen"); } else pickTool(k); }} className="flex h-11 min-w-[50px] shrink-0 items-center justify-center gap-1 rounded-lg px-1.5 text-[11px] font-bold"
                style={active ? { backgroundColor: BRAND, color: "#fff", boxShadow: "0 5px 12px rgba(76,67,153,.32)" } : { backgroundColor: "rgba(255,255,255,.055)", color: "rgba(255,255,255,.76)", border: "1px solid rgba(255,255,255,.055)" }}
                aria-pressed={active}><I size={20} strokeWidth={2.1} /><span className="whitespace-nowrap">{l}</span></button>;
            })}
          </div>
          <div className="mt-1 border-t pt-1" style={{ borderColor: "rgba(255,255,255,.08)" }}>
            <div className="pt-hscroll flex items-center gap-0.5 overflow-x-auto">
              {[...ANNOTATION_PRESET_COLORS, ...customRecentColors].map(({ color: optionColor, label: optionLabel }) => (
                <button key={optionColor} onClick={() => chooseColor(optionColor)} className="relative flex h-11 w-11 shrink-0 items-center justify-center rounded-full" aria-label={optionLabel} aria-pressed={color === optionColor}>
                  <span className="flex h-8 w-8 items-center justify-center rounded-full" style={{ backgroundColor: optionColor, border: color === optionColor ? "3px solid #FFFFFF" : "1px solid rgba(255,255,255,.22)", boxShadow: color === optionColor ? "0 0 0 2px #6C5FD4" : optionColor === "#FFFFFF" ? "inset 0 0 0 1px rgba(0,0,0,.14)" : "none" }}>
                    {color === optionColor && <Check size={13} strokeWidth={3} color={["#FFFFFF", "#FFD43B"].includes(optionColor) ? "#17171F" : "#FFFFFF"} />}
                  </span>
                </button>
              ))}
              <button type="button" onClick={openColorPicker} className="relative flex h-11 min-w-[44px] shrink-0 items-center justify-center gap-0.5 rounded-lg" style={{ color: "#fff", backgroundColor: "rgba(255,255,255,.065)", border: "1px solid rgba(255,255,255,.10)" }} aria-label="다른 색 직접 선택">
                <Plus size={13} /><Palette size={14} />
              </button>
            </div>
          </div>
          <div className="mt-1 flex min-h-11 items-center gap-1 border-t pt-1" style={{ borderColor: "rgba(255,255,255,.08)" }}>
            <span className="mr-auto text-[10px] font-bold text-white">{tool === "memo" || selectedMark?.tool === "text" ? "손메모 크기" : "선 굵기"}</span>
            {(tool === "memo" || selectedMark?.tool === "text" ? HANDWRITING_SIZE_OPTIONS : [{ value: 2, label: "얇게" }, { value: 4, label: "보통" }, { value: 6, label: "굵게" }]).map((option) => <button type="button" key={option.value} onClick={() => tool === "memo" || selectedMark?.tool === "text" ? setHandwritingSize(option.value) : setWidth(option.value)} className="flex h-11 min-w-[48px] items-center justify-center gap-1 rounded-md px-1.5 text-[10px] font-bold" style={{ backgroundColor: closestHandwritingWidth(width) === option.value ? "#FFFFFF" : "rgba(255,255,255,.06)", color: closestHandwritingWidth(width) === option.value ? "#17171F" : "rgba(255,255,255,.72)", border: `1px solid ${closestHandwritingWidth(width) === option.value ? "#FFFFFF" : "rgba(255,255,255,.07)"}` }}><span className="inline-block w-3 rounded-full" style={{ height: Math.max(1, option.value / 2), backgroundColor: closestHandwritingWidth(width) === option.value ? "#17171F" : "#FFFFFF" }} />{option.label}</button>)}
            {selectedMark?.tool === "text" && <button type="button" onClick={deleteSelectedMark} aria-label="선택한 손메모 삭제" className="flex h-11 w-11 shrink-0 items-center justify-center rounded-lg" style={{ backgroundColor: "rgba(255,59,48,.16)", color: "#FF8A84", border: "1px solid rgba(255,59,48,.24)" }}><Trash2 size={15} /></button>}
          </div>
        </div>
        <div className="mt-1 flex min-h-11 items-center gap-1.5">
          <p className="min-w-0 flex-1 px-1 text-[10px] font-semibold leading-snug" style={{ color: selectedMark ? "#C9C4FF" : "rgba(255,255,255,.52)" }}>{instruction}</p>
          <button type="button" onClick={openExportPreview} className="flex h-11 shrink-0 items-center justify-center gap-1.5 rounded-lg px-3 text-[10px] font-extrabold text-white" style={{ backgroundColor: "rgba(108,95,212,.92)", border: "1px solid rgba(255,255,255,.12)" }}><ImagePlus size={14} />저장·공유</button>
        </div>
      </div>
      {exportPreview && (
        <div className="safe-all fixed inset-0 z-[60] flex flex-col bg-photo" style={{ backgroundColor: "#111620" }}>
          <div className="flex items-center gap-2 px-3 py-2.5" style={{ backgroundColor: "rgba(24,29,40,.98)", borderBottom: "1px solid rgba(255,255,255,.08)" }}>
            <button type="button" onClick={() => setExportPreview(null)} aria-label="편집으로 돌아가기" className="flex h-11 w-11 items-center justify-center rounded-xl" style={{ backgroundColor: "rgba(255,255,255,.08)" }}><ChevronLeft size={19} color="#fff" /></button>
            <span className="min-w-0 flex-1"><span className="block text-sm font-extrabold text-white">최종 이미지 미리보기</span><span className="block text-[10px]" style={{ color: "rgba(255,255,255,.55)" }}>보이는 모습 그대로 저장·공유됩니다</span></span>
          </div>
          <div className="flex min-h-0 flex-1 items-center justify-center p-3"><img src={exportPreview.url} alt="직접그리기 최종 이미지" className="max-h-full max-w-full rounded-xl object-contain" style={{ boxShadow: "0 18px 42px rgba(0,0,0,.42)" }} /></div>
          {exportPreview.manual && <p className="px-4 pb-2 text-center text-xs font-bold text-white">자동 저장이 막힌 기기에서는 위 이미지를 길게 눌러 저장하세요.</p>}
          <div className="grid grid-cols-3 gap-2 px-3 pb-3 pt-2" style={{ backgroundColor: "rgba(24,29,40,.98)", borderTop: "1px solid rgba(255,255,255,.08)" }}>
            <button type="button" disabled={exportBusy} onClick={() => setExportPreview(null)} className="flex h-12 items-center justify-center gap-1 text-xs font-bold text-white disabled:opacity-50" style={{ borderRadius: 11, backgroundColor: "rgba(255,255,255,.08)" }}><ChevronLeft size={15} />뒤로</button>
            <button type="button" disabled={exportBusy} onClick={() => runPreviewExport(true)} className="flex h-12 items-center justify-center gap-1 text-xs font-extrabold text-white disabled:opacity-50" style={{ borderRadius: 11, backgroundColor: BRAND }}><Download size={15} />이미지 저장</button>
            <button type="button" disabled={exportBusy} onClick={() => runPreviewExport(false)} className="flex h-12 items-center justify-center gap-1 text-xs font-extrabold disabled:opacity-50" style={{ borderRadius: 11, backgroundColor: "#FFFFFF", color: "#17171F" }}><Share2 size={15} />공유</button>
          </div>
        </div>
      )}
      {guideSheet && <ScheduleBottomSheet title="기준선 선택" subtitle="종류를 고른 뒤 사진 위에서 원하는 위치를 직접 눌러 조절하세요" onClose={() => setGuideSheet(false)}>
        <div className="space-y-2">
          {[{ key: "shoulder", label: "어깨선", sub: "좌우 어깨 높이 확인" }, { key: "pelvis", label: "골반선", sub: "좌우 골반 높이 확인" }, { key: "spine", label: "척추 중심선", sub: "수직 중심 정렬" }, { key: "knee", label: "무릎선", sub: "좌우 무릎 높이" }, { key: "ankle", label: "발목선", sub: "좌우 발목 높이" }].map((item, index) => <button type="button" key={item.key} onClick={() => prepareGuide(item.key)} className="flex min-h-12 w-full items-center gap-3 px-3 text-left" style={{ borderRadius: 10, backgroundColor: index < 2 ? TINT : CANVAS, border: `1px solid ${index < 2 ? "#D5D1EB" : LINE}` }}><span className="min-w-0 flex-1"><span className="block text-sm font-bold" style={{ color: INK }}>{item.label}</span><span className="mt-0.5 block text-xs" style={{ color: SUB }}>{item.sub} · 위치는 다음 화면에서 지정</span></span><ChevronRight size={15} style={{ color: FAINT }} /></button>)}
        </div>
      </ScheduleBottomSheet>}
      {colorPickerOpen && <ScheduleBottomSheet title="사용자 지정 색상" subtitle="화면 안에서 색을 확인한 뒤 적용하세요" onClose={() => setColorPickerOpen(false)}>
        <div className="space-y-4">
          <div className="flex items-center gap-3 rounded-xl p-3" style={{ backgroundColor: CANVAS }}><span className="h-12 w-12 shrink-0 rounded-xl" style={{ backgroundColor: customColorPreview, border: `1px solid ${LINE}` }} /><span className="min-w-0 flex-1"><span className="block text-xs font-bold" style={{ color: INK }}>미리보기</span><span className="mt-1 block text-xs font-extrabold tabular-nums" style={{ color: SUB }}>{customColorPreview}</span></span></div>
          {[{ key: "h", label: "색상", min: 0, max: 359, background: "linear-gradient(90deg,#FF3B30,#FFD43B,#34C759,#35B8FF,#356AE6,#AF52DE,#FF3B30)" }, { key: "s", label: "선명도", min: 0, max: 100, background: `linear-gradient(90deg,${hslToHex(customColor.h, 0, customColor.l)},${hslToHex(customColor.h, 100, customColor.l)})` }, { key: "l", label: "밝기", min: 5, max: 95, background: `linear-gradient(90deg,#000000,${hslToHex(customColor.h, customColor.s, 50)},#FFFFFF)` }].map((row) => <label key={row.key} className="block"><span className="mb-2 block text-xs font-bold" style={{ color: INK2 }}>{row.label}</span><input type="range" min={row.min} max={row.max} value={customColor[row.key]} onChange={(event) => setCustomColor((current) => ({ ...current, [row.key]: Number(event.target.value) }))} className="h-11 w-full" style={{ accentColor: customColorPreview, background: row.background, touchAction: "pan-x" }} /></label>)}
          <div className="grid grid-cols-2 gap-2"><button type="button" onClick={() => setColorPickerOpen(false)} className="h-12 text-sm font-bold" style={{ borderRadius: 10, backgroundColor: CANVAS, color: INK2 }}>취소</button><button type="button" onClick={() => { chooseColor(customColorPreview); setColorPickerOpen(false); }} className="h-12 text-sm font-extrabold text-white" style={{ borderRadius: 10, backgroundColor: BRAND }}>적용</button></div>
        </div>
      </ScheduleBottomSheet>}
      {memoDraft && <ScheduleBottomSheet title="손글씨 메모" subtitle="여러 줄로 입력할 수 있고, 넣은 뒤 사진에서 다시 끌어 옮길 수 있습니다" onClose={() => setMemoDraft(null)}>
        <div className="space-y-3"><textarea autoFocus rows={4} value={memoDraft.text} onChange={(event) => setMemoDraft((value) => ({ ...value, text: event.target.value }))} placeholder={"회원에게 보여줄 메모를 입력하세요\n줄을 바꿔 적어도 그대로 표시됩니다"} className="w-full resize-none px-3 py-3 outline-none" style={{ borderRadius: 11, border: `1px solid ${LINE}`, backgroundColor: CANVAS, color: INK, fontFamily: "'Nanum Pen Script', 'Segoe Print', cursive", fontSize: 24, lineHeight: 1.25 }} /><button type="button" disabled={!memoDraft.text.trim()} onClick={saveMemo} className="h-12 w-full text-sm font-extrabold text-white disabled:opacity-40" style={{ borderRadius: 11, backgroundColor: BRAND }}>사진에 넣고 위치 조정하기</button></div>
      </ScheduleBottomSheet>}
    </div>
  );
}

function MemberList({ members, selectedId, onSelect, onAdd, onOpenFav, favCount, schedule, draftCount, onCleanDrafts }) {
  const [q, setQ] = useState("");
  const [cleanAsk, setCleanAsk] = useState(false);
  const [seg, setSeg] = useState("all");
  const [todayOnly, setTodayOnly] = useState(false);
  const [sortBy, setSortBy] = useState("default");
  const todayMap = useMemo(() => {
    const map = {};
    (schedule || []).filter((s) => s?.date === todayISO()).sort((a, b) => a.start.localeCompare(b.start)).forEach((s) => {
      attendeesOf(s).forEach((a) => { if (!map[a.memberId]) map[a.memberId] = { start: s.start, type: s.type, status: a.status }; });
    });
    return map;
  }, [schedule]);
  const todayCount = members.filter((m) => todayMap[m.id]).length;
  const holdCount = members.filter((m) => isHold(m)).length;
  const individualCount = members.filter((m) => isActive(m) && !m.duetWith).length;
  const duetCount = members.filter((m) => isActive(m) && !!m.duetWith).length;
  const expiringCount = members.filter((m) => isActive(m) && (left(m) <= 3 || (ddaySafe(m.contractEnd) ?? 999) <= 14)).length;
  /* 듀엣 짝을 항상 바로 아래에 붙인다 */
  const pairUp = (arr) => {
    const byId = {}; arr.forEach((m) => { byId[m.id] = m; });
    const out = [], used = new Set();
    arr.forEach((m) => {
      if (used.has(m.id)) return;
      out.push(m); used.add(m.id);
      const p = m.duetWith && byId[m.duetWith];
      if (p && !used.has(p.id)) { out.push(p); used.add(p.id); }
    });
    return out;
  };
  const filtered = pairUp(members
    .filter((m) => {
      if (seg === "individual") return isActive(m) && !m.duetWith;
      if (seg === "duet") return isActive(m) && !!m.duetWith;
      if (seg === "hold") return isHold(m);
      if (seg === "expiring") return isActive(m) && (left(m) <= 3 || (ddaySafe(m.contractEnd) ?? 999) <= 14);
      return true;
    })
    .filter((m) => (todayOnly ? !!todayMap[m.id] : true))
    .filter((m) => (m.name || "").includes(q) || (m.goal || "").includes(q) || (m.instructor || "").includes(q))
    .sort((a, b) => {
      if (sortBy === "leftDesc") return left(b) - left(a);
      if (sortBy === "leftAsc") return left(a) - left(b);
      const ta = todayMap[a.id]?.start, tb = todayMap[b.id]?.start;
      if (ta && tb) return ta.localeCompare(tb);
      if (ta) return -1;
      if (tb) return 1;
      return 0;
    }));
  return (
    <div className="space-y-2.5">
      <div className="flex gap-2">
        <div className="relative flex-1">
          <Search size={16} className="absolute left-3.5 top-3.5" style={{ color: SUB }} />
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="회원명 · 목표 · 강사 검색"
            className="h-11 w-full rounded-xl border-0 bg-white pl-10 pr-3 text-sm outline-none"
            style={{ border: `1px solid ${LINE}`, boxShadow: "0 1px 2px rgba(20,20,43,.04)" }} />
        </div>
        <button onClick={onAdd} className="flex h-11 items-center gap-1 rounded-xl px-4 text-sm font-extrabold text-white" style={{ backgroundColor: BRAND }}><UserPlus size={16} /> 추가</button>
      </div>
      {draftCount > 0 && (cleanAsk ? (
        <div className="flex flex-wrap items-center gap-2 rounded-2xl px-4 py-3" style={{ backgroundColor: BAD_S }}>
          <AlertTriangle size={15} style={{ color: BAD }} />
          <span className="min-w-0 flex-1 text-sm font-bold" style={{ color: INK }}>이름도 기록도 없는 회원 {draftCount}명을 지울까요?</span>
          <button onClick={() => { onCleanDrafts && onCleanDrafts(); setCleanAsk(false); }} className="rounded-full px-3 py-1.5 text-xs font-extrabold text-white" style={{ backgroundColor: BAD }}>정리</button>
          <button onClick={() => setCleanAsk(false)} className="rounded-full bg-white px-3 py-1.5 text-xs font-bold" style={{ color: SUB }}>취소</button>
        </div>
      ) : (
        <button onClick={() => setCleanAsk(true)} className="flex w-full items-center gap-2 rounded-2xl px-4 py-3" style={{ backgroundColor: WARN_S }}>
          <Pencil size={15} className="shrink-0" style={{ color: WARN }} />
          <span className="min-w-0 flex-1 text-left text-sm font-bold" style={{ color: INK }}>작성 중인 회원 {draftCount}명 · 이름이 비어 있습니다</span>
          <span className="shrink-0 text-xs font-extrabold" style={{ color: WARN }}>정리하기</span>
        </button>
      ))}
      {todayCount > 0 && (
        <button onClick={() => setTodayOnly((v) => !v)} className="flex h-10 w-full items-center gap-2 rounded-xl px-3"
          style={todayOnly ? { backgroundColor: BRAND, color: "#fff" } : { backgroundColor: CARD, color: INK, border: `1px solid ${LINE}` }}>
          <Calendar size={15} style={{ color: todayOnly ? "#fff" : PRIMARY }} />
          <span className="text-sm font-extrabold">오늘 수업 회원 {todayCount}명</span>
          <span className="ml-auto text-xs font-bold" style={{ color: todayOnly ? "rgba(255,255,255,0.8)" : SUB }}>
            {todayOnly ? "전체 보기" : "이 회원만 보기"}
          </span>
        </button>
      )}
      <div className="flex items-center gap-1.5">
        <div className="flex min-w-0 flex-1 gap-1 overflow-x-auto rounded-xl bg-white p-1" style={{ border: `1px solid ${LINE}` }}>
          {[
            { k: "all", l: "전체", n: members.length },
            { k: "individual", l: "개인", n: individualCount },
            { k: "duet", l: "듀엣", n: duetCount },
            { k: "hold", l: "홀딩", n: holdCount },
            { k: "expiring", l: "이용권 임박", n: expiringCount },
          ].map((o) => (
            <button key={o.k} onClick={() => setSeg(o.k)} className="flex h-8 shrink-0 items-center justify-center gap-1 rounded-lg px-2 text-xs font-bold"
              style={seg === o.k ? { backgroundColor: TINT, color: BRAND } : { color: SUB }}>
              {o.l} <span className="tabular-nums">{o.n}</span>
            </button>
          ))}
        </div>
        <button onClick={onOpenFav} className="flex h-10 items-center gap-1 rounded-xl bg-white px-3 text-xs font-bold" style={{ color: favCount ? WARN : SUB, border: `1px solid ${LINE}` }}>
          <Star size={14} fill={favCount ? WARN : "none"} /> 즐겨찾기 {favCount || 0}
        </button>
      </div>
      {filtered.length > 1 && (
        <button onClick={() => setSortBy((s) => (s === "default" ? "leftDesc" : s === "leftDesc" ? "leftAsc" : "default"))}
          className="flex h-10 w-full items-center gap-2 rounded-xl px-3"
          style={sortBy === "default" ? { backgroundColor: CARD, border: `1px solid ${LINE}` } : { backgroundColor: TINT, border: `1px solid ${PRIMARY}33` }}>
          <ArrowUpDown size={14} style={{ color: PRIMARY }} />
          <span className="text-xs font-extrabold" style={{ color: sortBy === "default" ? INK : PRIMARY }}>
            {sortBy === "leftDesc" ? "잔여 횟수 많은 순" : sortBy === "leftAsc" ? "잔여 횟수 적은 순" : "기본 순서 (오늘 수업 먼저)"}
          </span>
          <span className="ml-auto text-xs font-bold" style={{ color: SUB }}>
            {sortBy === "default" ? "많은 순으로" : sortBy === "leftDesc" ? "적은 순으로" : "기본으로"}
          </span>
        </button>
      )}
      {filtered.length === 0 && (
        <Card className="p-8 text-center">
          {members.length === 0 ? (
            <>
              <Users size={22} className="mx-auto" style={{ color: FAINT }} />
              <p className="mt-2 text-sm font-bold" style={{ color: INK }}>등록된 회원이 없습니다.</p>
              <Sub className="mt-1">오른쪽 위 '추가'를 눌러 첫 회원을 등록해 주세요.</Sub>
            </>
          ) : q ? (
            <>
              <p className="text-sm font-bold" style={{ color: INK }}>'{q}' 검색 결과가 없습니다.</p>
              <button onClick={() => setQ("")} className="mt-3 rounded-2xl px-4 py-2 text-xs font-extrabold text-white" style={{ backgroundColor: BRAND }}>검색 지우기</button>
            </>
          ) : (
            <>
              <p className="text-sm font-bold" style={{ color: INK }}>
                {seg === "hold" ? "홀딩 중인 회원이 없습니다." : seg === "expiring" ? "이용권 만료가 임박한 회원이 없습니다." : "조건에 맞는 회원이 없습니다."}
              </p>
              <Sub className="mt-1">다른 상태에 회원이 있습니다. 눌러서 이동하세요.</Sub>
              <div className="mt-3 flex justify-center gap-1.5">
                {[{ k: "all", l: "전체", n: members.length }, { k: "hold", l: "홀딩", n: holdCount }]
                  .filter((o) => o.k !== seg && o.n > 0)
                  .map((o) => (
                    <button key={o.k} onClick={() => setSeg(o.k)} className="rounded-2xl px-4 py-2 text-xs font-extrabold text-white" style={{ backgroundColor: BRAND }}>
                      {o.l} {o.n}명 보기
                    </button>
                  ))}
              </div>
            </>
          )}
        </Card>
      )}
      {filtered.map((m) => {
        const on = m.id === selectedId, total = left(m), low = total <= 3;
        const lastD = lastDoneOf(schedule, m.id);
        const idle = lastD ? Math.max(0, -dday(lastD)) : null;
        const idleC = idle === null ? SUB : idle >= 5 ? BAD : idle >= 3 ? WARN : GOOD;
        const d = ddaySafe(m.contractEnd);
        return (
          <button key={m.id} onClick={() => onSelect(m.id)} className="w-full rounded-xl bg-white p-3 text-left"
            style={{ border: `1px solid ${on ? PRIMARY : LINE}`, boxShadow: on ? `0 0 0 1px ${PRIMARY}` : SHADOW }}>
            <div className="flex items-center gap-3">
              <div className="flex h-11 w-11 items-center justify-center rounded-2xl text-sm font-extrabold" style={{ backgroundColor: TINT, color: PRIMARY }}>{(m.name || "?").slice(0, 1)}</div>
              <div className="min-w-0 flex-1">
                <p className="flex items-center gap-1 truncate font-extrabold" style={{ color: isDraft(m) ? SUB : INK }}>
                  {isDraft(m) ? "작성 중" : m.name} {ageOf(m) !== null ? <span className="text-xs font-medium" style={{ color: SUB }}>{ageOf(m)}세</span> : null}
                  {m.duetWith && members.some((x) => x.id === m.duetWith) && (
                    <span className="shrink-0 rounded-full px-1.5 py-0.5 text-xs font-extrabold" style={{ backgroundColor: TINT, color: PRIMARY }}>
                      듀엣 · {members.find((x) => x.id === m.duetWith)?.name || "짝"}
                    </span>
                  )}
                </p>
                {todayMap[m.id]
                  ? <p className="truncate text-xs font-extrabold" style={{ color: PRIMARY }}>오늘 {todayMap[m.id].start} · {todayMap[m.id].type}</p>
                  : <Sub className="truncate">{m.goal || "목표 미입력"}</Sub>}
              </div>
              <div className="text-right">
                <p className="text-sm font-extrabold tabular-nums" style={{ color: low ? BAD : INK }}>{total}회</p>
                <Sub>정규 {num(m.regular)} · 서비스 {num(m.service)}</Sub>
              </div>
              <ChevronRight size={16} style={{ color: FAINT }} />
            </div>
            <div className="mt-3 flex items-center gap-2">
              <div className="h-1.5 flex-1 overflow-hidden rounded-full" style={{ backgroundColor: CANVAS }}>
                <div className="h-full rounded-full" style={{ width: `${Math.min(100, Math.max(0, (total / (num(m.total) || total || 1)) * 100))}%`, backgroundColor: low ? BAD : PRIMARY }} />
              </div>
              {isEnded(m) && <span className="rounded-full px-2 py-0.5 text-xs font-bold" style={{ backgroundColor: CANVAS, color: SUB }}>종료{m.endedAt ? ` ${md(m.endedAt)}` : ""}</span>}
              {isHold(m) && <span className="rounded-full px-2 py-0.5 text-xs font-bold" style={{ backgroundColor: WARN_S, color: WARN }}>홀딩{m.holdUntil ? ` · 복귀 ${md(m.holdUntil)}` : ""}</span>}
              {isActive(m) && d !== null && d <= 14 && <span className="rounded-full px-2 py-0.5 text-xs font-bold" style={{ backgroundColor: WARN_S, color: WARN }}>{d < 0 ? "만료" : `D-${d}`}</span>}
              {!isEnded(m) && (isHold(m)
                ? <span className="rounded-full px-2 py-0.5 text-xs font-bold" style={{ backgroundColor: CANVAS, color: SUB }}>홀딩 중</span>
                : idle === null
                  ? <span className="rounded-full px-2 py-0.5 text-xs font-bold" style={{ backgroundColor: CANVAS, color: SUB }}>첫 수업 전</span>
                  : <span className="rounded-full px-2 py-0.5 text-xs font-extrabold" style={{ backgroundColor: `${idleC}14`, color: idleC }}>
                      {restLabel(idle)}
                    </span>)}
            </div>
          </button>
        );
      })}
    </div>
  );
}
function ReferenceMemberList({ members, schedule, settings, onSelect, onAdd }) {
  const [q, setQ] = useState("");
  const [filter, setFilter] = useState("all");
  const [sort, setSort] = useState("name");
  const [registerOpen, setRegisterOpen] = useState(false);
  const realMembers = visibleMembers(members).filter((m) => !isDraft(m));
  const nextOf = (memberId) => (schedule || [])
    .filter((s) => hasMember(s, memberId) && `${s.date} ${s.start}` >= `${todayISO()} 00:00`)
    .sort((a, b) => `${a.date} ${a.start}`.localeCompare(`${b.date} ${b.start}`))[0] || null;
  const matchFilter = (m) => {
    if (filter === "private") return isActive(m) && !m.duetWith;
    if (filter === "duet") return isActive(m) && !!m.duetWith;
    if (filter === "hold") return isHold(m);
    if (filter === "renew") return isActive(m) && (left(m) <= 3 || (ddaySafe(m.contractEnd) ?? 999) <= 14);
    return true;
  };
  const list = realMembers.filter(matchFilter)
    .filter((m) => !q.trim() || (m.name || "").includes(q.trim()) || (m.phone || "").includes(q.trim()))
    .sort((a, b) => {
      if (sort === "remaining") return left(a) - left(b);
      if (sort === "expiry") return String(a.contractEnd || "9999").localeCompare(String(b.contractEnd || "9999"));
      if (sort === "recent") return String(b.notes?.[0]?.date || "").localeCompare(String(a.notes?.[0]?.date || ""));
      return String(a.name || "").localeCompare(String(b.name || ""), "ko");
    });
  const filters = [
    { k: "all", l: "전체" }, { k: "private", l: "개인" }, { k: "duet", l: "듀엣" },
    { k: "hold", l: "홀딩" }, { k: "renew", l: "이용권 임박" },
  ];
  const countOf = (k) => realMembers.filter((m) => {
    if (k === "all") return true;
    if (k === "private") return isActive(m) && !m.duetWith;
    if (k === "duet") return isActive(m) && !!m.duetWith;
    if (k === "hold") return isHold(m);
    return isActive(m) && (left(m) <= 3 || (ddaySafe(m.contractEnd) ?? 999) <= 14);
  }).length;
  const singleInstructorMode = !Array.isArray(settings?.staffMembers) || settings.staffMembers.length <= 1;
  return (
    <div className="flex h-full min-h-0 flex-col" style={{ backgroundColor: PAGE }}>
      <header className="flex shrink-0 items-center" style={{ height: 52, padding: "0 14px", backgroundColor: CARD, borderBottom: `1px solid ${LINE}` }}>
        <div className="min-w-0 flex-1"><h1 style={{ fontSize: 18, fontWeight: 600, color: INK }}>회원</h1><p style={{ fontSize: 11, color: SUB }}>전체 {realMembers.length}명</p></div>
        <button type="button" onClick={() => setRegisterOpen(true)} className="flex items-center gap-1 text-white"
          style={{ height: 36, padding: "0 12px", borderRadius: 8, backgroundColor: BRAND, fontSize: 13, fontWeight: 600 }}><Plus size={15} />추가</button>
      </header>
      <div className="shrink-0" style={{ padding: "10px 12px 8px", backgroundColor: CARD, borderBottom: `1px solid ${LINE}` }}>
        <div className="relative">
          <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: SUB }} />
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="회원 이름 또는 연락처 검색" className="w-full border-0 pl-9 pr-3 text-sm outline-none"
            style={{ height: 40, borderRadius: 8, backgroundColor: CANVAS, color: INK }} />
        </div>
        <div className="mt-2 flex min-w-0 items-center gap-2">
          <div className="pt-hscroll flex min-w-0 flex-1 items-center gap-1 overflow-x-auto">
            {filters.map((o) => <button type="button" key={o.k} onClick={() => setFilter(o.k)} className="shrink-0"
              style={{ height: 32, padding: "0 10px", borderRadius: 16, fontSize: 12, fontWeight: 600,
                backgroundColor: filter === o.k ? TINT : CARD, color: filter === o.k ? BRAND : SUB,
                border: `1px solid ${filter === o.k ? RING : LINE}` }}>{o.l} <span className="tabular-nums">{countOf(o.k)}</span></button>)}
          </div>
          <label className="flex h-8 shrink-0 items-center gap-1 px-2" style={{ borderRadius: 8, border: `1px solid ${LINE}`, backgroundColor: CARD, color: SUB }}><ArrowUpDown size={13} />
            <select value={sort} onChange={(e) => setSort(e.target.value)} className="border-0 bg-transparent p-0 text-xs font-semibold outline-none" style={{ color: SUB }}>
              <option value="name">이름순</option><option value="remaining">잔여 적은순</option><option value="expiry">만료 임박순</option><option value="recent">최근 기록순</option>
            </select>
          </label>
        </div>
      </div>
      <div className="pt-scroll min-h-0 flex-1 overflow-y-auto" style={{ padding: "10px 12px 16px" }}>
        {!list.length && <div className="py-12 text-center"><Users size={22} className="mx-auto" style={{ color: FAINT }} /><p className="mt-2 text-sm font-semibold" style={{ color: INK }}>{q ? "검색 결과가 없습니다" : "조건에 맞는 회원이 없습니다"}</p></div>}
        <div className="pt-member-card-grid">{list.map((m) => {
          const remaining = left(m), expiry = ddaySafe(m.contractEnd), next = nextOf(m.id);
          const renew = isActive(m) && (remaining <= 3 || (expiry !== null && expiry <= 14));
          return (
            <div key={m.id} className="relative"><button type="button" onClick={() => onSelect(m.id)} className="h-full w-full text-left"
              style={{ padding: "12px 14px", borderRadius: 14, backgroundColor: CARD, border: `1px solid ${LINE}`, boxShadow: "0 1px 4px rgba(28,36,51,.05)" }}>
              <div className="flex items-start gap-2">
                <div className="min-w-0 flex-1">
                  <div className="flex min-w-0 items-center gap-1.5"><p className="truncate" style={{ fontSize: 15, fontWeight: 600, color: INK }}>{m.name}</p>
                    {isHold(m) && <span style={{ padding: "2px 6px", borderRadius: 5, fontSize: 10, fontWeight: 600, backgroundColor: WARN_S, color: WARN }}>홀딩</span>}
                    {isEnded(m) && <span style={{ padding: "2px 6px", borderRadius: 5, fontSize: 10, fontWeight: 600, backgroundColor: CANVAS, color: SUB }}>종료</span>}
                    {renew && <span style={{ padding: "2px 6px", borderRadius: 5, fontSize: 10, fontWeight: 600, backgroundColor: BAD_S, color: BAD }}>재등록 필요</span>}
                  </div>
                  <p className="mt-1 truncate" style={{ fontSize: 12, color: SUB }}>{singleInstructorMode ? (m.duetWith ? "듀엣" : "개인") : `${m.instructor || "담당 미지정"} · ${m.duetWith ? "듀엣" : "개인"}`}</p>
                </div>
                <div className="shrink-0 text-right"><p className="tabular-nums" style={{ fontSize: 17, lineHeight: 1, fontWeight: 600, color: remaining <= 3 ? BAD : INK }}>{remaining}<span style={{ fontSize: 11 }}>회</span></p><p style={{ marginTop: 3, fontSize: 10, color: SUB }}>잔여</p></div>
                <ChevronRight size={16} style={{ color: FAINT }} />
              </div>
              <div className="mt-2 flex min-w-0 items-center gap-2" style={{ paddingTop: 8, borderTop: `1px solid ${LINE}` }}>
                <span className="truncate" style={{ fontSize: 11, color: SUB }}>만료 {m.contractEnd ? ymd(m.contractEnd) : "미설정"}</span><span style={{ color: LINE }}>·</span>
                <span className="min-w-0 flex-1 truncate" style={{ fontSize: 11, color: next ? INK2 : SUB }}>다음 예약 {next ? `${md(next.date)} ${next.start}` : "없음"}</span>
              </div>
            </button></div>
          );
        })}</div>
      </div>
      {registerOpen && <MemberRegisterSheet members={realMembers} onClose={() => setRegisterOpen(false)}
        onOpenExisting={(id) => { setRegisterOpen(false); onSelect(id); }}
        onCreate={(v) => { onAdd(v); setRegisterOpen(false); }} />}
    </div>
  );
}

function MemberRegisterSheet({ members, onOpenExisting, onClose, onCreate }) {
  const [f, setF] = useState({ name: "", phone: "", birth: "", lessonType: "private", defaultLessonDuration: String(DEFAULT_CLASS_DURATION), goal: "", focus: "", memo: "", passName: "개인 10회", regular: "10", startDate: todayISO(), contractEnd: shift(todayISO(), 90) });
  const [error, setError] = useState("");
  const submit = () => {
    const name = f.name.trim(), phone = f.phone.replace(/\D/g, "");
    if (!name) { setError("회원 이름을 입력해 주세요."); return; }
    const duplicate = (members || []).find((m) => String(m.name || "").trim() === name
      && (!phone || String(m.phone || "").replace(/\D/g, "") === phone));
    if (duplicate) { setError("같은 회원이 이미 등록되어 있습니다."); return; }
    const count = num(f.regular);
    onCreate({ name, phone: f.phone.trim(), birth: f.birth || "", lessonType: f.lessonType, defaultLessonDuration: Number(f.defaultLessonDuration) || DEFAULT_CLASS_DURATION, goal: f.goal.trim(),
      focus: f.focus.split("\n").map((x) => x.trim()).filter(Boolean), passName: f.passName.trim(),
      regular: count, total: count, startDate: f.startDate, contractEnd: f.contractEnd,
      notes: f.memo.trim() ? [{ id: uid(), date: todayISO(), type: "상담", body: f.memo.trim(), tags: [] }] : [] });
  };
  return (
    <Sheet title="회원 등록" sub="필수 정보를 입력하면 실제 회원 데이터로 저장됩니다" onClose={onClose} wide safeTop
      footer={<button type="button" disabled={!f.name.trim() || !num(f.regular)} onClick={submit} className="w-full text-sm font-semibold text-white disabled:opacity-40" style={{ height: 48, borderRadius: 8, backgroundColor: BRAND }}>회원 등록</button>}>
      <div className="space-y-3">
        <Field label="회원 이름"><input autoFocus value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} className={inputCls} /></Field>
        <Field label="연락처"><input value={f.phone} onChange={(e) => setF({ ...f, phone: e.target.value })} className={inputCls} /></Field>
        <Field label="생년월일" hint={f.birth ? `${ageFromBirth(f.birth)}세 · 오늘 기준 자동 계산` : "나이는 자동 계산됩니다"}><input type="date" value={f.birth} max={todayISO()} onChange={(e) => setF({ ...f, birth: e.target.value })} className={inputCls} /></Field>
        <Field label="수업 유형"><div className="grid w-full min-w-0 grid-cols-3 gap-2">{[{k:"private",l:"개인"},{k:"duet",l:"듀엣"},{k:"group",l:"그룹"}].map((o) => <button type="button" key={o.k} onClick={() => setF({ ...f, lessonType: o.k, passName: `${o.l} ${f.regular || 0}회` })} className="min-w-0 whitespace-nowrap px-1" style={{ height: 38, borderRadius: 8, border: `1px solid ${f.lessonType === o.k ? BRAND : LINE}`, backgroundColor: f.lessonType === o.k ? TINT : CARD, color: f.lessonType === o.k ? BRAND_D : SUB, fontSize: 12, fontWeight: 600 }}>{o.l}</button>)}</div></Field>
        <Field label="기본 수업시간" hint="새 일정을 만들 때 자동 적용됩니다"><select value={f.defaultLessonDuration} onChange={(e) => setF({ ...f, defaultLessonDuration: e.target.value })} className={inputCls}>{[30, 50, 60, 80].map((value) => <option key={value} value={value}>{value}분</option>)}</select></Field>
        <Field label="목표"><input value={f.goal} onChange={(e) => setF({ ...f, goal: e.target.value })} className={inputCls} /></Field>
        <Field label="주의사항" hint="한 줄에 하나"><textarea rows={2} value={f.focus} onChange={(e) => setF({ ...f, focus: e.target.value })} className={`${inputCls} h-auto resize-none py-2.5`} /></Field>
        <div className="grid grid-cols-2 gap-2"><Field label="이용권"><input value={f.passName} onChange={(e) => setF({ ...f, passName: e.target.value })} className={inputCls} /></Field><Field label="총 횟수"><input inputMode="numeric" value={f.regular} onChange={(e) => setF({ ...f, regular: e.target.value.replace(/\D/g, "") })} className={inputCls} /></Field></div>
        <div className="grid grid-cols-2 gap-2"><Field label="시작일"><input type="date" value={f.startDate} onChange={(e) => setF({ ...f, startDate: e.target.value })} className={inputCls} /></Field><Field label="만료일"><input type="date" value={f.contractEnd} onChange={(e) => setF({ ...f, contractEnd: e.target.value })} className={inputCls} /></Field></div>
        <Field label="상담 메모"><textarea rows={2} value={f.memo} onChange={(e) => setF({ ...f, memo: e.target.value })} className={`${inputCls} h-auto resize-none py-2.5`} /></Field>
        {error && <div className="flex items-center gap-2" style={{ padding: "9px 10px", borderRadius: 8, backgroundColor: WARN_S, color: WARN, fontSize: 12 }}><AlertCircle size={14} />{error}{error.includes("이미") && <button type="button" className="ml-auto font-semibold" onClick={() => { const name = f.name.trim(), phone = f.phone.replace(/\D/g, ""); const d = (members || []).find((m) => String(m.name || "").trim() === name && (!phone || String(m.phone || "").replace(/\D/g, "") === phone)); if (d) onOpenExisting(d.id); }}>기존 회원 열기</button>}</div>}
      </div>
    </Sheet>
  );
}

function ReferenceMemberDetail({ member, schedule, photos, settings, canViewSettlement = true, onBack, onPatch, onSaveNote, onSchedule, onAssess, onToast, onDelete, onDeactivate }) {
  const [sheet, setSheet] = useState(null);
  const [edit, setEdit] = useState({});
  const [memo, setMemo] = useState("");
  const [memoMeta, setMemoMeta] = useState(null);
  const [memoImportant, setMemoImportant] = useState(false);
  const [pass, setPass] = useState({ name: "", regular: "", service: "", total: "", end: "" });
  const [passConfirm, setPassConfirm] = useState(false);
  const [rateEdit, setRateEdit] = useState("");
  const [rateConfirm, setRateConfirm] = useState(false);
  const [saving, setSaving] = useState("");
  const [saveError, setSaveError] = useState("");
  const [hold, setHold] = useState({ start: todayISO(), end: shift(todayISO(), 14), reason: "", extend: true });
  const [releaseArmed, setReleaseArmed] = useState(false);
  const [reviewNote, setReviewNote] = useState(null);
  const [reviewDraft, setReviewDraft] = useState(null);
  const [reviewEditing, setReviewEditing] = useState(false);
  const [deleteName, setDeleteName] = useState("");
  const [deleteBusy, setDeleteBusy] = useState(false);
  useEffect(() => {
    if (!reviewNote) return;
    setReviewDraft(reviewNote.lessonRecord?.structuredDraft || null);
    setReviewEditing(false);
  }, [reviewNote]);
  const lessons = (schedule || []).filter((s) => hasMember(s, member.id)).sort((a, b) => `${b.date} ${b.start}`.localeCompare(`${a.date} ${a.start}`));
  const notes = [...(member.notes || [])].sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")));
  const lessonNotes = notes.filter((note) => !["상담", "인바디"].includes(note.type));
  /* 수업기록에 붙는 기구는 강사가 일정에서 고른 값이다 — 기록 본문(AI 요약)에서 추론하지 않는다 */
  const noteEquipText = (note) => {
    const lesson = (schedule || []).find((item) => String(item?.id || "") === String(note?.sid || ""));
    return lesson ? lessonEquipFullText(lesson) : "";
  };
  const consultationNotes = notes.filter((note) => note.type === "상담").sort((a, b) => Number(Boolean(b.important)) - Number(Boolean(a.important)) || String(b.date || "").localeCompare(String(a.date || "")));
  const prepText = (value, fallback = "기록 없음") => Array.isArray(value) ? (value.map((item) => typeof item === "string" ? item : item?.text).filter(Boolean).join(" · ") || fallback) : (String(value || "").trim() || fallback);
  const memoryBriefing = useMemo(() => createMemberBriefing({ member }), [member]);
  const memorySummary = useMemo(() => memberMemorySummary(memoryBriefing), [memoryBriefing]);
  const activeMemory = (memoryBriefing.memories || []).filter((entry) => ["active", "conflict"].includes(entry?.status));
  const latestMemoryOf = (predicate) => activeMemory.filter(predicate).sort((a, b) => String(b.lastSeenAt || "").localeCompare(String(a.lastSeenAt || "")))[0] || null;
  const repeatedMemory = latestMemoryOf((entry) => entry.status !== "conflict" && Number(entry.seenCount) >= 2);
  const nextCheckMemory = latestMemoryOf((entry) => entry.type === "next_focus");
  const recentChangeMemories = activeMemory.filter((entry) => entry.status === "conflict" || entry.type === "response" || entry.type === "milestone")
    .sort((a, b) => String(b.lastSeenAt || "").localeCompare(String(a.lastSeenAt || ""))).slice(0, 3);
  const latestMemorySession = memoryBriefing.sessions?.at(-1) || null;
  const memorySourceDate = (entry) => {
    const sourced = (entry?.sourceRefs || []).filter((source) => (source?.type === "session" || source?.type === "assessment") && source?.date).map((source) => String(source.date)).sort().at(-1);
    return sourced || String(entry?.lastSeenAt || "");
  };
  const memoryDateLabel = (value) => {
    const match = String(value || "").match(/^\d{4}-(\d{2})-(\d{2})/);
    return match ? `${Number(match[1])}.${Number(match[2])}` : "";
  };
  const latestRecordDisplay = selectLastLessonMemoryRecord(latestMemorySession);
  const pendingStructuredNote = lessonNotes.find((note) => note?.lessonRecord?.stage === "structured_draft" && note.lessonRecord?.structuredDraft && !hasLessonRecordReviewFlag(note.lessonRecord));
  const pendingRawNote = lessonNotes.find((note) => note?.lessonRecord?.stage === "raw_transcript" && !hasLessonRecordReviewFlag(note.lessonRecord));
  const pendingStructured = pendingStructuredNote?.lessonRecord?.structuredDraft || null;
  const pendingDate = pendingStructuredNote?.date || pendingRawNote?.date || "";
  const pendingRows = pendingStructured ? [
    ["didToday", "지난 수업", pendingStructured.didToday],
    ["observations", "최근 변화", pendingStructured.observations],
    ["responses", "회원 반응", pendingStructured.responses],
    ["nextFocus", "선생님이 남긴 다음 확인", pendingStructured.nextFocus],
  ].map(([key, label, value]) => ({ key: `pending-${key}`, label, value: prepText(value, ""), date: pendingDate, origin: "ai", sourceLabel: "[AI · 확인 전]", pendingNote: pendingStructuredNote })).filter((row) => row.value) : pendingRawNote ? [{ key: "pending-raw", label: "지난 수업", value: String(pendingRawNote.lessonRecord?.rawTranscript || pendingRawNote.transcript || pendingRawNote.body || "").trim(), date: pendingDate, origin: "instructor", sourceLabel: "선생님 기록", pendingNote: null }] : [];
  const memoryRows = pendingRows.length ? pendingRows : [
    latestMemorySession && latestRecordDisplay ? { key: "last", label: "지난 수업", value: latestRecordDisplay.text, date: latestMemorySession.date, origin: latestRecordDisplay.origin, sourceLabel: latestRecordDisplay.sourceLabel, provenanceSource: latestRecordDisplay.provenanceSource, memory: null } : null,
    repeatedMemory ? { key: "repeated", label: "반복해서 기록된 내용", value: memorySummary.repeated, date: memorySourceDate(repeatedMemory), origin: repeatedMemory.origin, memory: repeatedMemory } : null,
    nextCheckMemory ? { key: "next", label: "선생님이 남긴 다음 확인", value: nextCheckMemory.text, date: memorySourceDate(nextCheckMemory), origin: nextCheckMemory.origin, memory: nextCheckMemory } : null,
    ...recentChangeMemories.map((entry) => ({ key: `change-${entry.id}`, label: entry.type === "response" ? "회원 반응" : "최근 변화", value: entry.status === "conflict" ? "최근 기록이 달라졌습니다" : entry.text, date: memorySourceDate(entry), origin: entry.presentationOrigin || entry.origin, memory: entry })),
  ].filter(Boolean);
  const hasMemoryOverview = memoryRows.length > 0;
  useEffect(() => {
    trackMemberMemoryUsage("briefing_rendered", { count: 1 });
    trackMemberMemoryUsage("briefing_opened", { count: 1 });
  }, [member.id]);
  const assessmentSets = useMemo(() => normalizeAssessmentSets(photos, { memberId: member.id }), [photos, member.id]);
  const resumableAssessment = useMemo(() => selectResumableAssessment(assessmentSets, { memberId: member.id }), [assessmentSets, member.id]);
  const completedAssessments = assessmentSets.filter((assessment) => assessment.status === "completed");
  const lastAssessment = completedAssessments[0] || null;
  const afterReminder = postureAfterReminder(completedAssessments);
  const lastAssessmentMetrics = lastAssessment?.poses.flatMap((pose) => pose.metrics || []).slice(0, 2) || [];
  const next = lessons.filter((s) => attOf(s, member.id)?.status === "booked" && new Date(`${s.date}T${s.start || "00:00"}:00`).getTime() >= Date.now()).sort((a, b) => `${a.date} ${a.start}`.localeCompare(`${b.date} ${b.start}`))[0] || null;
  const recentLesson = lessons.find((lesson) => lesson.date <= todayISO() && attOf(lesson, member.id)?.status === "done") || null;
  const memberUnit = paidAvg(member);
  const settlementUnit = rateFor(member, member.lessonType === "group" ? "그룹" : "개인레슨", settings);
  const singleInstructorMode = !Array.isArray(settings?.staffMembers) || settings.staffMembers.length <= 1;
  const membership = membershipDisplay(member);
  const openEdit = () => { setEdit({ name: member.name || "", phone: member.phone || "", birth: member.birth || "", instructor: member.instructor || "", lessonType: member.lessonType || "private", defaultLessonDuration: lessonDurationOf(member) }); setSaveError(""); setSheet("basic"); };
  const openPreparation = () => { setEdit({ goal: member.goal || "", focus: (member.focus || []).join(", ") }); setSaveError(""); setSheet("preparation"); };
  const openMembership = () => { setPass({ name: member.passName || "", regular: String(num(member.regular)), service: String(num(member.service)), total: String(num(member.total)), end: member.contractEnd || "" }); setPassConfirm(false); setSaveError(""); setSheet("membership"); };
  const openRate = () => { setRateEdit(String(Number(member.payRate) > 0 ? Number(member.payRate) : settlementUnit)); setRateConfirm(false); setSaveError(""); setSheet("rate"); };
  const openMemo = () => { setMemo(""); setMemoMeta(null); setMemoImportant(false); setSaveError(""); setSheet("memo"); };
  const openRecord = () => { setMemo(""); setMemoMeta(null); setSaveError(""); setSheet("record"); };
  const commitPatch = async (key, change, close = true) => {
    setSaving(key); setSaveError("");
    try {
      const stored = await onPatch(change);
      if (stored === false) throw new Error("save_failed");
      onToast?.({ ok: true, msg: "변경한 영역을 저장했습니다." });
      if (close) setSheet(null);
      return true;
    } catch (error) { setSaveError("저장하지 못했습니다. 입력 내용을 확인하고 다시 시도해 주세요."); return false; }
    finally { setSaving(""); }
  };
  const commitNote = async () => {
    if (!memo.trim()) return;
    setSaving(sheet || "note"); setSaveError("");
    try {
      const stored = await onSaveNote(sheet === "memo" ? "상담" : "개인레슨", memo.trim(), memoMeta, { important: sheet === "memo" && memoImportant });
      if (stored === false) throw new Error("save_failed");
      setMemoMeta(null); setSheet(null);
    } catch (error) { setSaveError("메모를 저장하지 못했습니다. 다시 시도해 주세요."); }
    finally { setSaving(""); }
  };
  const openRecordReview = (note) => {
    setReviewNote(note);
    setReviewDraft(note?.lessonRecord?.structuredDraft || null);
    setReviewEditing(false);
    setSheet("record-review");
  };
  const confirmRecordReview = async () => {
    if (!reviewNote || !reviewDraft) return;
    const lessonRecord = { ...reviewNote.lessonRecord, structuredDraft: reviewDraft, confirmationStatus: "confirmed" };
    const transcript = String(lessonRecord.rawTranscript || reviewNote.transcript || "").trim();
    const body = structuredRecordBody(reviewDraft, transcript);
    const stored = await onSaveNote(reviewNote.type || "개인레슨", body, {
      transcript,
      aiSummary: reviewNote.aiSummary || reviewDraft,
      aiSummaryTeacherEdited: reviewDraft,
      aiSummaryStatus: AI_STATUSES.CONFIRMED,
      aiMeta: reviewNote.aiMeta || lessonRecord.aiMeta || null,
      lessonRecord,
      voiceSource: reviewNote.voiceSource || lessonRecord.source || "unknown",
      recordedAt: reviewNote.recordedAt || lessonRecord.recordedAt,
    }, { confirmed: true, upsert: true, existingNoteId: reviewNote.id });
    if (stored !== false) { setReviewNote(null); setReviewDraft(null); setSheet(null); }
  };
  const rejectBriefingLine = async (briefingLine) => {
    const targets = (briefingLine?.memoryIds || []).filter((memoryId) => memoryBriefing.memories.find((entry) => entry.id === memoryId)?.origin !== "instructor");
    if (!targets.length) return;
    let nextMemory = memoryBriefing.memories;
    targets.forEach((memoryId) => { nextMemory = rejectMemoryEntry(nextMemory, memoryId); });
    await commitPatch("memory-reject", { aiMemory: nextMemory }, false);
  };
  const holdHistory = member.holdHistory || [];
  const sectionStyle = { backgroundColor: CARD, border: `1px solid ${LINE}`, borderRadius: 12, padding: "12px 14px" };
  const Section = ({ title, action, children }) => <section style={sectionStyle}><div className="mb-2 flex items-center gap-2"><h2 className="min-w-0 flex-1" style={{ fontSize: 14, fontWeight: 600, color: INK }}>{title}</h2>{action}</div>{children}</section>;
  return (
    <div className="relative flex h-full min-h-0 flex-col" style={{ backgroundColor: PAGE }}>
      <header className="flex shrink-0 items-center" style={{ height: 52, padding: "0 8px", backgroundColor: CARD, borderBottom: `1px solid ${LINE}` }}>
        <button type="button" onClick={onBack} aria-label="회원 목록" className="pt-member-back flex h-11 w-11 items-center justify-center" style={{ color: SUB }}><ChevronLeft size={19} /></button>
        <div className="min-w-0 flex-1"><h1 className="truncate" style={{ fontSize: 17, fontWeight: 600, color: INK }}>{member.name || "이름 미입력"}</h1><p style={{ fontSize: 11, color: SUB }}>{isHold(member) ? "홀딩" : isEnded(member) ? "종료" : "활성"}{singleInstructorMode ? "" : ` · 담당 ${member.instructor || "미지정"}`}</p></div>
      </header>
      <div className="grid shrink-0 grid-cols-3 gap-1.5" aria-label="회원 빠른 실행" style={{ padding: "7px 12px", backgroundColor: CARD, borderBottom: `1px solid ${LINE}` }}>
        {[{ l: "수업 기록", I: Pencil, fn: openRecord }, { l: "메모 추가", I: MessageSquare, fn: openMemo }].map(({ l, I, fn }) => <button type="button" key={l} onClick={fn} className="flex h-10 items-center justify-center gap-1.5" style={{ borderRadius: 9, backgroundColor: TINT, color: BRAND_D, fontSize: 12, fontWeight: 700 }}><I size={14} />{l}</button>)}
        <a href={member.phone ? `tel:${String(member.phone).replace(/[^0-9+]/g, "")}` : undefined} aria-disabled={!member.phone} onClick={(event) => { if (!member.phone) event.preventDefault(); }} className="flex h-10 items-center justify-center gap-1.5" style={{ borderRadius: 9, backgroundColor: CANVAS, color: member.phone ? INK2 : FAINT, fontSize: 12, fontWeight: 700 }}><Smartphone size={14} />연락하기</a>
      </div>
      <main className="pt-scroll min-h-0 flex-1 overflow-y-auto" style={{ padding: "8px 12px calc(18px + max(env(safe-area-inset-bottom, 0px), 12px))", scrollPaddingTop: 8 }}>
        <div className="space-y-2">
          <section data-member-section="top-summary" style={{ ...sectionStyle, backgroundColor: TINT, borderColor: RING }}>
            <div className="flex items-center gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl text-base font-extrabold text-white" style={{ background: GRAD }}>{(member.name || "?").slice(0, 1)}</span><span className="min-w-0 flex-1"><span className="block truncate text-base font-extrabold" style={{ color: INK }}>{member.name || "이름 미입력"}</span><span className="mt-0.5 block text-xs" style={{ color: SUB }}>{next ? `다음 수업 ${ymd(next.date)} ${next.start}` : "다음 예약 없음"}</span></span><span className="shrink-0 text-right"><span className="block text-2xl font-extrabold tabular-nums" style={{ color: left(member) <= 3 ? BAD : BRAND }}>{left(member)}회</span><span className="block text-[10px]" style={{ color: SUB }}>잔여</span></span></div>
          </section>
          <section data-member-section="memory-first" aria-label={`AI가 기억하는 ${member.name || "회원"}님`} style={{ ...sectionStyle, padding: hasMemoryOverview ? "10px 14px 4px" : "12px 14px" }}>
            <div className="mb-1 flex items-center gap-2"><Sparkles size={14} style={{ color: BRAND_D }} /><h2 className="min-w-0 flex-1 truncate text-sm font-extrabold" style={{ color: INK }}>AI가 기억하는 {member.name || "회원"}님</h2></div>
            {!hasMemoryOverview ? <div className="rounded-lg px-3 py-3" style={{ backgroundColor: CANVAS }}><p style={{ fontSize: 12, color: INK2 }}>아직 작성된 수업 기록이 없습니다.</p><p className="mt-1" style={{ fontSize: 10, lineHeight: 1.45, color: SUB }}>수업 기록을 저장하면 지난 수업과 다음 확인 내용을 이곳에서 이어서 볼 수 있어요.</p></div> : memoryRows.map((row, index) => <div key={row.key} className="flex items-start gap-3" style={{ padding: "9px 0", borderTop: index ? `1px solid ${LINE}` : "none" }}><p className="w-[112px] shrink-0" style={{ fontSize: 10, fontWeight: 700, color: SUB }}>{row.label}</p><div className="min-w-0 flex-1"><p className="line-clamp-2" style={{ fontSize: 11, lineHeight: 1.45, fontWeight: 650, color: row.key === "next" ? BRAND_D : INK2 }}>{row.value}</p><div className="mt-1 flex min-h-[14px] items-center gap-1.5">{row.sourceLabel ? row.pendingNote ? <button type="button" onClick={() => { setReviewNote(row.pendingNote); setSheet("record-review"); }} className="rounded-full px-1.5 py-0.5" style={{ fontSize: 9, fontWeight: 700, color: BRAND_D, backgroundColor: TINT }}>{row.sourceLabel}</button> : <span style={{ fontSize: 9, fontWeight: 700, color: row.sourceLabel === "[AI]" ? BRAND_D : SUB }}>{row.sourceLabel}</span> : row.origin === "ai" && <span style={{ fontSize: 9, fontWeight: 700, color: BRAND_D }}>[AI]</span>}{row.memory?.source === "posture_analysis" && <span style={{ fontSize: 9, fontWeight: 700, color: SUB }}>체형분석</span>}{memoryDateLabel(row.date) && <span className="tabular-nums" style={{ fontSize: 9, color: SUB }}>· {memoryDateLabel(row.date)}</span>}{row.memory?.origin === "ai" && <button type="button" onClick={() => rejectBriefingLine({ memoryIds: [row.memory.id] })} className="ml-auto shrink-0 text-[9px] font-bold" style={{ color: SUB }}>숨기기</button>}</div></div></div>)}
          </section>
          <details data-member-management-card="recent-lessons" style={{ ...sectionStyle, padding: 0, overflow: "hidden" }}>
            <summary aria-label="최근 수업기록 관리 카드 열기" className="flex min-h-14 cursor-pointer list-none items-center gap-3 px-3.5 py-3"><span className="min-w-0 flex-1"><span className="block truncate text-sm font-extrabold" style={{ color: INK }}>최근 수업기록</span><span className="mt-0.5 block truncate text-[10px]" style={{ color: SUB }}>{lessonNotes.length ? `${ymd(lessonNotes[0].date)} · ${lessonNotes[0].type || "수업"}` : "아직 작성된 기록이 없습니다"}</span></span><ChevronDown size={16} style={{ color: SUB }} /></summary>
            <div data-member-management-content="recent-lessons" style={{ padding: "0 12px 12px" }}>{lessonNotes.length > 0 ? <Section title="최근 수업 기록" action={<button type="button" onClick={() => setSheet("records-all")} style={{ fontSize: 12, fontWeight: 600, color: BRAND }}>전체 기록 보기</button>}>
              {lessonNotes.slice(0, 3).map((note) => { const summary = note.aiSummaryTeacherEdited || note.aiSummary || {}; const structured = note.lessonRecord?.confirmedRecord || note.lessonRecord?.structuredDraft || {}; const provenanceSource = lessonRecordProvenanceSource(note.lessonRecord); const rawOnly = provenanceSource === "fallback_raw"; const rawText = String(structured.rawTranscript || note.lessonRecord?.rawTranscript || note.transcript || note.body || "").trim(); const detailCount = rawOnly ? 0 : (structured.observations?.length || 0) + (structured.responses?.length || 0) + (summary.pain?.length || 0) + (summary.improvements?.length || 0); const pending = note.lessonRecord?.stage === "structured_draft"; const reviewRequired = hasLessonRecordReviewFlag(note.lessonRecord) || hasLessonRecordReviewFlag(note); return <div key={note.id} style={{ padding: "8px 0", borderTop: `1px solid ${LINE}` }}><div className="flex items-center gap-2"><p className="min-w-0 flex-1 truncate" style={{ fontSize: 10, color: SUB }}>{ymd(note.date)} · {note.type || "수업"}{noteEquipText(note) ? ` · ${noteEquipText(note)}` : ""}</p>{reviewRequired ? <span style={{ fontSize: 9, color: WARN }}>녹음 확인 필요</span> : pending ? <button type="button" onClick={() => { setReviewNote(note); setSheet("record-review"); }} className="rounded-full px-2 py-1" style={{ fontSize: 9, fontWeight: 700, color: BRAND_D, backgroundColor: TINT }}>확인 필요</button> : null}{note.lessonRecord?.reconcileStatus === "link_review_required" && <span style={{ fontSize: 9, color: WARN }}>연결 확인 필요</span>}{note.lessonRecord?.status === "confirmed_unstructured" && <span style={{ fontSize: 9, color: WARN }}>직접 작성</span>}{!rawOnly && summary.memberCondition && <span style={{ fontSize: 9, color: BRAND_D }}>{summary.memberCondition}</span>}</div><p className="mt-1 line-clamp-2" style={{ fontSize: 12, lineHeight: 1.45, color: INK2 }}>{reviewRequired ? "녹음 내용을 확인한 뒤 기록에 반영해 주세요." : rawOnly ? rawText : prepText(structured.didToday || summary.todayExercises, note.body)}</p>{!reviewRequired && detailCount > 0 && <p className="mt-1 line-clamp-2" style={{ fontSize: 10, color: WARN }}>{[prepText(structured.observations?.length ? structured.observations : summary.pain, ""), prepText(structured.responses?.length ? structured.responses : summary.improvements, "")].filter(Boolean).join(" · ")}</p>}</div>; })}
            </Section> : <p className="py-3 text-xs" style={{ color: SUB }}>아직 작성된 수업 기록이 없습니다</p>}</div>
          </details>
          <details data-member-management-card="posture" style={{ ...sectionStyle, padding: 0, overflow: "hidden", backgroundColor: afterReminder.show ? WARN_S : CARD }}>
            <summary aria-label="체형변화·사진 관리 카드 열기" className="flex min-h-14 cursor-pointer list-none items-center gap-3 px-3.5 py-3"><span className="min-w-0 flex-1"><span className="block truncate text-sm font-extrabold" style={{ color: INK }}>체형변화·사진</span><span className="mt-0.5 block truncate text-[10px]" style={{ color: SUB }}>{lastAssessment ? `마지막 촬영 ${ymd((lastAssessment.completedAt || lastAssessment.at).slice(0, 10))}` : "아직 완료된 분석이 없습니다"}</span></span>{afterReminder.show && <span className="shrink-0 rounded-full px-2 py-1 text-[9px] font-extrabold" style={{ backgroundColor: CARD, color: WARN }}>{afterReminder.label}</span>}<ChevronDown size={16} style={{ color: SUB }} /></summary>
            <div data-member-management-content="posture" style={{ padding: "0 12px 12px" }}>
          <section data-member-section="posture" style={{ ...sectionStyle, backgroundColor: afterReminder.show ? WARN_S : CARD }}>
            <div className="flex items-start gap-3"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg" style={{ backgroundColor: TINT, color: BRAND_D }}><Activity size={16} /></span><span className="min-w-0 flex-1"><span className="flex items-center gap-2">{afterReminder.show && <span className="ml-auto shrink-0 rounded-full px-2 py-1 text-[9px] font-extrabold" style={{ backgroundColor: CARD, color: WARN }}>{afterReminder.label}</span>}</span><span className="mt-1 block text-xs" style={{ color: SUB }}>{lastAssessment ? `마지막 촬영 ${ymd((lastAssessment.completedAt || lastAssessment.at).slice(0, 10))}${afterReminder.days != null ? ` · ${afterReminder.days}일 전` : ""}` : "아직 완료된 분석이 없습니다"}</span>{lastAssessmentMetrics.length > 0 && <span className="mt-1 block line-clamp-2 text-xs" style={{ color: INK2 }}>{lastAssessmentMetrics.map((metric) => `${metric.label} ${metric.value}${metric.unit}`).join(" · ")}</span>}</span></div>
            <div className="mt-2 grid grid-cols-2 gap-2"><button type="button" onClick={() => onAssess?.({ mode: "new" })} className="h-10 text-xs font-bold text-white" style={{ borderRadius: 8, backgroundColor: BRAND }}>새 체형분석</button><button type="button" onClick={() => onAssess?.({ mode: "history" })} className="h-10 text-xs font-bold" style={{ borderRadius: 8, backgroundColor: CARD, border: `1px solid ${LINE}`, color: INK }}>과거 이력</button></div>
          </section>
          <Section title="체형분석 과거 이력">
            {assessmentSets.length ? assessmentSets.slice(0, 3).map((assessment) => { const representative = assessment.photos.front || Object.values(assessment.photos)[0]; const summary = assessment.poses.flatMap((pose) => pose.metrics || []).slice(0, 1)[0]; const resumable = assessment.id === resumableAssessment?.id; return <button type="button" key={assessment.id} onClick={() => onAssess?.(assessment.status === "completed" && assessment.poses[0]?.id ? { mode: "result", poseId: assessment.poses[0].id, assessmentId: assessment.id } : resumable ? { mode: "resume", assessmentId: assessment.id } : { mode: "history" })} className="flex w-full items-center gap-2 text-left" style={{ padding: "8px 0", borderTop: `1px solid ${LINE}` }}>{representative?.src ? <img src={representative.src} alt="체형분석 대표 사진" className="h-11 w-8 shrink-0 object-cover" style={{ borderRadius: 6, backgroundColor: PHOTO }} /> : <span className="flex h-11 w-8 shrink-0 items-center justify-center" style={{ borderRadius: 6, backgroundColor: CANVAS, color: BRAND }}><Activity size={13} /></span>}<span className="min-w-0 flex-1"><span className="block truncate" style={{ fontSize: 12, color: INK2 }}>{ymd((assessment.completedAt || assessment.at).slice(0, 10))} · {assessment.scope === "partial" ? "부위별" : "전신"}</span><span className="mt-0.5 block truncate" style={{ fontSize: 10, color: SUB }}>{summary ? `${summary.label} ${summary.value}${summary.unit}` : assessment.method === "draw" ? "강사 직접 기록" : "저장된 AI 해석 없음"}</span></span><span style={{ padding: "2px 6px", borderRadius: 6, backgroundColor: assessment.status === "completed" ? GOOD_S : WARN_S, color: assessment.status === "completed" ? GOOD : WARN, fontSize: 9, fontWeight: 700 }}>{assessment.status === "completed" ? "완료" : resumable ? "초안" : "이전 초안"}</span><ChevronRight size={13} style={{ color: SUB }} /></button>; }) : <p style={{ fontSize: 12, color: SUB }}>저장된 분석이 없습니다</p>}
            {assessmentSets.length > 3 && <button type="button" onClick={() => onAssess?.({ mode: "history" })} className="mt-2 h-9 w-full text-xs font-bold" style={{ borderRadius: 8, backgroundColor: CANVAS, color: BRAND_D }}>전체 히스토리 보기</button>}
          </Section>
            </div>
          </details>
          <details data-member-management-card="membership" style={{ ...sectionStyle, padding: 0, overflow: "hidden", backgroundColor: TINT, borderColor: "#D5D1EB" }}>
            <summary aria-label="이용권·결제 관리 카드 열기" className="flex min-h-14 cursor-pointer list-none items-center gap-3 px-3.5 py-3"><span className="min-w-0 flex-1"><span className="block truncate text-sm font-extrabold" style={{ color: INK }}>이용권·결제</span><span className="mt-0.5 block truncate text-[10px]" style={{ color: SUB }}>{member.passName || "이용권 없음"} · 잔여 {left(member)}회 (정규 {num(member.regular)} · 서비스 {num(member.service)}) · {member.contractEnd ? ymd(member.contractEnd) : "만료일 미설정"}</span></span><ChevronDown size={16} style={{ color: SUB }} /></summary>
            <div data-member-management-content="membership" style={{ padding: "0 12px 12px" }}>
          <section data-member-section="membership" style={{ ...sectionStyle, backgroundColor: TINT, borderColor: "#D5D1EB" }}>
            <div className="flex items-start gap-3"><div className="min-w-0 flex-1"><p style={{ fontSize: 11, color: SUB }}>현재 이용권</p><p className="mt-0.5 truncate" style={{ fontSize: 14, fontWeight: 700, color: INK }}>{member.passName || "이용권 없음"}</p></div><div className="text-right"><p className="tabular-nums" style={{ fontSize: 27, lineHeight: 1, fontWeight: 750, color: left(member) <= 3 ? BAD : BRAND }}>{left(member)}<span style={{ fontSize: 12 }}>회 남음</span></p><p className="mt-1" style={{ fontSize: 10, color: SUB }}>정규 {num(member.regular)} · 서비스 {num(member.service)}</p></div></div>
            <div className="mt-3 grid grid-cols-2 gap-2">{[["누적 등록 횟수", membership.registeredTotal ? `${membership.registeredTotal}회` : "미등록"], ["이용권 만료일", member.contractEnd ? ymd(member.contractEnd) : "미설정"], ["회원 회당 금액", memberUnit ? `₩${won(memberUnit)}` : "결제 내역 없음"], ["최근 수업일", recentLesson ? `${md(recentLesson.date)} ${recentLesson.start}` : "수업 이력 없음"], ["다음 예약일", next ? `${md(next.date)} ${next.start}` : "예약 없음"]].map(([k,v]) => <div key={k} style={{ padding: "8px 9px", borderRadius: 8, backgroundColor: CARD }}><p style={{ fontSize: 9, color: SUB }}>{k}</p><p className="mt-0.5 truncate tabular-nums" style={{ fontSize: 11, fontWeight: 700, color: INK }}>{v}</p></div>)}</div>
            {membership.needsLegacyReview && <p className="mt-2" style={{ padding: "8px 9px", borderRadius: 8, backgroundColor: WARN_S, color: WARN, fontSize: 10, lineHeight: 1.45 }}>잔여 합계가 누적 등록 횟수보다 큽니다. 기존 데이터 확인이 필요하며 자동으로 수정하지 않았습니다.</p>}
            {canViewSettlement && <div className="mt-2 flex items-center gap-2" style={{ padding: "8px 9px", borderRadius: 8, backgroundColor: CARD }}><span className="min-w-0 flex-1"><span className="block" style={{ fontSize: 9, color: SUB }}>강사 정산 단가</span><span className="block text-xs font-bold tabular-nums" style={{ color: INK }}>₩{won(settlementUnit)}{Number(member.payRate) > 0 ? "" : " · 센터 기본"}</span></span><button type="button" onClick={openRate} style={{ fontSize: 11, fontWeight: 700, color: BRAND }}>단가 수정</button></div>}
            <p className="mt-2" style={{ fontSize: 10, lineHeight: 1.45, color: SUB }}>회원 회당 금액은 총 결제액을 정규 유료 횟수로 나눕니다. 할인은 결제액에 반영하고 서비스 횟수는 제외합니다.</p>
            <button type="button" onClick={openMembership} className="mt-2 h-10 w-full text-xs font-bold" style={{ borderRadius: 8, backgroundColor: BRAND, color: "#fff" }}>이용권 수정</button>
          </section>
          <Section title="이용권 변경 이력 및 상세 설정" action={<button type="button" onClick={openMembership} style={{ fontSize: 12, fontWeight: 700, color: BRAND }}>관리</button>}>
            {(member.payments || []).length ? member.payments.slice(0, 4).map((p) => <div key={p.id || `${p.date}-${p.amount}`} className="flex items-center gap-2" style={{ padding: "7px 0", borderTop: `1px solid ${LINE}` }}><span className="min-w-0 flex-1"><span className="block truncate" style={{ fontSize: 12, color: INK2 }}>{ymd(p.date)} · {p.name || p.passName || "이용권"}</span>{p.kind === "adjustment" && <span className="block truncate" style={{ fontSize: 10, color: SUB }}>잔여 {p.before?.remaining}회 → {p.after?.remaining}회 · 총 {p.before?.total}회 → {p.after?.total}회</span>}</span><span className="tabular-nums" style={{ fontSize: 12, fontWeight: 600, color: INK }}>{p.kind === "adjustment" ? "수정" : `${num(p.count || p.sessions)}회`}</span></div>) : <p style={{ fontSize: 12, color: SUB }}>저장된 변경 이력이 없습니다</p>}
            {holdHistory.slice(0, 4).map((h) => <div key={h.id} className="flex items-center gap-2" style={{ padding: "7px 0", borderTop: `1px solid ${LINE}`, backgroundColor: CANVAS }}><span style={{ padding: "2px 6px", borderRadius: 5, color: INK2, fontSize: 10, fontWeight: 600 }}>홀딩</span><span className="min-w-0 flex-1 truncate" style={{ fontSize: 11, color: INK2 }}>{ymd(h.startDate)} ~ {ymd(h.releasedAt || h.endDate)}{h.extendDays ? ` · 만료 +${h.extendDays}일` : ""}</span></div>)}
            {(member.instructorHistory || []).slice(0, 3).map((entry) => <div key={entry.id || entry.date} className="flex gap-2" style={{ padding: "7px 0", borderTop: `1px solid ${LINE}` }}><span style={{ fontSize: 10, color: SUB }}>담당 변경</span><span className="min-w-0 flex-1 truncate" style={{ fontSize: 11, color: INK2 }}>{ymd(entry.date)} · {entry.before || "미지정"} → {entry.after || "미지정"}</span></div>)}
            {isHold(member) && <div className="mt-2 flex items-start gap-2" style={{ padding: "9px 10px", borderRadius: 8, backgroundColor: CANVAS }}><AlertCircle size={14} className="mt-0.5 shrink-0" style={{ color: SUB }} /><p style={{ fontSize: 11, lineHeight: 1.5, color: INK2 }}>{ymd(member.holdFrom)} ~ {ymd(member.holdUntil)}{member.holdReason ? ` · ${member.holdReason}` : ""}</p></div>}
            <div className="mt-2 flex gap-2"><button type="button" onClick={openEdit} style={{ flex: 1, height: 42, borderRadius: 8, border: `1px solid ${LINE}`, color: INK2, fontSize: 12, fontWeight: 600 }}>정보 수정</button>{isHold(member) ? <button type="button" onClick={() => { if (!releaseArmed) { setReleaseArmed(true); return; } const releasedAt = todayISO(); onPatch({ status: "active", holdFrom: "", holdUntil: "", holdReason: "", holdHistory: [{ id: uid(), startDate: member.holdFrom, endDate: member.holdUntil, releasedAt, reason: member.holdReason, extendDays: num(member.holdExtendDays), createdAt: releasedAt }, ...holdHistory] }); setReleaseArmed(false); }} style={{ flex: 1.35, height: 42, borderRadius: 8, border: `1px solid ${releaseArmed ? BRAND : LINE}`, backgroundColor: releaseArmed ? TINT : CARD, color: BRAND_D, fontSize: 12, fontWeight: 600 }}>{releaseArmed ? "한 번 더 눌러 홀딩 해제" : "홀딩 해제"}</button> : <button type="button" onClick={() => { setHold({ start: todayISO(), end: shift(todayISO(), 14), reason: "", extend: true }); setSheet("hold"); }} style={{ flex: 1, height: 42, borderRadius: 8, border: `1px solid ${LINE}`, color: BRAND_D, fontSize: 12, fontWeight: 600 }}>홀딩 설정</button>}</div>
          </Section>
            </div>
          </details>
          <details data-member-management-card="basic-and-memos" style={{ ...sectionStyle, padding: 0, overflow: "hidden" }}>
            <summary aria-label="기본정보·상담메모 관리 카드 열기" className="flex min-h-14 cursor-pointer list-none items-center gap-3 px-3.5 py-3"><span className="min-w-0 flex-1"><span className="block truncate text-sm font-extrabold" style={{ color: INK }}>기본정보·상담메모</span><span className="mt-0.5 block truncate text-[10px]" style={{ color: SUB }}>{maskedPhone(member.phone)} · {consultationNotes.length ? `상담메모 ${consultationNotes.length}건` : "상담메모 없음"}</span></span><ChevronDown size={16} style={{ color: SUB }} /></summary>
            <div data-member-management-content="basic-and-memos" className="space-y-2" style={{ padding: "0 12px 12px" }}>
          <Section title="목표·주의사항" action={<button type="button" onClick={openPreparation} style={{ fontSize: 12, fontWeight: 700, color: BRAND }}>수정</button>}>
            <div className="space-y-2"><div><p style={{ fontSize: 10, color: SUB }}>운동 목표</p><p className="mt-0.5" style={{ fontSize: 12, lineHeight: 1.45, color: member.goal ? INK2 : SUB }}>{member.goal || "등록된 운동 목표가 없습니다"}</p></div><div style={{ padding: "9px 10px", borderRadius: 8, backgroundColor: WARN_S }}><p style={{ fontSize: 10, fontWeight: 700, color: WARN }}>통증 및 주의사항</p><p className="mt-1" style={{ fontSize: 12, lineHeight: 1.45, color: INK2 }}>{(member.focus || []).length ? member.focus.join(" · ") : "등록된 주의사항이 없습니다"}</p></div></div>
          </Section>
          <Section title="회원 기본정보" action={<button type="button" onClick={openEdit} style={{ fontSize: 12, fontWeight: 700, color: BRAND }}><Pencil size={12} className="inline" /> 정보 수정</button>}>
            <div className="grid grid-cols-2 gap-x-3 gap-y-2">{[["이름", member.name || "-"], ["회원 상태", isHold(member) ? "홀딩" : isEnded(member) ? "종료" : "활성"], ...(!singleInstructorMode ? [["담당 강사", member.instructor || "미지정"]] : []), ["연락처", maskedPhone(member.phone)], ["수업 유형", member.lessonType === "duet" ? "듀엣" : member.lessonType === "group" ? "그룹" : "개인"], ["기본 수업시간", `${lessonDurationOf(member)}분`], ["생년월일 · 나이", maskedBirth(member.birth, ageOf(member))]].map(([k,v]) => <div key={k} className={k === "생년월일 · 나이" ? "col-span-2" : ""}><p style={{ fontSize: 10, color: SUB }}>{k}</p><p className="mt-0.5 truncate" style={{ fontSize: 12, fontWeight: 600, color: INK }}>{v}</p></div>)}</div>
          </Section>
          <Section title="상담 및 중요 메모" action={<div className="flex gap-3"><button type="button" onClick={() => setSheet("memos-all")} style={{ fontSize: 12, fontWeight: 600, color: SUB }}>전체 보기</button><button type="button" onClick={openMemo} style={{ fontSize: 12, fontWeight: 700, color: BRAND }}>메모 추가</button></div>}>
            {consultationNotes.length ? consultationNotes.slice(0, 3).map((note) => <div key={note.id} className="flex items-start gap-2" style={{ padding: "7px 0", borderTop: `1px solid ${LINE}` }}><button type="button" aria-label={note.important ? "중요 메모 고정 해제" : "중요 메모로 고정"} onClick={() => commitPatch("pin", { notes: (member.notes || []).map((item) => item.id === note.id ? { ...item, important: !item.important } : item) }, false)} className="mt-0.5 shrink-0" style={{ color: note.important ? WARN : FAINT }}><Star size={14} fill={note.important ? "currentColor" : "none"} /></button><span className="min-w-0 flex-1"><span className="block" style={{ fontSize: 10, color: SUB }}>{ymd(note.date)}{note.important ? " · 중요" : ""}</span><span className="mt-0.5 block line-clamp-2" style={{ fontSize: 12, lineHeight: 1.45, color: INK2 }}>{note.body}</span></span></div>) : <button type="button" onClick={openMemo} className="flex h-9 w-full items-center justify-between px-2 text-left" style={{ borderRadius: 8, backgroundColor: CANVAS, color: SUB, fontSize: 11 }}>등록된 상담 메모가 없습니다<span style={{ color: BRAND }}>추가하기</span></button>}
          </Section>
            </div>
          </details>
          <section className="mt-3 rounded-xl p-3" style={{ backgroundColor: CARD, border: `1px solid ${LINE}` }}>
            <p className="text-xs font-extrabold" style={{ color: INK }}>회원 관리</p>
            <p className="mt-1 text-[11px] leading-relaxed" style={{ color: SUB }}>삭제 전에 기록을 보존하는 비활성 처리를 선택할 수 있습니다.</p>
            <button type="button" onClick={() => { setDeleteName(""); setSaveError(""); setSheet("delete-member"); }} className="mt-2 h-11 w-full rounded-lg text-xs font-extrabold" style={{ backgroundColor: BAD_S, color: BAD }}>회원 삭제</button>
          </section>
        </div>
      </main>
      {sheet === "delete-member" && <Sheet title="회원 삭제" sub="삭제하거나 기록을 보존한 채 목록에서 숨길 수 있습니다" onClose={() => !deleteBusy && setSheet(null)}><div className="space-y-3">
        <div className="rounded-xl p-3" style={{ backgroundColor: BAD_S, border: `1px solid ${BAD}` }}><p className="text-sm font-extrabold leading-relaxed" style={{ color: BAD }}>{member.name}님과 수업기록·체형분석·사진이 모두 삭제됩니다. 되돌릴 수 없어요.</p><p className="mt-2 text-[11px] leading-relaxed" style={{ color: INK2 }}>이미 지난 일정은 삭제하지 않고 ‘삭제된 회원’으로 표시하며, 예정 일정에서는 회원 연결을 해제합니다.</p></div>
        <Field label={`확인을 위해 “${member.name}” 입력`}><input autoComplete="off" value={deleteName} onChange={(event) => setDeleteName(event.target.value)} className={inputCls} /></Field>
        {saveError && <p role="alert" className="text-xs font-bold" style={{ color: BAD }}>{saveError}</p>}
        <button type="button" disabled={deleteBusy} onClick={async () => { setDeleteBusy(true); setSaveError(""); try { const saved = await onDeactivate?.(member.id); if (saved !== false) { setSheet(null); onBack?.(); } } catch (error) { setSaveError("회원을 비활성으로 전환하지 못했습니다."); } finally { setDeleteBusy(false); } }} className="h-12 w-full rounded-lg text-sm font-extrabold disabled:opacity-40" style={{ backgroundColor: CANVAS, color: BRAND_D }}>비활성으로 두기</button>
        <button type="button" disabled={deleteBusy || deleteName !== member.name} onClick={async () => { setDeleteBusy(true); setSaveError(""); try { const saved = await onDelete?.(member.id); if (saved !== false) { setSheet(null); onBack?.(); } else setSaveError("삭제를 완료하지 못했습니다."); } catch (error) { setSaveError("삭제를 완료하지 못했습니다. 연결 상태를 확인해 주세요."); } finally { setDeleteBusy(false); } }} className="h-12 w-full rounded-lg text-sm font-extrabold text-white disabled:opacity-35" style={{ backgroundColor: BAD }}>{deleteBusy ? "삭제 중…" : "회원과 관련 데이터 영구 삭제"}</button>
      </div></Sheet>}
      {sheet === "basic" && <Sheet title="기본정보 수정" onClose={() => setSheet(null)} wide><div className="space-y-3">
        <Field label="이름"><input value={edit.name || ""} onChange={(e) => setEdit({ ...edit, name: e.target.value })} className={inputCls} /></Field><div className="grid grid-cols-2 gap-2"><Field label="담당 강사"><input value={edit.instructor || ""} onChange={(e) => setEdit({ ...edit, instructor: e.target.value })} className={inputCls} /></Field><Field label="연락처"><input value={edit.phone || ""} onChange={(e) => setEdit({ ...edit, phone: e.target.value })} className={inputCls} /></Field></div><Field label="생년월일"><input type="date" value={edit.birth || ""} onChange={(e) => setEdit({ ...edit, birth: e.target.value })} className={inputCls} /></Field><div className="grid grid-cols-2 gap-2"><Field label="수업 유형"><select value={edit.lessonType || "private"} onChange={(e) => setEdit({ ...edit, lessonType: e.target.value })} className={inputCls}><option value="private">개인</option><option value="duet">듀엣</option><option value="group">그룹</option></select></Field><Field label="기본 수업시간"><select value={edit.defaultLessonDuration || DEFAULT_CLASS_DURATION} onChange={(e) => setEdit({ ...edit, defaultLessonDuration: Number(e.target.value) })} className={inputCls}>{[30, 50, 60, 80].map((value) => <option key={value} value={value}>{value}분</option>)}</select></Field></div>
        {saveError && <p role="alert" style={{ fontSize: 11, color: BAD }}>{saveError}</p>}<button type="button" aria-busy={saving === "basic"} disabled={!String(edit.name || "").trim() || saving === "basic"} onClick={() => commitPatch("basic", { ...edit, name: edit.name.trim(), defaultLessonDuration: lessonDurationOf(edit), ...(String(edit.instructor || "") !== String(member.instructor || "") ? { instructorHistory: [{ id: uid(), date: todayISO(), before: member.instructor || "", after: edit.instructor || "" }, ...(member.instructorHistory || [])] } : {}) })} className="w-full text-sm font-semibold text-white disabled:opacity-40" style={{ height: 48, borderRadius: 8, backgroundColor: BRAND }}>{saving === "basic" ? "저장 중…" : "기본정보 저장"}</button>
      </div></Sheet>}
      {sheet === "preparation" && <Sheet title="목표·주의사항 수정" onClose={() => setSheet(null)}><div className="space-y-3"><Field label="운동 목표"><textarea rows={3} value={edit.goal || ""} onChange={(e) => setEdit({ ...edit, goal: e.target.value })} className={`${inputCls} h-auto py-3`} /></Field><Field label="통증 및 주의사항" hint="쉼표로 구분"><textarea rows={3} value={edit.focus || ""} onChange={(e) => setEdit({ ...edit, focus: e.target.value })} className={`${inputCls} h-auto py-3`} /></Field>{saveError && <p role="alert" style={{ fontSize: 11, color: BAD }}>{saveError}</p>}<button type="button" disabled={saving === "preparation"} onClick={() => commitPatch("preparation", { goal: String(edit.goal || "").trim(), focus: String(edit.focus || "").split(",").map((x) => x.trim()).filter(Boolean) })} className="h-12 w-full text-sm font-bold text-white disabled:opacity-40" style={{ borderRadius: 8, backgroundColor: BRAND }}>{saving === "preparation" ? "저장 중…" : "목표·주의사항 저장"}</button></div></Sheet>}
      {sheet === "hold" && <Sheet title="홀딩 설정" sub={`${member.name} · 수업 기록과 분석 이력은 유지됩니다`} onClose={() => setSheet(null)}><div className="space-y-3">
        <div className="grid grid-cols-2 gap-2"><Field label="홀딩 시작일"><input type="date" value={hold.start} onChange={(e) => setHold({ ...hold, start: e.target.value })} className={inputCls} /></Field><Field label="종료 예정일"><input type="date" value={hold.end} onChange={(e) => setHold({ ...hold, end: e.target.value })} className={inputCls} /></Field></div>
        <Field label="홀딩 사유"><input value={hold.reason} onChange={(e) => setHold({ ...hold, reason: e.target.value })} placeholder="예: 개인 사정 · 부상 · 여행" className={inputCls} /></Field>
        <button type="button" onClick={() => setHold({ ...hold, extend: !hold.extend })} className="flex w-full items-center justify-between" style={{ height: 42, padding: "0 12px", borderRadius: 8, border: `1px solid ${hold.extend ? BRAND : LINE}`, backgroundColor: hold.extend ? TINT : CARD, color: hold.extend ? BRAND_D : INK2, fontSize: 12, fontWeight: 600 }}><span>이용권 만료일 연장</span><span>{hold.extend ? "연장" : "연장 안 함"}</span></button>
        <p style={{ fontSize: 11, lineHeight: 1.5, color: SUB }}>홀딩은 예정된 수업을 자동 취소하지 않습니다. 일정 탭에서 직접 확인해 주세요.</p>
        <button type="button" disabled={!hold.start || !hold.end || hold.end < hold.start} onClick={() => { const days = Math.max(0, Math.round((new Date(`${hold.end}T00:00:00`).getTime() - new Date(`${hold.start}T00:00:00`).getTime()) / 86400000)); onPatch({ status: "hold", holdFrom: hold.start, holdUntil: hold.end, holdReason: hold.reason.trim(), holdExtendDays: hold.extend ? days : 0, contractEnd: hold.extend && member.contractEnd ? shift(member.contractEnd, days) : member.contractEnd }); setSheet(null); }} className="w-full text-sm font-semibold text-white disabled:opacity-40" style={{ height: 48, borderRadius: 8, backgroundColor: BRAND }}>홀딩 시작</button>
      </div></Sheet>}
      {(sheet === "memo" || sheet === "record") && <Sheet title={sheet === "memo" ? "상담 메모 추가" : "수업 기록"} onClose={() => setSheet(null)}><div className="space-y-2">{sheet === "record" && <VoiceNote key={lessonRecordSessionKey(member.id, null)} memberId={member.id} memberName={member.name || "회원"} onClose={() => setSheet(null)} onDeferred={() => setSheet(null)} onDraftChange={(text, meta, options) => onSaveNote("개인레슨", text, meta, options)} onApply={(text, meta) => onSaveNote("개인레슨", text, meta, { confirmed: true, upsert: true })} />}{sheet === "memo" && <><button type="button" aria-pressed={memoImportant} onClick={() => setMemoImportant((value) => !value)} className="flex h-10 w-full items-center gap-2 px-3" style={{ borderRadius: 8, backgroundColor: memoImportant ? WARN_S : CANVAS, color: memoImportant ? WARN : SUB, fontSize: 12, fontWeight: 700 }}><Star size={14} fill={memoImportant ? "currentColor" : "none"} />중요 메모로 상단 고정</button><textarea autoFocus rows={5} value={memo} onChange={(e) => setMemo(e.target.value)} placeholder="내용을 입력하세요" className={`${inputCls} h-auto resize-none py-3`} />{saveError && <p role="alert" style={{ fontSize: 11, color: BAD }}>{saveError}</p>}<button type="button" aria-busy={saving === sheet} disabled={!memo.trim() || saving === sheet} onClick={commitNote} className="w-full text-sm font-semibold text-white disabled:opacity-40" style={{ height: 48, borderRadius: 8, backgroundColor: BRAND }}>{saving === sheet ? "저장 중…" : "저장"}</button></>}</div></Sheet>}
      {sheet === "record-review" && reviewDraft && <Sheet title="AI 수업기록 확인" sub="확인은 선택입니다. 정리된 기록은 이미 저장되어 있어요." onClose={() => setSheet(null)}><div className="space-y-3"><div className="grid grid-cols-2 gap-2">{[{ k: "didToday", l: "오늘 수업" }, { k: "observations", l: "변화" }, { k: "responses", l: "회원 반응" }, { k: "nextFocus", l: "다음 확인" }].map((field) => <div key={field.k} className="rounded-xl p-3" style={{ backgroundColor: CANVAS }}><p className="text-[10px] font-extrabold" style={{ color: SUB }}>{field.l}</p>{reviewEditing ? <textarea rows={2} aria-label={`${field.l} 수정`} value={structuredFieldText(reviewDraft, field.k)} onChange={(event) => setReviewDraft((current) => editStructuredField(current, field.k, event.target.value))} className={`${inputCls} mt-1 h-auto resize-none py-2 text-xs`} /> : <p className="mt-1 text-xs font-bold leading-relaxed" style={{ color: INK2 }}>{prepText(reviewDraft[field.k], "기록 없음")}</p>}</div>)}</div><div className="grid grid-cols-2 gap-2"><button type="button" onClick={() => setReviewEditing((value) => !value)} className="h-12 rounded-xl text-sm font-extrabold" style={{ backgroundColor: CANVAS, color: BRAND_D }}>{reviewEditing ? "수정 닫기" : "수정"}</button><button type="button" onClick={confirmRecordReview} className="h-12 rounded-xl text-sm font-extrabold text-white" style={{ backgroundColor: BRAND }}>확인</button></div></div></Sheet>}
      {sheet === "memos-all" && <Sheet title="상담 메모 전체 보기" onClose={() => setSheet(null)}><div className="space-y-2">{consultationNotes.length ? consultationNotes.map((note) => <div key={note.id} style={{ padding: 10, borderRadius: 8, backgroundColor: note.important ? WARN_S : CANVAS }}><p style={{ fontSize: 10, color: SUB }}>{ymd(note.date)}{note.important ? " · 중요 메모" : ""}</p><p className="mt-1" style={{ fontSize: 12, lineHeight: 1.5, color: INK2 }}>{note.body}</p></div>) : <p style={{ fontSize: 12, color: SUB }}>등록된 상담 메모가 없습니다</p>}<button type="button" onClick={openMemo} className="h-11 w-full text-xs font-bold" style={{ borderRadius: 8, backgroundColor: TINT, color: BRAND_D }}>메모 추가</button></div></Sheet>}
      {sheet === "records-all" && <Sheet title="수업 기록 전체 보기" onClose={() => setSheet(null)}><div className="space-y-2">{lessonNotes.length ? lessonNotes.map((note) => <div key={note.id} style={{ padding: 10, borderRadius: 8, backgroundColor: CANVAS }}><p style={{ fontSize: 10, color: SUB }}>{ymd(note.date)} · {note.type || "수업"}{noteEquipText(note) ? ` · ${noteEquipText(note)}` : ""}</p><p className="mt-1" style={{ fontSize: 12, lineHeight: 1.5, color: INK2 }}>{note.body}</p></div>) : <p style={{ fontSize: 12, color: SUB }}>아직 작성된 수업 기록이 없습니다</p>}</div></Sheet>}
      {sheet === "membership" && <Sheet title="현재 이용권 수정" onClose={() => setSheet(null)}><div className="space-y-3">{!passConfirm ? <><Field label="이용권 이름"><input value={pass.name} onChange={(e) => setPass({ ...pass, name: e.target.value })} className={inputCls} /></Field><div className="grid grid-cols-3 gap-2"><Field label="정규 잔여"><input inputMode="numeric" value={pass.regular} onChange={(e) => setPass({ ...pass, regular: e.target.value.replace(/\D/g, "") })} className={inputCls} /></Field><Field label="서비스 잔여"><input inputMode="numeric" value={pass.service} onChange={(e) => setPass({ ...pass, service: e.target.value.replace(/\D/g, "") })} className={inputCls} /></Field><Field label="누적 등록"><input inputMode="numeric" value={pass.total} onChange={(e) => setPass({ ...pass, total: e.target.value.replace(/\D/g, "") })} className={inputCls} /></Field></div><Field label="만료일"><input type="date" value={pass.end} onChange={(e) => setPass({ ...pass, end: e.target.value })} className={inputCls} /></Field><button type="button" onClick={() => setPassConfirm(true)} className="h-12 w-full text-sm font-bold text-white" style={{ borderRadius: 8, backgroundColor: BRAND }}>변경 내용 확인</button></> : <><div style={{ padding: 12, borderRadius: 10, backgroundColor: CANVAS }}><p className="mb-2 text-xs font-bold" style={{ color: INK }}>변경 전후를 확인해 주세요</p>{[["총 잔여", `${left(member)}회`, `${num(pass.regular) + num(pass.service)}회`], ["누적 등록", `${num(member.total)}회`, `${num(pass.total)}회`], ["만료일", member.contractEnd ? ymd(member.contractEnd) : "미설정", pass.end ? ymd(pass.end) : "미설정"]].map(([label,before,after]) => <div key={label} className="flex items-center gap-2 py-1"><span className="w-16 text-[10px]" style={{ color: SUB }}>{label}</span><span className="min-w-0 flex-1 text-right text-xs line-through" style={{ color: SUB }}>{before}</span><ChevronRight size={12} style={{ color: FAINT }} /><span className="min-w-0 flex-1 text-xs font-bold" style={{ color: BRAND_D }}>{after}</span></div>)}</div>{saveError && <p role="alert" style={{ fontSize: 11, color: BAD }}>{saveError}</p>}<div className="grid grid-cols-2 gap-2"><button type="button" onClick={() => setPassConfirm(false)} className="h-12 text-sm font-bold" style={{ borderRadius: 8, backgroundColor: CANVAS, color: INK2 }}>다시 수정</button><button type="button" disabled={saving === "membership"} onClick={() => { const regular = num(pass.regular), service = num(pass.service), total = num(pass.total); commitPatch("membership", { passName: pass.name.trim(), regular, service, total, contractEnd: pass.end, payments: [{ id: uid(), date: todayISO(), kind: "adjustment", name: "이용권 수정", before: { remaining: left(member), total: num(member.total), end: member.contractEnd || "" }, after: { remaining: regular + service, total, end: pass.end } }, ...(member.payments || [])] }); }} className="h-12 text-sm font-bold text-white disabled:opacity-40" style={{ borderRadius: 8, backgroundColor: BRAND }}>{saving === "membership" ? "저장 중…" : "확인 후 저장"}</button></div></>}</div></Sheet>}
      {sheet === "rate" && canViewSettlement && <Sheet title="강사 정산 단가 수정" onClose={() => setSheet(null)}><div className="space-y-3">{!rateConfirm ? <><Field label="강사 정산 단가"><input inputMode="numeric" value={rateEdit} onChange={(e) => setRateEdit(e.target.value.replace(/\D/g, ""))} className={inputCls} /></Field><p style={{ fontSize: 11, lineHeight: 1.5, color: SUB }}>회원 회당 결제금액과 별도이며 급여 예상 계산에 사용됩니다.</p><button type="button" disabled={!num(rateEdit)} onClick={() => setRateConfirm(true)} className="h-12 w-full text-sm font-bold text-white disabled:opacity-40" style={{ borderRadius: 8, backgroundColor: BRAND }}>변경 내용 확인</button></> : <><div className="flex items-center gap-3" style={{ padding: 12, borderRadius: 10, backgroundColor: CANVAS }}><span className="min-w-0 flex-1 text-right text-sm line-through" style={{ color: SUB }}>₩{won(settlementUnit)}</span><ChevronRight size={14} style={{ color: FAINT }} /><span className="min-w-0 flex-1 text-sm font-bold" style={{ color: BRAND_D }}>₩{won(rateEdit)}</span></div>{saveError && <p role="alert" style={{ fontSize: 11, color: BAD }}>{saveError}</p>}<div className="grid grid-cols-2 gap-2"><button type="button" onClick={() => setRateConfirm(false)} className="h-12 text-sm font-bold" style={{ borderRadius: 8, backgroundColor: CANVAS, color: INK2 }}>다시 수정</button><button type="button" disabled={saving === "rate"} onClick={() => commitPatch("rate", { payRate: num(rateEdit) })} className="h-12 text-sm font-bold text-white disabled:opacity-40" style={{ borderRadius: 8, backgroundColor: BRAND }}>{saving === "rate" ? "저장 중…" : "확인 후 저장"}</button></div></>}</div></Sheet>}
    </div>
  );
}

function ChangeSummary({ member, onGo }) {
  const rec = inbodyOf(member);
  const n = rec.length;
  if (n === 0)
    return (
      <button onClick={onGo} className="w-full rounded-2xl p-4 text-left" style={{ background: GRAD }}>
        <p className="text-sm font-extrabold text-white">첫 인바디 측정값을 입력해 주세요</p>
        <p className="mt-1 text-xs text-white opacity-70">기록 탭 → 인바디에서 등록하면 여기에 변화가 표시됩니다</p>
      </button>
    );
  const first = rec[0], last = rec[n - 1];
  return (
    <div className="rounded-2xl p-4" style={{ backgroundColor: BRAND }}>
      <div className="flex items-center justify-between">
        <p className="text-xs font-bold text-white opacity-70">{ymd(first.date)} → {ymd(last.date)}</p>
        <span className="rounded-full bg-white px-2.5 py-1 text-xs font-extrabold" style={{ color: PRIMARY }}>{n === 1 ? "첫 측정" : `${weeksBetween(first.date, last.date)}주 변화`}</span>
      </div>
      <div className="mt-4 grid grid-cols-3 gap-2">
        {Object.values(METRICS).map((m) => {
          const diff = +(last[m.key] - first[m.key]).toFixed(1);
          const t = toneOf(m.key, diff);
          const c = t === "good" ? GOOD : t === "bad" ? BAD : LINE;
          return (
            <div key={m.key} className="rounded-xl p-3" style={{ backgroundColor: "rgba(255,255,255,0.12)" }}>
              <p className="text-xs font-bold text-white opacity-80">{m.label}</p>
              <p className="mt-1 text-2xl font-extrabold tabular-nums text-white">{last[m.key]}<span className="ml-0.5 text-xs opacity-70">{m.unit}</span></p>
              {n > 1 && (
                <>
                  <p className="mt-1 text-xs font-extrabold tabular-nums" style={{ color: c }}>{diff > 0 ? "▲" : diff < 0 ? "▼" : "－"} {Math.abs(diff).toFixed(1)}{uLabel(m.key)}</p>
                  <p className="text-xs text-white opacity-50">시작 {first[m.key]}</p>
                </>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
function ChartTooltip({ active, payload, label }) {
  if (!active || !payload?.length) return null;
  return (
    <div className="rounded-2xl bg-white px-3 py-2" style={{ boxShadow: SHADOW }}>
      <p className="mb-1 text-xs" style={{ color: SUB }}>{label}</p>
      {payload.map((p) => <p key={p.dataKey} className="text-xs font-bold tabular-nums" style={{ color: p.color }}>{METRICS[p.dataKey]?.label} {p.value}{METRICS[p.dataKey]?.unit}</p>)}
    </div>
  );
}
function InbodyChart({ member }) {
  const [on, setOn] = useState({ weight: true, smm: true, fat: true });
  const data = useMemo(() => inbodyOf(member).map((r) => ({ ...r, label: md(r.date) })), [member.inbody]);
  if (data.length < 2) return <Card className="p-5"><h3 className="font-extrabold" style={{ color: INK }}>인바디 변화 추이</h3><Sub className="mt-1">측정값이 2회 이상 쌓이면 그래프가 그려집니다. (현재 {data.length}회)</Sub></Card>;
  return (
    <Card className="p-5">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div><h3 className="font-extrabold" style={{ color: INK }}>인바디 변화 추이</h3><Sub>{data.length}회 측정</Sub></div>
        <div className="flex gap-1.5">
          {Object.values(METRICS).map((m) => (
            <button key={m.key} onClick={() => setOn((s) => ({ ...s, [m.key]: !s[m.key] }))} className="rounded-full px-3 py-1.5 text-xs font-bold"
              style={on[m.key] ? { backgroundColor: m.color, color: "#fff" } : { backgroundColor: CANVAS, color: SUB }}>{m.label}</button>
          ))}
        </div>
      </div>
      <div className="mt-4 h-64 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={data} margin={{ top: 8, right: 4, left: -18, bottom: 0 }}>
            <CartesianGrid stroke={LINE} vertical={false} />
            <XAxis dataKey="label" tick={{ fontSize: 11, fill: SUB }} axisLine={false} tickLine={false} />
            <YAxis yAxisId="kg" domain={["auto", "auto"]} tick={{ fontSize: 11, fill: SUB }} axisLine={false} tickLine={false} width={44} />
            <YAxis yAxisId="pct" orientation="right" domain={["auto", "auto"]} tick={{ fontSize: 11, fill: SUB }} axisLine={false} tickLine={false} width={36} />
            <Tooltip content={<ChartTooltip />} />
            {!!member.goalWeight && on.weight && (
              <ReferenceLine yAxisId="kg" y={num(member.goalWeight)} stroke={PRIMARY} strokeDasharray="4 4" strokeOpacity={0.45}
                label={{ value: `목표 ${num(member.goalWeight)}kg`, position: "insideTopLeft", fontSize: 10, fill: PRIMARY }} />
            )}
            {on.weight && <Line yAxisId="kg" type="monotone" dataKey="weight" stroke={PRIMARY} strokeWidth={2.5} dot={{ r: 3, fill: CARD, strokeWidth: 2 }} />}
            {on.smm && <Line yAxisId="kg" type="monotone" dataKey="smm" stroke={GOOD} strokeWidth={2.5} dot={{ r: 3, fill: CARD, strokeWidth: 2 }} />}
            {on.fat && <Line yAxisId="pct" type="monotone" dataKey="fat" stroke={BAD} strokeWidth={2.5} dot={{ r: 3, fill: CARD, strokeWidth: 2 }} />}
          </LineChart>
        </ResponsiveContainer>
      </div>
      <div className="mt-2 flex flex-wrap items-center justify-center gap-x-4">
        <Sub>왼쪽 축 kg · 오른쪽 축 %</Sub>
        <span className="text-xs font-bold" style={{ color: GOOD }}>● 근육 ↑ 좋음</span>
        <span className="text-xs font-bold" style={{ color: BAD }}>● 체중 · 지방 ↑ 주의</span>
      </div>
    </Card>
  );
}
function AlignSheet({ src, ghost, init, title, onSave, onCancel, ghostEditable, mainName, ghostName }) {
  const [which, setWhich] = useState("main");
  const [m, setM] = useState({ x: num(init?.x) || 0, y: num(init?.y) || 0, scale: num(init?.scale) || 1, rot: num(init?.rot) || 0 });
  const [g, setG] = useState({ x: num(ghost?.x) || 0, y: num(ghost?.y) || 0, scale: num(ghost?.scale) || 1, rot: num(ghost?.rot) || 0 });
  const [op, setOp] = useState(0);
  useBackClose(true, onCancel);
  useScrollLock();
  const twoWay = !!(ghost && ghostEditable);
  const onGhost = twoWay && which === "ghost";
  /* 상대 사진을 실제로 건드렸을 때만 같이 저장한다 */
  const gDirty = twoWay && (g.x !== (num(ghost?.x) || 0) || g.y !== (num(ghost?.y) || 0)
    || g.scale !== (num(ghost?.scale) || 1) || g.rot !== (num(ghost?.rot) || 0));
  /* 사진 원본 비율이 3:4 가 아니면 저장 프레임에서 잘린다 — 얼마나 줄여야 다 들어오는지 계산 */
  const [nat, setNat] = useState(null);
  const FR = 3 / 4;
  const fitScale = nat && nat.w && nat.h
    ? Math.min(FR / nat.w, 1 / nat.h) / Math.max(FR / nat.w, 1 / nat.h)
    : 1;
  const offRatio = nat && nat.w && nat.h ? Math.abs(nat.w / nat.h - FR) > 0.02 : false;
  const marked = (init?.marks?.length || 0) + (onGhost ? (ghost?.marks?.length || 0) : 0);
  const cur = onGhost ? g : m;
  const setCur = (p) => (onGhost ? setG((v) => ({ ...v, ...p })) : setM((v) => ({ ...v, ...p })));
  const rows = [
    { k: "x", l: "좌 · 우", min: -40, max: 40, step: 1 },
    { k: "y", l: "위 · 아래", min: -40, max: 40, step: 1 },
    { k: "scale", l: "확대", min: 0.35, max: 2, step: 0.02 },
    { k: "rot", l: "기울기", min: -20, max: 20, step: 0.5 },
  ];
  return (
    <div className="safe-all fixed inset-0 z-50 flex flex-col bg-photo" style={{ overscrollBehavior: "contain", touchAction: "none" }}>
      <div className="flex items-center justify-between px-4 py-3">
        <button onClick={onCancel} className="rounded-full p-2" style={{ backgroundColor: "rgba(255,255,255,0.15)" }}><X size={18} color="#fff" /></button>
        <p className="text-sm font-bold text-white">{title || "중심선 맞추기"}</p>
        <button onClick={() => onSave(m, gDirty ? g : null)} className="rounded-full px-4 py-2 text-sm font-extrabold text-white" style={{ backgroundColor: BRAND }}>저장</button>
      </div>
      {twoWay && (
        <div className="mx-4 mb-1 flex gap-1 rounded-2xl p-1" style={{ backgroundColor: "rgba(255,255,255,0.12)" }}>
          {[{ k: "ghost", l: ghostName || "비포" }, { k: "main", l: mainName || "애프터" }].map((o) => (
            <button key={o.k} onClick={() => setWhich(o.k)} className="flex-1 rounded-xl py-2 text-xs font-extrabold"
              style={which === o.k ? { backgroundColor: BRAND, color: "#fff" } : { color: "rgba(255,255,255,0.7)" }}>{o.l} 맞추기</button>
          ))}
        </div>
      )}
      <div className="flex min-h-0 flex-1 items-center justify-center px-4">
        <div className="relative overflow-hidden rounded-2xl bg-photo" style={{ aspectRatio: "3 / 4", maxHeight: "100%", maxWidth: "min(100%, 540px)", width: "100%" }}>
          <img src={src} alt="촬영본" onLoad={(e) => setNat({ w: e.currentTarget.naturalWidth, h: e.currentTarget.naturalHeight })}
            className="absolute inset-0 h-full w-full object-cover"
            style={{ transform: ptf(m), opacity: onGhost ? 0.45 : 1 }} />
          {ghost && <img src={ghost.src} alt="이전" className="absolute inset-0 h-full w-full object-cover"
            style={{ opacity: onGhost ? 1 : op / 100, transform: ptf(twoWay ? g : ghost) }} />}
          <GuideOverlay strong />
        </div>
      </div>
      <div className="space-y-2 px-4 pb-6 pt-3">
        {twoWay && <p className="text-center text-xs font-bold text-white opacity-60">지금 {onGhost ? (ghostName || "비포") : (mainName || "애프터")} 사진을 맞추는 중입니다</p>}
        {marked > 0 && <p className="text-center text-xs font-bold" style={{ color: WARN }}>이 사진에 분석선 {marked}개가 있습니다. 위치를 바꾸면 선이 몸에서 어긋납니다.</p>}
        {!onGhost && offRatio && (
          <div className="flex flex-wrap items-center gap-2 rounded-2xl px-3 py-2.5" style={{ backgroundColor: "rgba(247,144,9,.22)" }}>
            <AlertTriangle size={14} style={{ color: WARN }} />
            <span className="min-w-0 flex-1 text-xs font-bold text-white">이 사진은 3:4 가 아니라 {nat.w > nat.h * FR ? "좌우가" : "위아래가"} 잘립니다</span>
            <button onClick={() => setCur({ x: 0, y: 0, scale: Math.max(0.35, Math.round(fitScale * 100) / 100) })}
              className="shrink-0 rounded-full px-3 py-1.5 text-xs font-extrabold" style={{ backgroundColor: "#fff", color: "#17171F" }}>전체 담기</button>
          </div>
        )}
        {rows.map((r) => {
          const n100 = Math.round(((cur[r.k] - r.min) / (r.max - r.min)) * 100);
          return (
            <div key={r.k} className="flex items-center gap-2">
              <span className="w-14 shrink-0 text-xs font-bold text-white opacity-70">{r.l}</span>
              <input type="range" min={r.min} max={r.max} step={r.step} value={cur[r.k]}
                onChange={(e) => setCur({ [r.k]: Number(e.target.value) })} className="min-w-0 flex-1" style={{ accentColor: PRIMARY, touchAction: "none" }} />
              <span className="w-9 shrink-0 rounded-lg py-1 text-center text-xs font-extrabold tabular-nums text-white" style={{ backgroundColor: "rgba(255,255,255,0.16)" }}>{n100}</span>
              <button onClick={() => setCur({ [r.k]: r.k === "scale" ? 1 : 0 })} className="w-8 shrink-0 rounded-lg py-1 text-center text-xs font-bold text-white" style={{ backgroundColor: "rgba(255,255,255,0.1)" }}>↺</button>
            </div>
          );
        })}
        <p className="text-center text-xs text-white opacity-50">숫자는 0~100 · 좌우·위아래·기울기는 50이 가운데입니다</p>
        {ghost && !onGhost && (
          <div className="flex items-center gap-3">
            <span className="w-14 shrink-0 text-xs font-bold text-white opacity-70">이전 사진</span>
            <input type="range" min="0" max="80" value={op} onChange={(e) => setOp(Number(e.target.value))} className="w-full" style={{ accentColor: PRIMARY, touchAction: "none" }} />
          </div>
        )}
      </div>
    </div>
  );
}
/* 사진 위에 저장된 분석선을 그대로 얹는다 (캔버스와 같은 3:4 기준) */
