  const speechSessionRef = useRef(0);
  const stoppingRef = useRef(false);
  const startRequestRef = useRef(false);
  const nativeListeningStartedRef = useRef(false);
  const heardRef = useRef(false);
  const textRef = useRef("");
  const textAtStartRef = useRef("");
  const audioBlobRef = useRef(null);
  const audioTransferredRef = useRef(false);
  const discardRecordingRef = useRef(false);
  const recordingStartedAtRef = useRef(0);
  const lastSpeechAtRef = useRef(0);
  const sttTrackedRef = useRef(false);
  const autoStructureRef = useRef(false);
  const silenceGuardRef = useRef(null);
  const silenceTimeoutActionRef = useRef(() => {});
  const transcriptInputRef = useRef(null);
  const amplitudeTimerRef = useRef(null);
  const amplitudeSamplesRef = useRef([]);
  const amplitudeMeterErrorLoggedRef = useRef(false);
  const recorderPrewarmedRef = useRef(false);
