      if (Capacitor.getPlatform() !== "ios") return;
      if (!shouldInterruptServerRecordingOnPause({ engineMode: VOICE_ENGINE_MODE, recording: recordingActiveRef.current, stopping: backgroundStopRef.current })) return;
